function migrate(o){
  if(!o||typeof o!=="object"||!o.cards||typeof o.cards!=="object"||Array.isArray(o.cards))throw new Error("Bu veri YDS Kelime Atölyesi ilerlemesine benzemiyor.");
  let v=o.dataVersion==null?1:o.dataVersion;
  if(typeof v!=="number"||!isFinite(v))throw new Error("Veri sürümü (dataVersion) geçersiz.");
  if(v>DATA_VERSION)throw new Error(`Bu yedek daha yeni bir sürümden (v${v}). Uygulamanın bu sürümü v${DATA_VERSION}'e kadar okuyabilir.`);
  if(v<2){
    const n=blankState();
    for(const id in o.cards){const c=o.cards[id];n.cards[id]=Object.assign(cardDefaults(),c,{hist:[],cdays:c.correct>0&&c.last!=null?[c.last]:[],sk:{},rat:[],lastCorrect:c.correct>0?c.last:null,confErr:0,masteredOn:null})}
    n.days=o.days||{};n.streak=o.streak||0;n.last=o.last??null;n.doneDay=o.doneDay??null;
    const GM={artmak:"increase",azalmak:"decrease",onemli:"important",sebep:"cause",engel:"prevent",koru:"maintain",elde:"achieve",goster:"show",arastir:"research",degis:"change",sifat:"amount"};
    for(const g in o.grp||{}){const k=GM[g];if(k){n.grp[k]=n.grp[k]||{c:0,w:0};n.grp[k].c+=o.grp[g].c||0;n.grp[k].w+=o.grp[g].w||0}}
    const TM={mean:"mean",syn:"syn",ctx:"ctx",guess:"ctx"};
    for(const t in o.typ||{}){const k=TM[t];if(k){n.err[k].c+=o.typ[t].c||0;n.err[k].w+=o.typ[t].w||0}}
    n.conf=o.conf||{};
    n.settings.newPerDay=(o.newPerDay&&o.newPerDay!==12)?o.newPerDay:15;
    n.dataVersion=2;o=n;v=2;
  }
  if(v<3){
    // v2 → v3: hafıza gücü (stab), son tekrar günü, en iyi seri ve yeni alanlar
    for(const id in o.cards){const c=o.cards[id];
      if(c.stab==null||!(c.stab>0))c.stab=c.reps>0?Math.max(.5,LAD[Math.min(7,Math.max(0,c.step|0))]*1.5):0;
      if(c.lastRev==null)c.lastRev=c.last!=null?c.last:(c.reps>0?c.first:null);
      if(!c.exp||typeof c.exp!=="object")c.exp={};
      if(c.hardPending==null)c.hardPending=false;
    }
    o.best=Math.max(o.best||0,o.streak||0);
  }
  if(v<4){
    // v3 → v4: soru tanışıklığı (eski bankSeen'den), okuma seviyesi, kişisel aralıklar, Hard takibi; mevcut kullanıcılar için karşılama atlanır
    const qs={};for(const id of o.bankSeen||[])qs[id]={n:1,last:null,c:0,w:0,lastOk:null};
    o.qstats=Object.assign(qs,o.qstats||{});
    if(!o.profile&&(Object.keys(o.cards).length||Object.keys(o.days||{}).length))o.profile={skipped:true};
  }
  if(v<5){
    // v4 → v5: olay günlüğü, tahmin kalibrasyonu, oturum günlüğü; geçmiş veriler scheduler-v1 ile üretildi olarak işaretlenir
    o.algHistory=(o.algHistory||[]).concat([{v:"scheduler-v1",to:today()}]);o.alg=ALG;
    for(const id in o.cards){const c=o.cards[id];if(c.masteredOn!=null&&c.stableOn==null&&today()-c.masteredOn>=45)c.stableOn=c.masteredOn+45}
  }
  const b=blankState();
  for(const k in b)if(o[k]===undefined)o[k]=b[k];
  o.settings=Object.assign(b.settings,o.settings||{});
  o.err=o.err||{};for(const k in b.err)o.err[k]=Object.assign({c:0,w:0},o.err[k]||{});
  o.self=Object.assign(b.self,o.self||{});
  o.spacing=Object.assign(b.spacing,o.spacing||{});o.spStats=Object.assign(b.spStats,o.spStats||{});o.hardStats=Object.assign(b.hardStats,o.hardStats||{});
  if(!o.qstats||typeof o.qstats!=="object")o.qstats={};if(!Array.isArray(o.readHist))o.readHist=[];if(!Array.isArray(o.placeKnown))o.placeKnown=[];
  o.readLevel=Math.min(2,Math.max(0,o.readLevel??1));
  if(!Array.isArray(o.ev))o.ev=[];if(!o.dailyStats||typeof o.dailyStats!=="object")o.dailyStats={};if(!Array.isArray(o.sessLog))o.sessLog=[];
  if(!Array.isArray(o.calib)||o.calib.length!==5)o.calib=b.calib;o.schedWin=Object.assign(b.schedWin,o.schedWin||{});o.schedTot=Object.assign(b.schedTot,o.schedTot||{});
  o.alg=ALG;
  for(const id in o.cards)o.cards[id]=Object.assign(cardDefaults(),o.cards[id]);
  if(!Array.isArray(o.fav))o.fav=[];if(!Array.isArray(o.queue))o.queue=[];if(!Array.isArray(o.mini))o.mini=[];if(!Array.isArray(o.ctxRecent))o.ctxRecent=[];if(!Array.isArray(o.bankSeen))o.bankSeen=[];
  o.ctxLevel=Math.min(3,Math.max(1,o.ctxLevel|0||1));
  o.best=Math.max(o.best||0,o.streak||0);
  o.dataVersion=DATA_VERSION;
  return o;
}
/* Yedek doğrulama: hatalı yedek mevcut veriyi asla bozmaz (kopya üzerinde çalışır). */
function validateBackup(text){
  let o;try{o=JSON.parse(text)}catch(e){throw new Error("Metin geçerli bir JSON değil. Yedeğin tamamını kopyaladığından emin ol.")}
  if(!o||typeof o!=="object")throw new Error("Yedek bir nesne değil.");
  const data=o.data&&typeof o.data==="object"?o.data:o;
  if(data.dataVersion!=null&&(typeof data.dataVersion!=="number"||!isFinite(data.dataVersion)))throw new Error("dataVersion alanı sayı değil.");
  if(!data.cards||typeof data.cards!=="object"||Array.isArray(data.cards))throw new Error("Zorunlu alan eksik: cards.");
  for(const id in data.cards){const c=data.cards[id];
    if(!c||typeof c!=="object")throw new Error(`“${id}” kartı bozuk.`);
    for(const f of ["step","due","reps"])if(typeof c[f]!=="number"||!isFinite(c[f]))throw new Error(`“${id}” kartında zorunlu alan eksik ya da hatalı: ${f}.`);
  }
  if(data.mini!=null&&!Array.isArray(data.mini))throw new Error("mini alanı liste olmalı.");
  if(data.days!=null&&typeof data.days!=="object")throw new Error("days alanı hatalı.");
  if(o.dataVersion>=5){for(const f of ["questionStats","dailyStats","calibrationStats"])if(o[f]!=null&&typeof o[f]!=="object")throw new Error(`${f} alanı hatalı.`);
    if(typeof o.algorithmVersion!=="string")throw new Error("algorithmVersion alanı eksik.")}
  if(data.ev!=null&&!Array.isArray(data.ev))throw new Error("ev alanı liste olmalı.");
  const raw=JSON.parse(JSON.stringify(data));
  if(o.questionStats&&typeof o.questionStats==="object"&&!raw.qstats)raw.qstats=o.questionStats;
  if(o.dailyStats&&typeof o.dailyStats==="object"&&!raw.dailyStats)raw.dailyStats=o.dailyStats;
  const m=migrate(raw);
  let unknown=0;for(const id in m.cards)if(!BY[id]){unknown++;delete m.cards[id]}
  const n=Object.keys(m.cards).length;
  return{state:m,summary:`${n} kelimenin ilerlemesi, ${m.fav.length} favori ve ${m.mini.length} Mini YDS sonucu bulundu (veri sürümü v${data.dataVersion||1} → v${DATA_VERSION})${unknown?`; havuzda olmayan ${unknown} kayıt atlandı`:""}.`};
}
function learningState(){const t=today(),sm=statusMap(),o={};for(const id in S.cards){if(!BY[id])continue;const tf=transferScore(id);o[id]={s:sm[id],m:masteryScore(id,t),tr:tf?tf.score:null,p:Math.round(100*recallProbability(id,t))/100,tags:[...wordTags(id)]}}return o}
/* Yedek: ham kişisel veri çoğaltılmaz. Soru ve günlük istatistikler yalnızca üst düzeyde tutulur; 30 günden eski ayrıntılı olaylar özet olarak yazılır. */
function exportText(){
  flush();const data=JSON.parse(JSON.stringify(S));const daily=JSON.parse(JSON.stringify(S.dailyStats||{}));
  const lim=today()-30,keep=[];
  for(const e of data.ev||[]){const d=evDay(e[0]);if(d>=lim){keep.push(e);continue}const x=daily[d]||(daily[d]={e:{},q:0,c:0,rt:0,rtn:0});const ty=EVT[e[1]]||"?";x.e[ty]=(x.e[ty]||0)+1;if(ty==="questionCorrect"||ty==="questionWrong"){x.q++;if(ty==="questionCorrect")x.c++}if(e[6]!=null){x.rt+=e[6];x.rtn++}}
  data.ev=keep;delete data.qstats;delete data.dailyStats;
  return JSON.stringify({app:"YDS Kelime Atölyesi",dataVersion:DATA_VERSION,algorithmVersion:ALG,exportedAt:new Date().toISOString(),
    learningState:learningState(),questionStats:S.qstats,dailyStats:daily,
    calibrationStats:{calib:S.calib,brier:S.brier,schedWin:S.schedWin,schedTot:S.schedTot,spacing:S.spacing,schedLog:S.schedLog,hardStats:S.hardStats,ratingGap:S.ratingGap,rtNext:S.rtNext,gapStats:S.gapStats,leechRec:S.leechRec,mastCheck:S.mastCheck,delayed:S.delayed,immediate:S.immediate},
    realUserCalibration:realCalibration(),report30:calDay()>=30?report30():null,data})}
function load(){
  try{const r=localStorage.getItem(KEY);if(r)return migrate(JSON.parse(r))}catch(e){}
  try{const r=localStorage.getItem(OLDKEY);if(r){const m=migrate(JSON.parse(r));try{localStorage.setItem(KEY,JSON.stringify(m))}catch(e){}return m}}catch(e){}
  return blankState();
}
/* Kontrollü yazma: değişiklikler 400 ms içinde toplanıp tek seferde yazılır. */
let REV=0,saveTimer=null;
function save(){REV++;if(saveTimer)return;saveTimer=setTimeout(flush,400)}
function flush(){if(saveTimer){clearTimeout(saveTimer);saveTimer=null}try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}}
let S=load();
let tab="home",SS=null,sheet=null,wf="all",wq="",wlimit=120,summary=null;
const MEMO={};
function memo(k,fn){const key=k+"|"+REV+"|"+today();if(MEMO[k]&&MEMO[k].key===key)return MEMO[k].v;const v=fn();MEMO[k]={key,v};return v}

/* ================= YARDIMCILAR ================= */
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const pct=x=>Math.round(x*100);
const exHtml=w=>esc(w.ex).replace(/\*([^*]+)\*/,"<mark>$1</mark>");
const clsOf=w=>{if(w.g[0]==="l")return"link";const p=w.pos.split("/")[0];return p.startsWith("adj")?"adj":p.startsWith("adv")?"adv":p.startsWith("n")?"n":"v"};
const posCls=p=>p.startsWith("adj")?"adj":p.startsWith("adv")?"adv":p.startsWith("n")?"n":"v";
function trKeys(w){return new Set((w.tr+" / "+(w.tr2||"")).toLocaleLowerCase("tr-TR").split(/[\/,;()]/).map(s=>s.trim().split(" ")[0]).filter(s=>s.length>3))}
function trOverlap(a,b){const A=trKeys(a);for(const k of trKeys(b))if(A.has(k))return true;return false}
const isFav=id=>S.fav.includes(id);
const isLink=w=>w.g[0]==="l";
function famForms(w){const k=clsOf(w);const out=[];for(const [f,p] of w.fam){if(f===w.w||p.includes("pl"))continue;if(p.split("/").some(x=>posCls(x)===k))continue;if(!out.includes(f))out.push(f)}return out.slice(0,3)}
function bump(o,k,ok){(o[k]=o[k]||{c:0,w:0})[ok?"c":"w"]++}
const accOf=x=>x&&x.c+x.w?x.c/(x.c+x.w):null;
function dayRec(t){t=t??today();const d=S.days[t]||(S.days[t]={n:0,r:0,q:0,c:0,m:0});d.sk=d.sk||{};d.g=d.g||{};return d}

/* ================= HAFIZA MODELİ ================= */
/* retrieval strength: şu an hatırlama olasılığı R = e^(−geçen gün / stab).
   storage strength: kelimenin uzun süreli hafızadaki sağlamlığı 1 − e^(−stab/30). */
function retr(c,t){if(!c||c.lastRev==null||!(c.stab>0))return 0;const e=Math.max(0,(t??today())-c.lastRev);return Math.exp(-e/Math.max(.3,c.stab))}
function storageStr(c){return c&&c.stab>0?1-Math.exp(-c.stab/30):0}
function updateStab(c,r){
  const t=today();
  if(!(c.stab>0)||c.lastRev==null){c.stab={again:.4,hard:.8,good:1.5,easy:3}[r];c.lastRev=t;return}
  const same=c.lastRev===t,R=retr(c,t);
  let m;
  if(same)m={again:.7,hard:1,good:1.1,easy:1.2}[r];        // aynı gün tekrar uzun süreli hafızaya az katkı sağlar
  else if(r==="again")m=.45;
  else if(r==="hard")m=1.15;                                 // Hard: yavaş büyüme, unutma hızlı kalır
  else if(r==="good")m=1.6+1.2*(1-R);                        // zor hatırlanan doğru cevap daha çok güçlendirir
  else m=2.3+1.5*(1-R);                                      // Easy: unutma eğrisi en çok yavaşlar
  c.stab=Math.min(400,Math.max(.3,c.stab*m));c.lastRev=t;
}
function quizStab(c,ok){const t=today();if(!(c.stab>0)){c.stab=ok?1:.4;c.lastRev=t;return}if(c.lastRev===t){c.stab=Math.min(400,c.stab*(ok?1.02:.85));return}c.stab=Math.min(400,Math.max(.3,c.stab*(ok?1.1:.75)));c.lastRev=t}

/* masteryScore 0–100: bileşenler kelime tipine göre ağırlıklandırılır, zamanla (retrieval düştükçe) azalır. */
function weightsFor(w){
  if(isLink(w))return{mean:20,syn:10,ctx:50,coll:0,fam:0,ret:20};
  const x={mean:30,syn:20,ctx:25,coll:10,fam:5,ret:10};
  if(!w.col.length){x.ctx+=x.coll;x.coll=0}
  if(famForms(w).length<2){x.mean+=x.fam;x.fam=0}
  if(!w.syn.length){x.ctx+=x.syn;x.syn=0}
  return x;
}
function masteryParts(id,t){
  const c=S.cards[id],w=BY[id];if(!c||!w)return null;
  const sm=k=>{const x=c.sk[k];return x&&x.c+x.w?(x.c+.5)/(x.c+x.w+1):null};
  const h=c.hist.slice(-8);const hm=h.length?(h.reduce((a,b)=>a+b,0)+.5)/(h.length+1):0;
  const skm=sm("mean");const mean=skm==null?hm:(hm*.6+skm*.4);
  const est=v=>v==null?mean*.6:v;
  const R=retr(c,t);
  return{mean,syn:est(sm("syn")),ctx:est(sm("ctx")),coll:est(sm("coll")),fam:est(sm("fam")),ret:.5*Math.min(1,c.cdays.length/4)+.5*storageStr(c),R,storage:storageStr(c)};
}
/* Yumuşak unutma etkisi: son tekrardan bu yana geçen güne göre. Tipik kalıcı kelimede 30 gün ≈ −8%, 60 gün ≈ −15%.
   Easy ile güçlenen (yüksek stab) kelimelerde daha yavaş, Hard ile kalanlarda daha hızlı. Alt sınır %50. */
function decayFactor(c,t){if(!c||c.lastRev==null)return 1;const e=Math.max(0,(t??today())-c.lastRev);return Math.max(.5,Math.exp(-e/(250+8*Math.min(400,c.stab||0))))}
function masteryScore(id,t){
  const p=masteryParts(id,t);if(!p)return 0;
  const w=BY[id],x=weightsFor(w),c=S.cards[id];
  const decay=decayFactor(c,t);
  let s=0;for(const k of ["mean","syn","ctx","coll","fam"])s+=x[k]*p[k]*decay;
  s+=x.ret*p.ret;
  s-=Math.min(10,(c.confErr||0)*2);
  const rs=rtScore(c);if(rs!=null)s+=4*(rs-.5);        // tepki süresi: düşük ağırlıklı yardımcı sinyal (±2)
  return Math.max(0,Math.min(100,Math.round(s)));
}
/* ===== v5: tepki süresi, hatırlama olasılığı, iç etiketler, aktarım ===== */
const RT_MIN=300,RT_MAX=60000,RT_CAP=30000;
function validRt(ms,hidden){if(hidden||ms==null||!isFinite(ms)||ms<RT_MIN||ms>RT_MAX){S.rtStats.dropped++;return null}return Math.min(RT_CAP,ms)}
const RT_B=ms=>ms<3000?"<3":ms<7000?"3–7":ms<15000?"7–15":"15–30";
function noteRt(c,rt){if(rt==null||!c)return;c.rtB={b:RT_B(rt),d:today()};c.rt=c.rt==null?rt:Math.round(.7*c.rt+.3*rt);c.rtn=(c.rtn||0)+1;S.rtStats.n++;S.rtStats.sum+=rt}
function rtScore(c){if(!c||c.rt==null||(c.rtn||0)<2)return null;return 1-Math.min(1,Math.max(0,(c.rt-3000)/15000))}
const sigm=z=>1/(1+Math.exp(-z)),logit=p=>Math.log(p/(1-p));
function smAcc(x,prior){return x&&x.c+x.w?(x.c+(prior??.6))/(x.c+x.w+1):null}
/* recallProbability: bugün hatırlama olasılığı (0–1). Girdiler: retrieval, ustalık, depolama, son puan, Hard geçmişi, son hatalar, tepki süresi, bağlam/eş anlam başarısı. */
function recallProbability(id,t){
  const c=S.cards[id];if(!c||!c.reps&&!c.correct)return 0;
  t=t??today();const R=retr(c,t);
  let z=logit(Math.min(.97,Math.max(.03,R)));
  const ms=masteryScore(id,t);z+=1.1*(ms/100-.5);
  z+=.8*(storageStr(c)-.25);
  const last=c.rat[c.rat.length-1];z+=last==="e"?.35:last==="h"?-.35:last==="a"?-.6:0;
  if(c.hardAt!=null)z-=.25;
  const h=c.hist.slice(-5);if(h.length)z-=1.2*(1-h.reduce((a,b)=>a+b,0)/h.length);
  const rs=rtScore(c);if(rs!=null)z+=.4*(rs-.5);
  const cs=[smAcc(c.sk.ctx),smAcc(c.sk.syn)].filter(x=>x!=null);if(cs.length)z+=.6*(cs.reduce((a,b)=>a+b,0)/cs.length-.6);
  return Math.min(.99,Math.max(.01,sigm(z)));
}
/* Tahmin kalibrasyonu: tahmin edilen olasılık (5 aralık) ile gerçek sonuç karşılaştırılır. */
function calibAdd(p,ok){const i=Math.min(4,Math.floor(p*5));const b=S.calib[i];b.n++;if(ok)b.ok++;b.ps+=p;S.brier.n++;S.brier.sum+=(p-(ok?1:0))**2}
function calibReport(){return S.calib.map((b,i)=>({range:`${i*20}–${i*20+20}`,n:b.n,pred:b.n?b.ps/b.n:null,real:b.n?b.ok/b.n:null}))}
/* Aktarım (Transfer) puanı: kartta bilmenin sınav benzeri sorulara taşınması. Bileşenler: anlam 20, eş anlam 15, bağlam 25, okuma 20, cloze 10, Mini YDS kelime 10. */
const TR_W={mean:20,syn:15,ctx:25,read:20,clz:10,yv:10};
function transferScore(id){
  const c=S.cards[id];if(!c)return null;const tr=c.tr||{};
  const parts={mean:smAcc(c.sk.mean),syn:smAcc(c.sk.syn),ctx:smAcc(c.sk.ctx),read:smAcc(tr.read),clz:smAcc(tr.clz),yv:smAcc(tr.yv)};
  if(parts.mean==null){const h=c.hist.slice(-6);if(h.length)parts.mean=h.reduce((a,b)=>a+b,0)/h.length}
  if(parts.ctx==null&&parts.read==null&&parts.clz==null&&parts.yv==null)return null;
  let s=0,w=0;for(const k in TR_W)if(parts[k]!=null){s+=TR_W[k]*parts[k];w+=TR_W[k]}
  return{score:Math.round(100*s/w),parts};
}
function cnt(x){return x?x.c+x.w:0}
/* İç etiketler (kullanıcıya gösterilmez; zamanlayıcı kullanır) */
function wordTags(id,t){
  return memo("tags:"+id,()=>{
    const c=S.cards[id],out=new Set();if(!c)return out;t=t??today();
    const tr=c.tr||{},h=c.rat.slice(-6).map(x=>x==="g"||x==="e"?1:x==="h"?.5:0);   // doğrudan hatırlama: kart puanları + anlam soruları
    const meanN=cnt(c.sk.mean)+h.length,meanA=meanN?((c.sk.mean?c.sk.mean.c:0)+h.reduce((a,b)=>a+b,0))/meanN:null;
    const use={c:(c.sk.ctx?c.sk.ctx.c:0)+(tr.read?tr.read.c:0)+(tr.clz?tr.clz.c:0),w:(c.sk.ctx?c.sk.ctx.w:0)+(tr.read?tr.read.w:0)+(tr.clz?tr.clz.w:0)};
    const useA=cnt(use)?use.c/cnt(use):null;
    const direct={c:(c.sk.mean?c.sk.mean.c:0),w:(c.sk.mean?c.sk.mean.w:0)};h.forEach(x=>{if(x>=1)direct.c++;else direct.w++});
    if(meanN>=3&&meanA>.85&&cnt(use)>=3&&useA<.6)out.add("RecognitionGap");
    if(cnt(use)>=3&&useA>=.8&&cnt(direct)>=3&&direct.c/cnt(direct)<.6)out.add("RecallGap");
    if(cnt(c.sk.ctx)>=3&&c.sk.ctx.c/cnt(c.sk.ctx)<.6)out.add("ContextWeak");
    if(cnt(c.sk.syn)>=3&&c.sk.syn.c/cnt(c.sk.syn)<.6)out.add("SynonymWeak");
    if(c.due<t-2)out.add("Overdue");
    if(c.masteredOn!=null&&c.stableOn==null&&t-c.masteredOn<45)out.add("FragileMastered");
    if(c.reps+c.correct+c.wrong>=8&&masteryScore(id,t)<45)out.add("Leech");
    return out});
}
function taggedIds(tag){return memo("tagged:"+tag,()=>Object.keys(S.cards).filter(id=>BY[id]&&wordTags(id).has(tag)))}
/* Kişisel karıştırma çiftleri: gerçek hatalardan (her iki yönde toplam ≥ 3) */
const CONF_MIN=3;
function confusionCount(a,b){return((S.conf[a]||{})[b]||0)+((S.conf[b]||{})[a]||0)}
function personalPairs(){
  return memo("ppairs",()=>{const seen=new Set(),out=[];
    for(const a in S.conf)for(const b in S.conf[a]){if(!BY[a]||!BY[b]||a===b)continue;const k=pairKey(a,b);if(seen.has(k)||PAIRMAP[k])continue;seen.add(k);
      const n=confusionCount(a,b);if(n>=CONF_MIN)out.push({ws:[a,b].sort(),n,personal:true,tip:`${a} = ${BY[a].tr.split(" / ")[0]} · ${b} = ${BY[b].tr.split(" / ")[0]}. Bu ikisini ${n} kez karıştırdın; farkı örnek cümlelerde gör.`})}
    return out.sort((x,y)=>y.n-x.n)});
}
function mnemonic(w){
  const tr0=w.tr.split(" / ")[0],syn=w.syn[0],ff=famForms(w)[0];
  return`${w.w} → “${tr0}”${syn?` · yakın: ${syn}`:""}${ff?` · aile: ${ff}`:""}${w.col[0]?` · kalıp: ${w.col[0]}`:""}`;
}
function mastery(c){
  if(!c)return{days:false,syn:false,ctx:false,rat:false};
  const r=c.rat.slice(-3);
  return{days:c.cdays.length>=3,syn:!!(c.sk.syn&&c.sk.syn.c>=1),ctx:!!(c.sk.ctx&&c.sk.ctx.c>=1),rat:r.length>=2&&r.filter(x=>x==="g"||x==="e").length>=2};
}
function criteriaMet(c){const m=mastery(c);return m.days&&m.syn&&m.ctx&&m.rat}
/* Kalıcı: ölçütler + puan ≥ 75 ile girilir; puan 60'ın altına düşerse (unutma) kalıcılıktan çıkar. */
function isMasteredId(id,t){const c=S.cards[id];if(!c||!criteriaMet(c))return false;const s=masteryScore(id,t);return c.masteredOn?s>=60:s>=75}
function weakScore(id){
  const c=S.cards[id];if(!c)return 0;
  const att=c.correct+c.wrong;if(att+c.reps<2)return 0;
  const h=c.hist.slice(-5);const recentErr=h.length?1-h.reduce((a,b)=>a+b,0)/h.length:0;
  const errRate=att?c.wrong/att:0;
  const t=today();const timeF=c.lastCorrect==null?1:Math.min(1,(t-c.lastCorrect)/14);
  const sk=k=>{const x=c.sk[k];return x&&x.c+x.w?x.w/(x.c+x.w):0};
  const s=100*(.30*recentErr+.18*errRate+.10*timeF+.14*sk("ctx")+.12*sk("syn")+.08*Math.min(1,(c.confErr||0)/2)+.08*Math.min(1,c.lapses/3));
  return Math.round(Math.min(100,s));
}
function isWeak(id){const c=S.cards[id];if(!c)return false;return weakScore(id)>=40&&(c.correct+c.wrong>=2||c.lapses>=1)}
function statusOf(id){
  const c=S.cards[id];if(!c)return"new";
  if(isWeak(id))return"weak";
  if(isMasteredId(id))return"mastered";
  if((masteryScore(id)>=50&&c.reps+c.correct>=2)||c.cdays.length>=2||c.step>=2)return"familiar";
  return"learning";
}
function statusMap(){return memo("status",()=>{const m={};for(const w of W)m[w.id]=statusOf(w.id);return m})}
const STATUS={new:"Yeni",learning:"Öğreniliyor",weak:"Zayıf",familiar:"Tanıdık",mastered:"Kalıcı"};
function groupErr(){const o={};for(const g in S.grp){const x=S.grp[g],n=x.c+x.w;if(n>=4)o[g]={err:x.w/n,n}}return o}
function focusGroup(){const e=groupErr();let b=null;for(const g in e){if(GROUPS[g]&&e[g].err>=.3&&(!b||e[g].err>b.err))b={g,err:e[g].err}}return b}
function lapseRate(){let r=0,l=0;for(const id in S.cards){const c=S.cards[id];if(c.reps>1){r+=c.reps-1;l+=c.lapses}}return r>=10?l/r:null}
function weakestSkill(min){let b=null;for(const k in SKILLS){const x=S.err[k],n=x.c+x.w;if(n>=(min||6)){const a=x.c/n;if(!b||a<b.a)b={k,a}}}return b&&b.a<.8?b:null}
function weakList(){return memo("weak",()=>Object.keys(S.cards).filter(id=>BY[id]&&isWeak(id)).sort((a,b)=>weakScore(b)-weakScore(a)))}
function dueList(){const t=today();return Object.keys(S.cards).filter(id=>BY[id]&&S.cards[id].due<=t&&!(S.cards[id].restUntil>t))}
function selfAccuracy(){const v=S.self.verify||{n:0};if(v.n>=5)return v.ok/v.n;const k=S.self.know;return k.n>=5?k.ok/k.n:null}

/* ================= YENİ KELİME SEÇİMİ (ydsPriorityScore) ================= */
function pickNew(n,opts){
  if(n<=0)return[];
  opts=opts||{};const out=[];
  for(const id of S.queue){if(out.length>=n)break;if(BY[id]&&!S.cards[id])out.push(id)}
  // Yerleştirme testinde zaten bildiğin kelimeler biraz geriye alınır
  const known=new Set(S.placeKnown||[]),ep=w=>w.p-(known.has(w.id)?15:0);
  const unseen=W.filter(w=>!S.cards[w.id]&&!out.includes(w.id)).sort((a,b)=>ep(b)-ep(a));
  const win=unseen.slice(0,Math.max((n-out.length)*3,30));
  const byG={};win.forEach(w=>(byG[w.g]=byG[w.g]||[]).push(w));
  const f=focusGroup();
  let gs=Object.keys(byG).sort((a,b)=>ep(byG[b][0])-ep(byG[a][0]));
  if(f&&byG[f.g])gs=[f.g,...gs.filter(g=>g!==f.g)];
  let links=out.filter(id=>isLink(BY[id])).length;const maxLinks=opts.maxLinks??3;
  // Anlamsal girişim kontrolü: aynı anlam merdiveninden en fazla 3, aynı kümeden en fazla 3 yeni kelime
  const ladCnt={},grpCnt={};out.forEach(id=>{grpCnt[BY[id].g]=(grpCnt[BY[id].g]||0)+1;(LADBY[id]||[]).forEach(L=>ladCnt[L.id]=(ladCnt[L.id]||0)+1)});
  const fits=w=>(grpCnt[w.g]||0)<3&&(LADBY[w.id]||[]).every(L=>(ladCnt[L.id]||0)<3);
  const take=w=>{out.push(w.id);grpCnt[w.g]=(grpCnt[w.g]||0)+1;(LADBY[w.id]||[]).forEach(L=>ladCnt[L.id]=(ladCnt[L.id]||0)+1)};
  for(const g of gs)for(const w of byG[g].slice(0,3)){if(out.length>=n)break;if(!fits(w))continue;if(isLink(w)){if(links>=maxLinks)continue;links++}take(w)}
  for(const w of unseen){if(out.length>=n)break;if(out.includes(w.id)||!fits(w))continue;if(isLink(w)){if(links>=maxLinks)continue;links++}take(w)}
  return out;
}
function adaptRatios(){
  const r=Object.assign({},RATIOS),why=[];
  const a=k=>{const x=S.err[k];return x.c+x.w>=8?x.c/(x.c+x.w):null};
  const sa=a("syn"),ca=a("ctx"),fa=a("conf");
  if(sa!=null&&sa<.7){r.syn+=.05;r.due-=.05;why.push("eş anlam")}
  if(ca!=null&&ca<.7){r.ctx+=.05;r.new-=.05;why.push("bağlam")}
  if((fa!=null&&fa<.7)||Object.keys(S.conf).length>=3){r.conf+=.05;r.weak-=.05;why.push("karıştırılan kelimeler")}
  return{r,why};
}
function spreadOverflow(ids,perDay){const t=today(),out={};ids.forEach((id,i)=>{out[id]=t+1+Math.floor(i/Math.max(5,perDay))});return out}
function plan(mode){return memo("plan:"+mode+":"+S.settings.length+":"+S.settings.newPerDay+":"+S.noNewDay+":"+S.doneDay,()=>planRaw(mode))}
function planRaw(mode){
  const t=today(),cfg=LEN[S.settings.length]||LEN.normal,U=cfg.cap;
  const {r:R,why}=adaptRatios();
  const ret=id=>retr(S.cards[id],t);
  const rp={};const prob=id=>rp[id]??(rp[id]=recallProbability(id,t));
  // Karar motoru: önce en yüksek öğrenme değeri (gecikmiş + düşük hatırlama olasılığı, aktarım açığı, zayıflık, YDS önceliği)
  const val={};const lv=id=>val[id]??(val[id]=learningValueScore(id,t,prob(id)));
  const dueAll=dueList().sort((a,b)=>(lv(b)-lv(a))||(prob(a)-prob(b)));
  const weakAll=weakList();
  let n=Math.round(S.settings.newPerDay*cfg.nm),note=null;
  if(S.firstNew&&!Object.keys(S.cards).length)n=Math.min(n,S.firstNew);   // karşılama: yalnızca ilk oturumun yükü
  if(dueAll.length>100){n=Math.min(n,5);note=`Tekrar bekleyen ${dueAll.length} kelime var; bugün yeni kelime sayısı ${n}'e düşürüldü.`}
  else if(dueAll.length>60){n=Math.min(n,10);note=`Tekrar bekleyen ${dueAll.length} kelime var; bugün yeni kelime sayısı ${n}'a düşürüldü.`}
  if(S.noNewDay===t&&mode==="daily"){n=0;note="Bugün yalnızca tekrar yapıyorsun."}
  if(mode==="daily"&&S.doneDay===t)n=0;
  if(mode==="extra")n=5;
  const revUnits=U*(1-R.new),share=k=>revUnits*R[k]/(1-R.new);
  const weak=weakAll.slice(0,Math.max(mode==="extra"?8:0,Math.floor(share("weak")/UNIT.weak)));
  const synN=Math.round(share("syn")/UNIT.q),ctxN=Math.round(share("ctx")/UNIT.q),confN=Math.max(0,Math.round(share("conf")/UNIT.conf));
  let dueUnits=revUnits-weak.length*UNIT.weak-synN-ctxN-confN*UNIT.conf;
  const dueRest=dueAll.filter(id=>!weak.includes(id));
  const maxRev=mode==="extra"?0:Math.max(0,Math.floor(dueUnits/UNIT.flash));
  const review=dueRest.slice(0,maxRev);
  const overflow=dueRest.slice(review.length);
  let early=[];
  if(mode!=="extra"&&review.length<maxRev){
    early=Object.keys(S.cards).filter(id=>BY[id]&&S.cards[id].due>t&&S.cards[id].due<=t+3&&!weak.includes(id)&&ret(id)<.6).sort((a,b)=>ret(a)-ret(b)).slice(0,Math.min(10,maxRev-review.length));
  }
  // Gecikmeli aktarım kontrolleri: 3–7 gün önce öğrenilen, bugün tekrarı olmayan kelimeler (yeni kelimelerden önce)
  const dtc=mode==="extra"?[]:Object.keys(S.cards).filter(id=>{const c=S.cards[id];return BY[id]&&c.first<=t-3&&c.first>=t-7&&c.due>t&&!weak.includes(id)&&!(c.restUntil>t)&&c.trD==null}).sort((a,b)=>lv(b)-lv(a)).slice(0,3);
  const used=review.length*UNIT.flash+early.length*UNIT.flash+weak.length*UNIT.weak+synN+ctxN+confN*UNIT.conf+dtc.length*UNIT.q;
  const newCap=Math.max(mode==="extra"?5:0,Math.floor((U-used)/UNIT.new));
  const newIds=pickNew(Math.min(n,newCap));
  if(newIds.length<n&&!note&&n>0&&newCap<n)note=`Bugünkü kapasite dolu olduğu için yeni kelime sayısı ${newIds.length} ile sınırlandı.`;
  const demand=(dueAll.length*UNIT.flash+Math.min(weakAll.length,12)*UNIT.weak+n*UNIT.new)/U;
  const loadScore=(used+newIds.length*UNIT.new)/U;
  const load=demand<.4?"light":demand<=1?"normal":"heavy";
  const secs=newIds.length*95+(review.length+early.length)*14+weak.length*45+(synN+ctxN)*18+confN*35+cfg.mini*22;
  return{newIds,review,early,weak,dueAll,overflow,synN,ctxN,confN,dtc,minutes:Math.max(1,Math.round(secs/60)),note,cfg,ratios:R,why,load,demand,loadScore,cap:U};
}
const LOAD={light:"Hafif",normal:"Normal",heavy:"Yoğun"};

/* ================= ZAMANLAMA ================= */
function ensure(id){return S.cards[id]||(S.cards[id]=cardDefaults())}
function nextStep(c,r,fresh,hadAgain){
  if(r==="again")return{step:fresh?0:1,due:1,lapse:!fresh};
  if(r==="hard")return{step:fresh?1:Math.max(1,c.step-1),due:1};
  if(hadAgain)return{step:1,due:1};
  if(r==="good"){const s=fresh?1:Math.min(c.step+1,7);return{step:s,due:LAD[s]}}
  const s=fresh?2:Math.min(c.step+2,7);return{step:s,due:LAD[s]};
}
/* Kişisel tekrar aralıkları: Easy / Good / Hard çarpanları kullanıcının gerçek hatırlama oranına göre yavaşça uyarlanır. */
/* Kalibrasyon güvenlik sınırları: Easy 0,80–1,30 · Good 0,80–1,25 · Hard 0,70–1,15; adım ±%5; aynı çarpan 3 günden sık değişmez */
const SP_TARGET={easy:.92,good:.88,hard:.78},SP_RANGE={easy:[.8,1.3],good:[.8,1.25],hard:[.7,1.15]},SCHED_GAP=3;
const HARD_BASE=s=>s>=5?3:s>=3?2:1;
function personalDue(r,x){if(r==="again")return x.due;const m=S.spacing[r]||1;return Math.max(1,Math.round((r==="hard"?HARD_BASE(x.step):x.due)*m))}
/* Zamanlayıcı kalibrasyonu (scheduler-v2): bir önceki puana göre hedef hatırlama aralıkları.
   Good %80–90, Easy %90+, Hard %60–75. En az 20 örnek birikmeden çarpan değişmez; her değişiklikten sonra pencere yarıya iner. */
const SCHED_TGT={good:[.80,.90],easy:[.90,.97],hard:[.60,.75]},SCHED_MIN=20;
function adaptSpacing(c,r){
  const t=today();if(!c.reps||c.lastRev==null||c.lastRev>=t)return;
  const key={e:"easy",g:"good",h:"hard"}[c.rat[c.rat.length-1]];if(!key)return;
  const ok=r==="good"||r==="easy",st=S.schedWin[key],tot=S.schedTot[key];
  st.n++;if(ok)st.ok++;tot.n++;if(ok)tot.ok++;
  const old=S.spStats[key];old.n++;old.ema=.92*old.ema+.08*(ok?1:0);
  if(st.n<SCHED_MIN)return;
  if(S.schedLast[key]!=null&&t-S.schedLast[key]<SCHED_GAP)return;
  const rate=st.ok/st.n,[lo,hi]=SCHED_TGT[key],[mn,mx]=SP_RANGE[key],from=S.spacing[key];
  let to=from;
  if(rate>hi)to=Math.min(mx,from*1.05);else if(rate<lo)to=Math.max(mn,from*.95);
  if(to!==from){S.spacing[key]=to;S.schedLast[key]=t;
    S.schedLog.push({t,key,from:Math.round(from*100)/100,to:Math.round(to*100)/100,rate:Math.round(rate*100)/100,n:st.n,target:`${pct(lo)}–${pct(hi)}%`,reason:rate>hi?"recall above target":"recall below target",alg:ALG});if(S.schedLog.length>50)S.schedLog.shift();
    st.n=Math.round(st.n/2);st.ok=Math.round(st.ok/2)}
  else if(st.n>=60){st.n=Math.round(st.n/2);st.ok=Math.round(st.ok/2)}
}
/* Hard takibi: Hard verilen kelimenin bir sonraki hatırlanması 1 / 3 / 7 gün kovalarına yazılır. */
function hardTrack(c,ok){
  const t=today();if(c.hardAt==null||t<=c.hardAt)return;
  const g=t-c.hardAt,b=g<=2?"d1":g<=5?"d3":g<=10?"d7":null;
  if(b){S.hardStats[b].n++;if(ok)S.hardStats[b].ok++}
  c.hardAt=null;
}
function addCorrectDay(c){const t=today();if(!c.cdays.includes(t)){c.cdays.push(t);if(c.cdays.length>12)c.cdays.shift()}c.lastCorrect=t}
function checkMastery(id){
  const c=S.cards[id];if(!c)return;REV++;
  if(c.masteredOn&&isWeak(id)){       // Kalıcı → Zayıf: unutulan kalıcı kelime, bağlam ağırlıklı yeniden öğrenmeye alınır
    c.masteredOn=null;c.forgot=(c.forgot||0)+1;c.relearn=true;S.forgotMastered=(S.forgotMastered||0)+1;const d=dayRec();d.fm=(d.fm||0)+1;REV++;return}
  if(!c.masteredOn&&isMasteredId(id)){c.masteredOn=today();c.relearn=false;if(SS)SS.mastered++;dayRec().m++}
}
function schedule(id,r){
  const c=ensure(id),t=today();
  if(c.reps>0&&c.lastRev!=null&&c.lastRev<t){const okR=r==="good"||r==="easy";calibAdd(recallProbability(id,t),okR);retrievalObs(c,okR,t)}
  const x=nextStep(c,r,c.first===t,SS&&SS.again.has(id));
  if(c.hardPending&&c.lastRev!==t){S.hardFollow.n++;if(r==="good"||r==="easy")S.hardFollow.ok++}
  c.hardPending=r==="hard";
  hardTrack(c,r==="good"||r==="easy");if(r==="hard")c.hardAt=t;
  adaptSpacing(c,r);
  if(x.lapse)c.lapses++;
  updateStab(c,r);
  c.step=x.step;c.due=t+personalDue(r,x);c.reps++;c.last=t;
  c.rat.push(r[0]);if(c.rat.length>6)c.rat.shift();
  c.hist.push(r==="again"?0:r==="hard"?.5:1);if(c.hist.length>10)c.hist.shift();
  if(r==="good"||r==="easy")addCorrectDay(c);
  checkMastery(id);
}
function rateLabel(id,r){
  if(r==="again")return"oturumda";
  const c=S.cards[id]||{step:0,first:today()};
  const x=nextStep(c,r,!S.cards[id]||c.first===today(),SS&&SS.again.has(id));
  return personalDue(r,x)+" gün";
}

/* ================= SORU ÜRETİMİ ================= */
function available(k,w,n){
  n=n||4;
  if(k==="mean")return true;
  if(k==="syn")return w.syn.length>0&&w.gd.length>=n-1;
  if(k==="pairq"&&w.id==="ensure")return false;   // ensure/insure: bölgesel kullanım farkı nedeniyle soru üretilmez
  if(k==="cloze"||k==="pairq")return w.czd.length>=n-1;
  if(k==="yctx")return!!(w.x2||(w.cx&&w.cx.length))&&w.czd.length>=4;
  if(k==="cpunct")return CPUNCT_OK.has(w.id);
  if(k==="place")return!isLink(w);
  if(k==="guess")return!!w.en&&w.gd.length>=n-1;
  if(k==="coll")return w.col.length>0&&w.bad.length>=n-1;
  if(k==="fam")return famForms(w).length>=2;
  if(k==="cstruct")return isLink(w)&&!!w.cn&&!CONN_SKIP.has(w.id);
  if(k==="cfunc"||k==="cid")return isLink(w)&&!!w.cn&&!CONN_SKIP.has(w.id);
  return true;
}
const SENT={cloze:"cz",fam:"cz",pairq:"cz",yctx:"x2",guess:"ex"};
/* Cümle havuzu: aynı kelime için cz + x2 + cx[] cümleleri; aynı cümle kısa sürede tekrar gösterilmez. */
function blankSents(w,kind){const all=[["cz",w.cz]];if(w.x2)all.push(["x2",w.x2]);(w.cx||[]).forEach((s,i)=>all.push(["cx"+i,s]));
  if(kind==="yctx"){const long=all.filter(([k,s])=>k!=="cz"&&s.split(" ").length>=16);return long.length?long:all.filter(([k])=>k!=="cz")}
  return all}
function pickSent(id,kind){
  const w=BY[id],c=S.cards[id],ex=(c&&c.exp)||{};
  const list=shuffle(blankSents(w,kind));if(!list.length)return["cz",w.cz];
  list.sort((a,b)=>(ex[a[0]]??-1e9)-(ex[b[0]]??-1e9));
  return list[0];
}
function recentlySeen(id,key,days){const c=S.cards[id];if(!c||!c.exp||c.exp[key]==null)return false;return today()-c.exp[key]<(days||2)}
function kindFresh(id,k){if(k==="guess")return!recentlySeen(id,"ex");if(k==="cloze"||k==="yctx")return blankSents(BY[id],k).some(([key])=>!recentlySeen(id,key));return true}
function markSeen(id,k,it){const key=(it&&it.sk)||SENT[k];const c=S.cards[id];if(key&&c){c.exp=c.exp||{};c.exp[key]=today()}}
/* Bağlam zorluğu: Kolay (işaretli örnek cümleden tahmin) → Orta (boşluk doldurma) → YDS (uzun akademik cümle, 5 seçenek) */
function ctxPick(id,level){
  const w=BY[id];level=level||S.ctxLevel;
  const pref=level>=3?["yctx","cloze","guess"]:level===2?["cloze","yctx","guess"]:["guess","cloze","yctx"];
  const av=pref.filter(k=>available(k,w));
  if(!av.length)return null;
  const fresh=av.filter(k=>kindFresh(id,k));
  return(fresh[0]||av[0]);
}
function meanCands(w){
  const k=clsOf(w);
  let c=W.filter(x=>x.id!==w.id&&x.g!==w.g&&clsOf(x)===k&&!w.syn.includes(x.w)&&!x.syn.includes(w.w)&&!trOverlap(w,x));
  c=shuffle(c);
  if(c.length<4){const more=shuffle(W.filter(x=>x.id!==w.id&&x.g!==w.g&&!isLink(x)&&!c.includes(x)&&!w.syn.includes(x.w)&&!x.syn.includes(w.w)&&!trOverlap(w,x)));c=c.concat(more)}
  const cw=w.cw.find(x=>BY[x]&&!trOverlap(w,BY[x])&&!w.syn.includes(x));
  if(cw){c=c.filter(x=>x.id!==cw);c.unshift(BY[cw])}
  return c;
}
/* Bağlaç noktalama/konum sorusu: aynı iki cümlenin dört farklı noktalaması, yalnızca biri doğru. */
const CP_PAIRS={lcontrast:["the new drug was highly effective","it caused serious side effects in some patients"],lresult:["the factory closed down last year","hundreds of local workers lost their jobs"],
  ladd:["cycling reduces traffic in city centres","it improves the physical health of commuters"],lexample:["some birds cannot fly at all","penguins use their wings to swim instead"],lcond:["patients must complete the full course of treatment","the infection may return"]};
const CPUNCT_OK=new Set(["however","nevertheless","nonetheless","on the other hand","therefore","thus","consequently","as a result","moreover","furthermore","in addition","for instance","otherwise","although","even though"].filter(x=>BY[x]));
const cap=s=>s.charAt(0).toUpperCase()+s.slice(1);
function cpunctOpts(w){
  const [A,B]=CP_PAIRS[w.g],x=w.w;
  if(w.cn.struct==="clause")return[`${cap(x)} ${A}, ${B}.`,`${cap(x)}, ${A}, ${B}.`,`${cap(x)} ${A}. ${cap(B)}.`,`${cap(A)}, ${x}, ${B}.`];
  return[`${cap(A)}; ${x}, ${B}.`,`${cap(A)}, ${x} ${B}.`,`${cap(A)} ${x}, ${B}.`,`${cap(A)}, ${x}, ${B}.`];
}
const CM_KIND={mean:"meaning",reverse:"meaning",cfunc:"function",cstruct:"structure",cpunct:"punct",cid:"select",cloze:"select",yctx:"select",pairq:"select",trap:"select"};
const CM_LABEL={meaning:"Anlam",function:"İşlev (zıtlık/sonuç/sebep)",structure:"Yapı",punct:"Konum ve noktalama",select:"Cümlede seçim"};
function connMastery(id){const c=S.cards[id];const o={};for(const k in CM_LABEL){const x=c&&c.cm&&c.cm[k];o[k]=x&&x.c+x.w?Math.round(100*(x.c+.5)/(x.c+x.w+1)):null}return o}
/* Eş anlam bilgi grafiği: doğru cevap olarak güçlü/yakın eş anlam tercih edilir; “farklı dil bilgisi” veya “bağlama bağlı” olanlar kaçınılır. */
function pickSyn(w){
  const ok=w.syn.filter(x=>{const r=BY[x]?relOf(w.id,x):null;return!r||r[0]==="strong"||r[0]==="near"||r[0]==="intensity"});
  return ok[0]||w.syn[0];
}
function connPool(w){return W.filter(x=>isLink(x)&&x.cn&&x.id!==w.id&&!CONN_SKIP.has(x.id))}
function rawOpts(it,n){
  const w=BY[it.id];let correct,pool,syn=[];
  if(it.k==="syn"){correct=pickSyn(w);pool=shuffle(w.gd);syn=w.syn}
  else if(it.k==="guess"){correct=w.en;pool=shuffle(w.gd)}
  else if(it.k==="coll"){correct=w.col[Math.floor(Math.random()*w.col.length)];pool=shuffle(w.bad)}
  else if(it.k==="fam"){correct=w.w;pool=famForms(w)}
  else if(it.k==="pairq"){correct=w.w;pool=[...it.p.ws.filter(x=>x!==w.w),...shuffle(w.czd)]}
  else if(it.k==="cloze"){correct=w.w;pool=shuffle(w.czd);if(!it.sent){const[k,sn]=pickSent(it.id,"cloze");it.sk=k;it.sent=sn}}
  else if(it.k==="yctx"){correct=w.w;pool=shuffle(w.czd);n=5;if(!it.sent){const[k,sn]=pickSent(it.id,"yctx");it.sk=k;it.sent=sn}}
  else if(it.k==="cpunct"){const o=cpunctOpts(w);correct=o[0];pool=o.slice(1)}
  else if(it.k==="place"){correct=w.tr.split(" / ")[0];pool=meanCands(w).map(x=>x.tr.split(" / ")[0])}
  else if(it.k==="cstruct"){correct=STRUCT[w.cn.struct];pool=shuffle(Object.keys(STRUCT).filter(s=>s!==w.cn.struct).map(s=>STRUCT[s]))}
  else if(it.k==="cfunc"){correct=CONN_FN[w.g];pool=shuffle(Object.keys(CONN_FN).filter(g=>g!==w.g&&!(w.g==="lcause"&&g==="lresult")&&!(w.g==="lresult"&&g==="lcause")).map(g=>CONN_FN[g]))}
  else if(it.k==="cid"){correct=w.w;const P=connPool(w);
    const sameG=shuffle(P.filter(x=>x.g===w.g&&x.cn.struct!==w.cn.struct)).slice(0,2);
    const sameS=shuffle(P.filter(x=>x.g!==w.g&&x.cn.struct===w.cn.struct));
    const other=shuffle(P.filter(x=>x.g!==w.g&&x.cn.struct!==w.cn.struct));
    pool=[...sameG,...sameS,...other].map(x=>x.w)}
  else{correct=w.w;pool=meanCands(w).map(x=>x.w)}
  const seen=new Set([correct,...syn]),d=[];
  for(const o of pool){if(d.length>=n-1)break;if(!seen.has(o)){seen.add(o);d.push(o)}}
  const wid=t=>BY[t]?t:null;
  return shuffle([{t:correct,ok:true,wid:wid(correct)},...d.map(t=>({t,ok:false,wid:wid(t)}))]);
}
/* Çeldirici kalitesi: 0–1. 0.6 altı sorular gösterilmez. */
function distractorQuality(it,opts){
  const w=BY[it.id];let q=1;const need=it.k==="fam"?Math.min(4,famForms(w).length+1):it.k==="yctx"?5:4;
  if(opts.length<need)q-=.5;
  if(opts.length<3)q-=.5;
  if(new Set(opts.map(o=>o.t.toLowerCase())).size!==opts.length)q-=1;
  if(opts.filter(o=>o.ok).length!==1)q-=1;
  const wrong=opts.filter(o=>!o.ok);
  for(const o of wrong){
    const x=o.wid&&BY[o.wid];
    if(["mean","cloze","yctx","pairq"].includes(it.k)){
      const curated=it.k!=="mean"&&w.czd.includes(o.t);               // elle yazılmış kalıp çeldiricisi (ör. held prone ✗)
      if(!curated&&(w.syn.includes(o.t)||(x&&x.syn.includes(w.w))))q-=.5; // ikinci doğru cevap riski
      else if(!curated&&x&&sameLadder(w.id,x.id))q-=.5;                 // aynı anlam ailesi: ikisi de cümleye oturabilir
      if(it.k==="mean"&&x&&trOverlap(w,x))q-=.4;
      if(it.k==="mean"&&x&&clsOf(x)!==clsOf(w)&&!isLink(w))q-=.08;     // sözcük türü uyumsuzluğu ipucu verir
    }
    if(it.k==="syn"&&(w.syn.includes(o.t)||o.t===w.w))q-=.6;
    if(it.k==="syn"&&x&&sameLadder(w.id,x.id))q-=.5;
    if(x&&x.id!==w.id){const rl=relOf(w.id,x.id);if(rl&&(rl[0]==="strong"||rl[0]==="near")&&!(it.k!=="mean"&&w.czd.includes(o.t)))q-=.5}
  }
  if(["coll","guess","syn"].includes(it.k)&&wrong.length){
    const avg=wrong.reduce((a,o)=>a+o.t.length,0)/wrong.length,cl=opts.find(o=>o.ok);
    if(cl&&cl.t.length>avg*2.2&&cl.t.length-avg>8)q-=.15;           // çok uzun doğru cevap ipucu
  }
  return Math.max(0,Math.round(q*100)/100);
}
function buildOpts(it,n){
  let best=null,bq=-1;
  for(let i=0;i<3;i++){const o=rawOpts(it,n||4),q=distractorQuality(it,o);if(q>bq){best=o;bq=q}if(q>=1)break}
  it.dq=bq;return best;
}
function globalAcc(s){const x=S.err[s];return(x.c+1)/(x.c+x.w+2)}
function kindsFor(id,only){
  const w=BY[id],c=S.cards[id];
  const sa=s=>{const x=c&&c.sk[s];return x?(x.c+1)/(x.c+x.w+2):.5};
  const ck=ctxPick(id);
  const opts=[["mean","mean"],["syn","syn"],["ctx",ck],["coll","coll"],["fam","fam"]].filter(([s,k])=>k&&available(k,w)&&(!only||only.includes(k)||(s==="ctx"&&only.includes("ctx"))));
  if(isLink(w)&&available("cstruct",w)&&(!only||only.includes("ctx")))opts.push(["ctx","cstruct"]);
  if(isLink(w)&&available("cpunct",w)&&(!only||only.includes("ctx")))opts.push(["ctx","cpunct"]);
  if(c&&wordTags(id).has("RecallGap"))return[...opts.filter(([s])=>s==="mean").map(([s,k])=>k),...opts.filter(([s])=>s!=="mean").map(([s,k])=>k)];
  if(c&&(c.relearn||transferGap(id)))return[...opts.filter(([s])=>s==="ctx").map(([s,k])=>k),...opts.filter(([s])=>s!=="ctx").map(([s,k])=>k)];   // unutulan kalıcı: önce bağlam
  return opts.map(([s,k])=>({k,v:sa(s)*.7+globalAcc(s)*.3+Math.random()*.06})).sort((a,b)=>a.v-b.v).map(x=>x.k);
}
function drill(id){const w=BY[id];return["mean","syn",ctxPick(id),"coll","fam"].filter(k=>k&&available(k,w)).map(k=>({k,id,drill:true}))}
const MEAN_STEMS=[t=>`Which word means <q>${t}</q>?`,t=>`<q>${t}</q> anlamına gelen kelime hangisi?`,t=>`Choose the English word for <q>${t}</q>.`];

/* ================= MINI YDS ================= */
function ydsPickWord(filter){
  const studied=Object.keys(S.cards).filter(id=>BY[id]&&filter(BY[id]));
  const pool=studied.length>=8?studied:W.filter(w=>filter(w)&&w.l<=2).map(w=>w.id);
  return BY[pool[Math.floor(Math.random()*pool.length)]];
}
const blankHtml=s=>esc(s).replace("___","<span class=\"blank\">----</span>").replace("----","<span class=\"blank\">----</span>");
function ydsAuto(yt){
  if(yt==="vocab"){const w=ydsPickWord(w=>!isLink(w)&&w.czd.length>=4);const s=pickSent(w.id,"yctx")[1]||w.cz;
    const o=[w.w,...w.czd.slice(0,4)];
    return{yt,id:w.id,auto:true,stemText:s.replace("___","----"),stem:`<p class="sent long">${blankHtml(s)}</p>`,opts:shuffle(o.map((t,i)=>({t,ok:i===0,ow:i?(BY[t]?`${t} = ${BY[t].tr}; cümlenin anlamına uymuyor.`:"Cümlenin anlamına uymuyor."):""}))),why:w.note,key:[`${w.w} = ${w.tr}`,...w.col.slice(0,1)],gram:w.pat.slice(0,2).join(" · "),words:[w.id]}}
  if(yt==="ctl"){const w=ydsPickWord(w=>isLink(w)&&w.czd.length>=4&&w.cn);if(!w)return null;
    const o=[w.w,...w.czd.slice(0,4)];
    return{yt:"ct",id:w.id,auto:true,stemText:w.cz.replace("___","----"),stem:`<p class="sent long">${blankHtml(w.cz)}</p>`,opts:shuffle(o.map((t,i)=>({t,ok:i===0,ow:i?(BY[t]&&BY[t].cn?`${t}: ${CONN_FN[BY[t].g]||""}, ${STRUCT_SHORT[BY[t].cn.struct]}.`:"Bağlantı ilişkisine uymuyor."):""}))),why:w.note,key:[`${w.w} = ${w.tr}`],gram:w.cn?`${w.w} ${STRUCT_SHORT[w.cn.struct]} · ${w.cn.punct}`:"",words:[w.id]}}
  return null;
}
function bankItem(b,idx){
  const opts=b.o.map((t,i)=>({t,ok:i===b.a,ow:b.ow[i]||""}));
  let stem;
  if(b.t==="tr")stem=`<p class="sent long">${esc(b.q)}</p><p class="qtext">Yukarıdaki cümlenin en yakın çevirisi hangisidir?</p>`;
  else if(b.t==="rs")stem=`<p class="sent long">${esc(b.q)}</p><p class="qtext">Choose the sentence that is closest in meaning.</p>`;
  else if(b.t==="pc")stem=`<p class="sent long">${blankHtml(b.q)}</p><p class="qtext">Paragrafı en uygun şekilde tamamlayan cümle hangisidir?</p>`;
  else if(b.t==="rd"){const p=PBY[b.p];stem=`<details class="passage" open><summary>${esc(p.title)}</summary><p class="ptext">${esc(p.text)}</p></details><p class="qtext">${esc(b.q)}</p>`}
  else stem=`<p class="sent long">${blankHtml(b.q)}</p>`;
  return{yt:b.t,bank:idx,stemText:b.q,stem,opts:shuffle(opts),why:b.why||"",key:b.key||[],gram:b.gram||"",words:(b.w||[]).filter(id=>BY[id]),pid:b.p};
}
/* Soru tanışıklığı: hiç görülmeyen → en uzun süredir görülmeyen; son 14 günde doğru yapılan soru mümkünse gelmez, yanlış yapılan 3 gün sonra dönebilir. */
function qPriority(qid,t){
  const q=S.qstats[qid];if(!q||!q.n)return Math.random()*.1;
  const age=q.last==null?999:t-q.last;
  if(q.lastOk&&age<14)return 3+1/(1+age);
  if(q.lastOk===false&&age<3)return 2.5+1/(1+age);
  return 1+1/(1+age);
}
function ydsBank(t,used){
  const all=t==="rd"?RD.map((b,i)=>({b,i:"r"+i})):BANK.map((b,i)=>({b,i:"b"+i})).filter(x=>x.b.t===t);
  if(!all.length)return null;
  const day=today();
  const pool=all.filter(x=>!used.has(x.i));const src=pool.length?pool:all;
  const ranked=src.map(x=>({x,p:qPriority(x.i,day)+Math.random()*.01})).sort((a,b)=>a.p-b.p);
  const x=ranked[0].x;used.add(x.i);
  if(t==="rd"){const sib=RD.map((b,i)=>({b,i:"r"+i})).filter(y=>y.b.p===x.b.p&&!used.has(y.i));sib.forEach(y=>used.add(y.i))} // aynı pasajdan tek soru
  return bankItem(x.b,x.i);
}
const YDS_PLANS={5:["vocab","ct","sc","tr","rd"],10:["vocab","vocab","ct","ct","sc","tr","rs","pc","rd","rd"],20:["vocab","vocab","vocab","vocab","ct","ct","ct","sc","sc","sc","tr","tr","rs","rs","pc","pc","rd","rd","rd","rd"],
  40:["vocab","vocab","vocab","vocab","vocab","vocab","vocab","vocab","ct","ct","ct","ct","ct","ct","sc","sc","sc","sc","sc","sc","tr","tr","tr","tr","rs","rs","rs","rs","pc","pc","pc","pc","rd","rd","rd","rd","rd","rd","rd","rd"]};
function ydsSet(n){
  const plan=YDS_PLANS[n]||YDS_PLANS[10];
  const used=new Set();let vAlt=0,ctAlt=0;
  const items=plan.map(t=>{let q=null;
    if(t==="vocab"){q=(vAlt++%2===1)?ydsAuto("vocab"):ydsBank("vocab",used);if(!q)q=ydsAuto("vocab")}
    else if(t==="ct"){q=(ctAlt++%3===2)?ydsAuto("ctl"):null;if(!q)q=ydsBank("ct",used)}
    else q=ydsBank(t,used);
    return q&&Object.assign({k:"yds"},q)}).filter(Boolean);
  // Okuma soruları aynı pasajdan geliyorsa art arda gelsin
  const rd=items.filter(x=>x.yt==="rd").sort((a,b)=>String(a.pid).localeCompare(String(b.pid)));
  return[...items.filter(x=>x.yt!=="rd"),...rd];
}
function ydsBalance(items){const c=[0,0,0,0,0];items.forEach(it=>{const i=it.opts.findIndex(o=>o.ok);if(i>=0)c[i]++});return c}

/* ================= OTURUM ================= */
function newSession(mode,extra){return Object.assign({mode,phases:[],pi:0,ii:0,stage:"front",ans:null,self:null,fam:false,newIds:[],revIds:[],studied:[],q:0,c:0,hard:new Set(),again:new Set(),pen:new Set(),pairHit:new Set(),rq:{},sk:{},mastered:0,t0:Date.now(),ydsT:{},ydsWrong:new Set(),ydsLog:[],selfPending:null,knowIds:[],dqSkipped:0,revRec:{n:0,ok:0},deferred:0,ctx0:S.ctxLevel},extra||{})}
function addPhase(key,label,items,dyn){if(items.length||dyn)SS.phases.push({key,label,items,dyn:!!dyn})}
function connItems(id){const w=BY[id];const out=[{k:"connfo",id}];["cstruct","cfunc","cid","cpunct"].forEach(k=>{if(available(k,w))out.push({k,id})});if(available("cloze",w))out.push({k:"cloze",id});return out}
function trapItem(t){return{k:"trap",t,opts:t.o.map((x,i)=>({t:x,ok:i===t.a}))}}
function clozeItems(c){return c.blanks.map((b,i)=>({k:"clz",cz:c,bi:i,opts:shuffle(b.o.map((t,j)=>({t,ok:j===b.a})))}))}
/* Okuma köprüsü hedef seti: zayıf (3), son 3 günde öğrenilen (2), unutulmaya yakın kalıcı (2), tanıdık (1) */
const READ_LEVELS=["easy","intermediate","yds"],READ_LABEL={easy:"Kolay",intermediate:"Orta",yds:"YDS"};
function targetWeights(){
  const t=today(),sm=statusMap(),o={};
  for(const id in S.cards){if(!BY[id])continue;const c=S.cards[id],st=sm[id];let v=0;
    if(st==="weak"||transferGap(id))v=3;else if(c.first>=t-3)v=2;else if(c.first>=t-7)v=2;else if(st==="mastered"&&(c.due<=t+1||retr(c,t)<.7))v=2;else if(st==="familiar")v=1;
    if(v)o[id]=v}
  return o;
}
function textScore(words){const tw=targetWeights();return words.reduce((a,id)=>a+(tw[id]||0),0)}
function pickByLevel(list,doneMap,level){
  const t=today();
  let pool=list.filter(x=>doneMap[x.id]==null||t-doneMap[x.id]>=7);         // son 7 günde gösterilen tekrar gelmez
  if(!pool.length)pool=list.slice().sort((a,b)=>(doneMap[a.id]??-1)-(doneMap[b.id]??-1)).slice(0,3);
  const want=READ_LEVELS[level];
  const order=[want,READ_LEVELS[level-1],READ_LEVELS[level+1]].filter(Boolean);
  for(const lv of order){const c=pool.filter(x=>x.difficulty===lv);if(c.length){const tw=targetWeights();
    return c.map(x=>({x,s:x.words.reduce((a,id)=>a+(tw[id]||0),0)+Math.random()*.5})).sort((a,b)=>b.s-a.s)[0].x}}
  return pool[0];
}
function pickPassage(){return pickByLevel(PASSAGES,S.readDone,S.readLevel)}
function pickCloze(){return pickByLevel(CLOZES,S.clozeDone,S.readLevel)}
/* Okuma zorluğu: son 20 okuma sorusu; en az 12 cevap ve 2 oturum olmadan seviye değişmez. */
function readAdjust(){
  S.readSess++;
  if(S.readHist.length<12||S.readSess<2)return null;
  const a=S.readHist.reduce((x,y)=>x+y,0)/S.readHist.length;let ch=null;
  if(a>=.8&&S.readLevel<2){S.readLevel++;ch="up"}else if(a<.55&&S.readLevel>0){S.readLevel--;ch="down"}
  if(ch){S.readSess=0;S.readHist=[]}
  return ch;
}
function startSession(mode,arg){
  if(mode==="yds"){
    SS=newSession("yds",{ydsN:arg});
    addPhase("yds","Mini YDS",ydsSet(arg));
  }else if(mode==="pair"){
    const p=PAIRS[arg];SS=newSession("pair",{pair:arg,studied:p.ws.slice()});
    addPhase("compare","Karşılaştır",[{k:"pair",p}]);
    const items=[];p.ws.forEach(id=>{items.push({k:"pairq",id,p});items.push({k:"mean",id})});
    TRAPS.filter(t=>t.pair.split("/").some(x=>p.ws.includes(x))).slice(0,3).forEach(t=>items.push(trapItem(t)));
    addPhase("test","Mini test",shuffle(items));
  }else if(mode==="quick"){
    const t=today();const due=dueList().sort((a,b)=>recallProbability(a,t)-recallProbability(b,t)).slice(0,30);
    if(!due.length)return;
    SS=newSession("quick",{revIds:due,studied:due.slice()});
    addPhase("review","Hızlı tekrar",due.map(id=>({k:"flash",id})));
    addPhase("mini","Kısa test",[],true);
  }else if(mode==="weak"){
    const ws=weakList().slice(0,8);if(!ws.length)return;
    SS=newSession("weak",{revIds:ws,studied:ws.slice()});
    const lw=ws.filter(id=>wordTags(id).has("Leech")).slice(0,2);
    if(lw.length)addPhase("leech","Farklı yöntem",lw.flatMap(id=>[{k:"leech",id},{k:"mean",id},{k:ctxPick(id)||"mean",id}]));
    const pairs=PAIRS.filter(p=>p.ws.some(w=>ws.includes(w))).slice(0,2);
    const items=[];
    ws.forEach(id=>{const c=S.cards[id];if(c&&c.wrong>=3)items.push(...drill(id));else{items.push({k:"flash",id});kindsFor(id).filter(k=>k!=="mean").slice(0,2).forEach(k=>items.push({k,id}))}});
    if(pairs.length)addPhase("pairs","Karıştırılan kelimeler",pairs.map(p=>({k:"pair",p})));
    addPhase("weak","Zayıf kelimeler",items);
  }else if(mode==="fav"){
    const fs=S.fav.filter(id=>BY[id]).slice(0,20);if(!fs.length)return;
    SS=newSession("fav",{revIds:fs.filter(id=>S.cards[id]),newIds:fs.filter(id=>!S.cards[id]),studied:fs.slice()});
    addPhase("fav","Favoriler",fs.map(id=>({k:S.cards[id]?"flash":"learn",id})));
    addPhase("favq","Bağlam ve bağlantı",fs.map(id=>({k:kindsFor(id)[0]||"mean",id})));
  }else if(mode==="conn"){
    const L=W.filter(w=>isLink(w)&&w.cn&&!CONN_SKIP.has(w.id));
    let ids=arg?L.filter(w=>w.g===arg).map(w=>w.id):[];
    if(!ids.length){const known=L.filter(w=>S.cards[w.id]).sort((a,b)=>masteryScore(a.id)-masteryScore(b.id)).map(w=>w.id);const fresh=L.filter(w=>!S.cards[w.id]).sort((a,b)=>b.p-a.p).map(w=>w.id);ids=[...known.slice(0,4),...fresh].slice(0,6)}
    ids=ids.slice(0,8);
    SS=newSession("conn",{studied:ids.slice(),newIds:ids.filter(id=>!S.cards[id]),revIds:ids.filter(id=>S.cards[id])});
    addPhase("cinfo","Bağlaç kartları",ids.map(id=>({k:"connfo",id})));
    const qs=[];ids.forEach(id=>connItems(id).slice(1).forEach(x=>qs.push(x)));
    TRAPS.filter(t=>/although|because/.test(t.pair)).forEach(t=>qs.push(trapItem(t)));
    addPhase("cq","Yapı ve işlev testi",shuffle(qs));
  }else if(mode==="place"){
    // Seviyemi ölç: 18 soru (6 temel, 6 orta, 6 ileri); kart oluşturmaz
    const band=f=>shuffle(W.filter(w=>!isLink(w)&&!w.sv&&f(w.l))).slice(0,6).map(id=>({k:"place",id:id.id,band:f===B1?"core":f===B2?"inter":"adv"}));
    const B1=l=>l<=2,B2=l=>l===3,B3=l=>l>=4;
    SS=newSession("place",{place:{core:{c:0,n:0},inter:{c:0,n:0},adv:{c:0,n:0}},placeOk:[]});
    addPhase("place","Seviyemi ölç",[...band(B1),...band(B2),...band(B3)]);
  }else if(mode==="trap"){
    SS=newSession("trap");
    addPhase("trap","Kelime tuzağı",shuffle(TRAPS).slice(0,12).map(trapItem));
  }else if(mode==="cluster"){
    const g=arg;const ws=W.filter(w=>w.g===g).sort((a,b)=>a.l-b.l||b.p-a.p);
    const pick=[...ws.filter(w=>S.cards[w.id]),...ws.filter(w=>!S.cards[w.id])].slice(0,8).map(w=>w.id);
    SS=newSession("cluster",{cluster:g,studied:pick.slice(),newIds:pick.filter(id=>!S.cards[id]),revIds:pick.filter(id=>S.cards[id])});
    addPhase("ladder","Eş anlam merdiveni",[{k:"ladder",g,ids:pick}]);
    addPhase("cards","Kelimeler",pick.map(id=>({k:S.cards[id]?"flash":"learn",id})));
    addPhase("cq","Kullanım farkı",shuffle(pick.flatMap(id=>[available("syn",BY[id])?{k:"syn",id}:null,{k:ctxPick(id)||"mean",id}]).filter(Boolean)));
  }else if(mode==="ladder"){
    const L=LADDERS.find(x=>x.id===arg);if(!L)return;
    const pick=ladderWords(L).filter(id=>BY[id]).slice(0,8);
    SS=newSession("cluster",{cluster:null,ladder:L.id,studied:pick.slice(),newIds:pick.filter(id=>!S.cards[id]),revIds:pick.filter(id=>S.cards[id])});
    addPhase("ladder","Anlam merdiveni",[{k:"ladder",L}]);
    addPhase("cards","Kelimeler",pick.map(id=>({k:S.cards[id]?"flash":"learn",id})));
    addPhase("cq","Kullanım farkı",shuffle(pick.flatMap(id=>[available("syn",BY[id])?{k:"syn",id}:null,{k:ctxPick(id)||"mean",id}]).filter(Boolean)));
  }else if(mode==="read"){
    const p=arg?PBY[arg]:pickPassage();if(!p)return;
    SS=newSession("read",{pid:p.id,studied:p.words.filter(id=>S.cards[id]),readLv0:S.readLevel});
    const qs=RD.map((b,i)=>({b,i})).filter(x=>x.b.p===p.id).map(x=>Object.assign({k:"rdq"},bankItem(x.b,"r"+x.i)));
    addPhase("passage","Okuma köprüsü",[{k:"passage",p},...qs]);
  }else if(mode==="clz"){
    const c=arg?CLOZES.find(x=>x.id===arg):pickCloze();if(!c)return;
    SS=newSession("clz",{czid:c.id,studied:c.words.filter(id=>S.cards[id]),readLv0:S.readLevel});
    addPhase("clz","Cloze köprüsü",clozeItems(c));
  }else{
    const p=planRaw(mode);const rev=[...p.weak,...p.review,...p.early];
    if(!rev.length&&!p.newIds.length)return;
    // Kapasiteyi aşan tekrarlar sonraki günlere yayılır (en iyi hatırlananlar ertelenir)
    let deferred=0;
    if(mode==="daily"&&p.overflow.length){const map=spreadOverflow(p.overflow,p.review.length);for(const id in map){S.cards[id].due=map[id];deferred++}S.deferred=deferred}
    SS=newSession(mode,{newIds:p.newIds,revIds:rev,studied:[...new Set([...rev,...p.newIds])],weakSet:new Set(p.weak),deferred,plan:p});
    const flash=rev.map(id=>({k:"flash",id,early:p.early.includes(id)}));
    // Ters hatırlama: günlük maddelerin en fazla %12'si; zamanlamayı değiştirmez
    const est=flash.length+p.newIds.length*3+p.weak.length*2+p.synN+p.ctxN+p.confN+p.cfg.mini;
    const revN=Math.min(Math.floor(est*.12),p.review.filter(id=>S.cards[id].step>=1).length);
    const revItems=shuffle(p.review.filter(id=>S.cards[id].step>=1)).slice(0,revN).map(id=>({k:"reverse",id}));
    // Recall Gap: kartta söyleyemiyor ama soruda tanıyor → açık hatırlama + ters hatırlama ile pekiştir
    const rg=rev.filter(id=>wordTags(id).has("RecallGap")).slice(0,5);
    flash.forEach(x=>{if(rg.includes(x.id))x.open=true});
    rg.filter(id=>!revItems.some(x=>x.id===id)).forEach(id=>revItems.push({k:"reverse",id,gap:true}));
    const mixed=flash.slice();revItems.forEach((x,i)=>mixed.splice(Math.min(mixed.length,(i+1)*Math.ceil(mixed.length/(revItems.length+1))+i),0,x));
    addPhase("review","Hızlı tekrar",mixed);
    const wq=[];p.weak.forEach(id=>{const ks=kindsFor(id).filter(k=>k!=="mean").slice(0,2);ks.forEach(k=>wq.push({k,id}));
      if(S.cards[id].relearn&&available("cloze",BY[id]))wq.push({k:"cloze",id,relearn:true})});   // unutulan kalıcı: ek bağlam
    // Recognition Gap: kartta tanıyor ama soruda kaçırıyor → flashcard değil bağlam ağırlığı
    rev.filter(id=>transferGap(id)).slice(0,6).forEach(id=>{const k=ctxPick(id);if(k)wq.push({k,id,gap:true})});
    // Leech: çok tekrar, düşük ustalık → farklı yöntem (özel kart + kısa test), 3 günde bir
    const t=today(),lee=rev.filter(id=>wordTags(id).has("Leech")&&(S.cards[id].leechShown==null||t-S.cards[id].leechShown>=3)).slice(0,2);
    const leeItems=lee.flatMap(id=>[{k:"leech",id},{k:"mean",id},{k:ctxPick(id)||"mean",id}]);
    addPhase("weak","Zayıf kelimeler",[...leeItems,...shuffle(wq)]);
    addPhase("learn","Yeni kelimeler",p.newIds.map(id=>({k:"learn",id})));
    // Kırılgan kalıcı: kalıcı olduktan 7+ gün sonra bir bağlam kontrolü; sürpriz kontrol: 30/60/90. gün civarı (yoğun günlerde yok)
    const fr=Object.keys(S.cards).filter(id=>BY[id]&&wordTags(id).has("FragileMastered")&&t-S.cards[id].masteredOn>=7&&!rev.includes(id)).slice(0,3);
    const sp=p.load==="heavy"?[]:surpriseCandidates(t).slice(0,2);
    SS.extraMini=[...fr.map(id=>({k:ctxPick(id)||"mean",id,fragile:true})),...sp.map(x=>({k:ctxPick(x.id)||"mean",id:x.id,surprise:x.m})),...(p.dtc||[]).map(id=>({k:ctxPick(id)||"mean",id,delayed:true}))];
    SS.studied=[...new Set([...SS.studied,...fr,...sp.map(x=>x.id),...(p.dtc||[])])];
    const revS=shuffle(p.review.concat(p.early));
    addPhase("syn","Eş anlam testi",shuffle([...p.newIds,...revS.filter(id=>available("syn",BY[id])).slice(0,p.synN)].filter(id=>available("syn",BY[id]))).map(id=>({k:"syn",id})));
    SS.ctxRev=revS.filter(id=>!SS.phases.find(ph=>ph.key==="syn"&&ph.items.some(x=>x.id===id))).slice(0,p.ctxN);
    addPhase("ctx","Cümle içinde",[],true);
    SS.confN=p.confN;
    addPhase("conf","Karıştırılan kelimeler",[],true);
    addPhase("hard","Günün zor kelimeleri",[],true);
    addPhase("mini","Kısa karışık test",[],true);
  }
  SS.sid=Date.now().toString(36)+Math.floor(Math.random()*1e4).toString(36);SS.acts=0;
  SS.planned=SS.phases.reduce((a,ph)=>a+ph.items.length,0);
  S.sessLog.push({sid:SS.sid,d:today(),mode,len:S.settings.length,planned:SS.planned,done:0,ok:false,alg:ALG});if(S.sessLog.length>80)S.sessLog.shift();
  logEv("sessionStarted",{qt:mode});
  document.body.classList.add("in-session");sheet=null;
  enterPhase();if(typeof window!=="undefined")window.scrollTo(0,0);
}
function buildDynamic(ph){
  if(ph.key==="ctx"){
    const ids=[...SS.newIds,...(SS.ctxRev||[])];
    // Öz değerlendirme doğrulaması: “Biliyorum” dediğin kelimelerden bazıları bağlamda sorulur
    const verify=SS.knowIds.filter(id=>!ids.includes(id)).slice(0,4);
    ph.items=[...ids.map(id=>({k:ctxPick(id)||"mean",id})),...verify.map(id=>({k:ctxPick(id)||"mean",id,verify:true}))];
    ph.items=shuffle(ph.items);
  }else if(ph.key==="conf"){
    const st=new Set(SS.studied);const items=[];
    const pairs=PAIRS.filter(p=>p.ws.some(w=>st.has(w)&&S.cards[w])).slice(0,Math.max(0,SS.confN||0));
    pairs.forEach(p=>{const id=p.ws.find(w=>st.has(w));if(available("pairq",BY[id]))items.push({k:"pairq",id,p})});
    const confd=Object.keys(S.conf).filter(id=>st.has(id)&&BY[id]);
    confd.slice(0,2).forEach(id=>{const p=PAIRS.find(pp=>pp.ws.includes(id));if(p&&!items.some(x=>x.id===id))items.push({k:"pairq",id,p})});
    const traps=TRAPS.filter(t=>t.pair.split("/").some(x=>st.has(x)));
    shuffle(traps).slice(0,Math.max(0,(SS.confN||0)-items.length)).forEach(t=>items.push(trapItem(t)));
    // Kişisel karıştırma çiftleri (gerçek hatalardan): karşılaştırma kartı + soru
    personalPairs().filter(p=>p.ws.some(w=>st.has(w))).slice(0,2).forEach(p=>{items.unshift({k:"pair",p});const id=p.ws.find(w=>st.has(w));if(available("pairq",BY[id]))items.push({k:"pairq",id,p})});
    ph.items=items;
  }else if(ph.key==="hard"){
    const hard=[...SS.hard];
    const pairs=PAIRS.filter(p=>p.ws.some(w=>SS.pairHit.has(w))||(p.ws.some(w=>SS.hard.has(w))&&p.ws.every(w=>S.cards[w]))).slice(0,2);
    const items=pairs.map(p=>({k:"pair",p}));let drills=0;
    for(const id of hard.slice(0,10)){if(!BY[id])continue;const c=S.cards[id];if(c&&c.wrong>=3&&drills<3){items.push(...drill(id));drills++}else items.push({k:"flash",id,hard:true})}
    ph.items=items;
  }else if(ph.key==="mini"){
    const pool=shuffle(SS.studied.filter(id=>BY[id]));if(!pool.length){ph.items=[];return}
    const cfg=LEN[S.settings.length]||LEN.normal;const n=SS.mode==="quick"?3:Math.min(cfg.mini,Math.max(3,pool.length*2));
    const base=["mean","ctx","syn","coll","ctx","fam"];const ws=weakestSkill();
    const prefer=ws?{mean:"mean",syn:"syn",ctx:"ctx",coll:"coll",fam:"fam",conf:"ctx"}[ws.k]:null;
    ph.items=[];
    for(let i=0;i<n;i++){const id=pool[i%pool.length];let k=(prefer&&i%3===2)?prefer:base[i%base.length];if(k==="ctx")k=ctxPick(id)||"mean";if(!available(k,BY[id]))k=ctxPick(id)||"mean";ph.items.push({k,id})}
    if(SS.extraMini)ph.items.push(...SS.extraMini);
  }
}
function enterPhase(){
  while(SS.pi<SS.phases.length){const ph=SS.phases[SS.pi];if(ph.dyn)buildDynamic(ph);
    if(ph.items.length){SS.ii=0;if(prepare())return render();continue}SS.pi++}
  finish();
}
const cur=()=>SS.phases[SS.pi].items[SS.ii];
/* Hazırla: kalitesiz soru gösterilmez; önce “anlam” sorusuna düşer, o da kalitesizse atlanır. */
function prepare(){
  for(;;){
    const ph=SS.phases[SS.pi];
    if(SS.ii>=ph.items.length){SS.pi++;if(SS.pi>=SS.phases.length)return false;const np=SS.phases[SS.pi];if(np.dyn)buildDynamic(np);SS.ii=0;continue}
    SS.stage="front";SS.ans=null;SS.self=null;SS.fam=false;SS.t0i=Date.now();SS.hid=false;SS.trev=null;
    const it=cur();
    if(it.k==="learn"&&!it.again&&!it.logged){it.logged=true;logEv("wordShown",{w:it.id,d:BY[it.id]&&BY[it.id].l})}
    if(it.k==="flash"&&it.open==null&&wordTags(it.id).has("RecallGap"))it.open=true;
    if((it.k==="flash"||it.k==="learn"||it.k==="connfo")&&it.open==null){
      // Açık hatırlama: ayara göre; butonlu modda bile her 4. tekrar kartı açık hatırlama ister
      const m=S.settings.recall,c=S.cards[it.id];SS.fc=(SS.fc||0)+1;
      it.open=m==="open"||(it.k==="flash"&&(m==="auto"?(c&&c.step>=2)||SS.fc%4===0:SS.fc%4===0));
    }
    if(OPTK.includes(it.k)){
      if(!it.id||!BY[it.id]||!available(it.k,BY[it.id])){it.k="mean"}
      it.opts=buildOpts(it);
      if(it.dq<.6&&it.k!=="mean"){it.k="mean";it.opts=buildOpts(it)}
      if(it.dq<.6){SS.dqSkipped++;SS.ii++;continue}
    }
    return true;
  }
}
function trackCtx(ok){
  S.ctxRecent.push(ok?1:0);if(S.ctxRecent.length>10)S.ctxRecent.shift();
  if(S.ctxRecent.length>=10){const a=S.ctxRecent.reduce((x,y)=>x+y,0)/S.ctxRecent.length;
    if(a>=.8&&S.ctxLevel<3){S.ctxLevel++;S.ctxRecent=[]}else if(a<=.5&&S.ctxLevel>1){S.ctxLevel--;S.ctxRecent=[]}}
}
function record(it,ok,picked){
  SS.q++;if(ok)SS.c++;SS.acts=(SS.acts||0)+1;
  if(it.k==="place"){const b=SS.place[it.band];b.n++;if(ok){b.c++;SS.placeOk.push(it.id)}return}   // yerleştirme: istatistiklere ve kartlara dokunmaz
  const d=dayRec();d.q++;if(ok)d.c++;
  if(it.k==="yds"||it.k==="rdq"){bump(SS.ydsT,it.yt,ok);if(!ok)it.words.forEach(id=>SS.ydsWrong.add(id));
    if(it.bank){const q=S.qstats[it.bank]||(S.qstats[it.bank]={n:0,last:null,c:0,w:0,lastOk:null});q.n++;q.last=today();q[ok?"c":"w"]++;q.lastOk=ok}
    if(it.yt==="rd"){S.readHist.push(ok?1:0);if(S.readHist.length>20)S.readHist.shift();bump(d,"rd",ok)}
    // Aktarım: okuma / Mini YDS kelime sorularındaki kelimeler; 3–7 gün önce öğrenilenler ayrıca izlenir
    const key=it.yt==="rd"?"read":it.yt==="vocab"?"yv":null,tt=today();
    if(key)for(const wid of it.words){const c=S.cards[wid];if(!c)continue;c.tr=c.tr||{};bump(c.tr,key,ok);
      if(key==="read"&&c.first<=tt-3&&c.first>=tt-7){S.transfer37.n++;if(ok)S.transfer37.ok++}
      if(key==="read"&&S.qstats[it.bank]&&S.qstats[it.bank].n===1){const age=tt-c.first;if(age<=1){bump(c,"trI",ok);bump(S,"immediate",ok)}else if(age>=3&&age<=7){bump(c,"trD",ok);bump(S,"delayed",ok)}}
      if(key==="read")fragileCheck(c,ok)}}
  if(it.k==="trap"){bump(S,"trapStats",ok);bump(S.err,"conf",ok);bump(SS.sk,"conf",ok);bump(d.sk,"conf",ok);
    it.t.pair.split("/").forEach(x=>{const c=S.cards[x];if(c){bump(c.sk,"conf",ok);if(!ok)c.confErr=(c.confErr||0)+1}});return save()}
  if(it.k==="clz"){bump(SS.sk,"ctx",ok);bump(d.sk,"ctx",ok);S.readHist.push(ok?1:0);if(S.readHist.length>20)S.readHist.shift();bump(d,"rd",ok);bump(d,"cz",ok);
    const wid=it.cz.blanks[it.bi].o[it.cz.blanks[it.bi].a],c=S.cards[wid];if(c){c.tr=c.tr||{};bump(c.tr,"clz",ok);
      if(S.clozeDone[it.cz.id]==null){const age=today()-c.first;if(age<=1){bump(c,"trI",ok);bump(S,"immediate",ok)}else if(age>=3&&age<=7){bump(c,"trD",ok);bump(S,"delayed",ok)}}}return save()}
  const id=it.id;if(!id||!BY[id])return save();
  const skill=KIND_SKILL[it.k]||"ctx";
  bump(SS.sk,skill,ok);bump(d.sk,skill,ok);
  // “Biliyorum” iddiası, aynı kelimenin oturumdaki bir sonraki sorusuyla doğrulanır
  if(SS.claim&&SS.claim[id]&&it.k!=="reverse"){delete SS.claim[id];S.self.verify.n++;if(ok)S.self.verify.ok++;if(skill==="ctx"){S.self.knowCtx.n++;if(ok)S.self.knowCtx.ok++}}
  const c=S.cards[id];if(!c){save();return}
  const w=BY[id];
  const t0=today();if(it.k!=="reverse"&&c.reps>0&&c.lastRev!=null&&c.lastRev<t0){calibAdd(recallProbability(id,t0),ok);retrievalObs(c,ok,t0,true)}
  delayedTransfer(c,it,ok,t0,skill);
  if(skill==="ctx")fragileCheck(c,ok);
  if(it.surprise){c.surpr=c.surpr||[];c.surpr.push(it.surprise);S.surpriseStats.n++;if(ok)S.surpriseStats.ok++;bump(S.mastCheck,String(it.surprise),ok)}
  if(skill==="ctx"&&it.k!=="yds"&&it.k!=="rdq")trackCtx(ok);
  markSeen(id,it.k,it);
  bump(S.err,skill,ok);bump(S.grp,w.g,ok);bump(c.sk,skill,ok);bump(d.g,w.g,ok);
  if(isLink(w)&&CM_KIND[it.k]){c.cm=c.cm||{};bump(c.cm,CM_KIND[it.k],ok);bump(S.connDim,CM_KIND[it.k],ok)}
  hardTrack(c,ok);
  if(it.k==="reverse"){SS.revRec.n++;if(ok)SS.revRec.ok++;REV++;return save()}   // ters hatırlama programı değiştirmez
  c.hist.push(ok?1:0);if(c.hist.length>10)c.hist.shift();
  quizStab(c,ok);
  if(ok){c.correct++;addCorrectDay(c)}else{
    c.wrong++;SS.hard.add(id);
    const t=today();
    if(c.first===t){c.step=Math.min(c.step,1);c.due=t+1}
    else if(!SS.pen.has(id)){c.step=Math.max(1,c.step-1);c.due=Math.min(c.due,t+1);SS.pen.add(id)}
    if(picked&&picked!==id){
      S.conf[id]=S.conf[id]||{};S.conf[id][picked]=(S.conf[id][picked]||0)+1;
      if(skill!=="conf"&&(w.cw.includes(picked)||PAIRMAP[pairKey(id,picked)])){c.confErr=(c.confErr||0)+1;bump(c.sk,"conf",false);bump(S.err,"conf",false);SS.pairHit.add(id);SS.pairHit.add(picked)}else if(skill==="conf"){c.confErr=(c.confErr||0)+1}
    }
  }
  checkMastery(id);save();
}
function answer(i){
  const it=cur();if(SS.ans!==null||!it.opts||i>=it.opts.length)return;
  SS.ans=i;const o=it.opts[i];
  const rt=validRt(Date.now()-SS.t0i,SS.hid);
  record(it,o.ok,o.wid);
  if(o.ok&&it.id&&S.cards[it.id]&&!it.bank)noteRt(S.cards[it.id],rt);
  if(!o.ok){const qk=qKey(it);const wp=S.wrongPicks[qk]||(S.wrongPicks[qk]={pick:null,n:0,rep:0});if(wp.pick===o.t)wp.rep++;wp.pick=o.t;wp.n++;
    const ks=Object.keys(S.wrongPicks);if(ks.length>600)delete S.wrongPicks[ks[0]]}
  logEv(o.ok?"questionCorrect":"questionWrong",{w:it.id||null,q:it.bank||null,qt:it.k==="yds"||it.k==="rdq"?it.yt:it.k,rt,d:it.k==="rdq"||it.yt==="rd"?S.readLevel:KIND_SKILL[it.k]==="ctx"?S.ctxLevel:(it.id&&BY[it.id]?BY[it.id].l:null),r:o.ok?1:0});
  if(it.k==="yds"){const a=it.opts.findIndex(x=>x.ok);SS.ydsLog.push({yt:it.yt,q:it.stemText,pid:it.pid,o:it.opts.map(x=>x.t),ow:it.opts.map(x=>x.ow||""),picked:i,a,why:it.why,key:it.key,gram:it.gram,ok:o.ok})}
  if(typeof announce==="function")announce(o.ok?"Doğru.":"Yanlış. Doğru cevap: "+it.opts.find(x=>x.ok).t);
  render();
}
/* Öz değerlendirme: Biliyorum / Emin değilim / Bilmiyorum seçimi, sonraki puanla karşılaştırılır. */
function selfRecord(self,r){
  if(!self||!S.self[self])return;
  const ok=self==="know"?(r==="good"||r==="easy"):self==="unsure"?(r==="hard"||r==="good"):r==="again"||r==="hard";
  S.self[self].n++;if(ok)S.self[self].ok++;
}
function revealRecall(ok){const it=cur();record(it,ok,null);logEv(ok?"wordRecalled":"wordMissed",{w:it.id,qt:it.k});SS.stage="done";render()}
function markReveal(){if(SS&&SS.trev==null)SS.trev=validRt(Date.now()-SS.t0i,SS.hid)}
function rate(r){
  const it=cur(),id=it.id;
  if(SS.self&&!it.open)selfRecord(SS.self,r);
  if(SS.self==="know"){SS.claim=SS.claim||{};
    if(r==="again"){S.self.verify.n++}                                  // cevabı görünce bilmediği anlaşıldı
    else{SS.claim[id]=true;if(!SS.knowIds.includes(id)&&S.cards[id]&&!SS.newIds.includes(id))SS.knowIds.push(id)}}
  if(SS.trev===undefined||SS.trev===null)markReveal();
  if((r==="good"||r==="easy")&&S.cards[id])noteRt(S.cards[id],SS.trev);
  schedule(id,r);SS.acts=(SS.acts||0)+1;
  logEv("reviewCompleted",{w:id,qt:it.k,rt:SS.trev,d:BY[id]&&BY[id].l,r:r[0]});
  if(it.open)logEv(r==="good"||r==="easy"?"wordRecalled":"wordMissed",{w:id,qt:"open"});
  if(r==="again"){SS.again.add(id);SS.hard.add(id);SS.rq[id]=(SS.rq[id]||0)+1;if(SS.rq[id]<=2)SS.phases[SS.pi].items.push({k:it.k==="learn"?"learn":"flash",id,again:true,hard:it.hard})}
  if(r==="hard")SS.hard.add(id);
  if(S.queue.includes(id))S.queue=S.queue.filter(x=>x!==id);
  save();next();
}
function next(){const pv=cur();if(pv&&pv.k==="leech"&&S.cards[pv.id]){const lc=S.cards[pv.id];lc.leechShown=today();lc.leechTrack={t:today(),fails:0,seen:{}}}SS.ii++;if(prepare())render();else finish();if(typeof window!=="undefined")window.scrollTo(0,0)}
function finish(){
  const t=today(),mode=SS.mode;
  if(mode==="daily")S.doneDay=t;
  if(mode!=="place"&&S.last!==t){S.streak=(S.last===t-1)?S.streak+1:1;S.last=t}
  S.best=Math.max(S.best||0,S.streak);
  const d=dayRec(t);
  d.n+=SS.newIds.length;d.r+=SS.revIds.length;
  const secs=Math.round((Date.now()-SS.t0)/1000);
  if(mode==="yds"){
    const bt={};for(const k in SS.ydsT)bt[k]=SS.ydsT[k];
    S.mini.push({d:t,n:SS.q,c:SS.c,secs,bt});if(S.mini.length>30)S.mini.shift();
    if(bt.rd)readAdjust();
    summary={type:"yds",n:SS.q,c:SS.c,secs,bt,weak:[...SS.ydsWrong],log:SS.ydsLog};
  }else if(mode==="place"){
    const lab=x=>x.n?(x.c/x.n>=.8?"Strong":x.c/x.n>=.5?"Developing":"Limited"):"–";
    const P=SS.place;S.placement={core:lab(P.core),inter:lab(P.inter),adv:lab(P.adv),raw:P,d:t};
    S.placeKnown=[...new Set([...(S.placeKnown||[]),...SS.placeOk])];
    summary={type:"place",placement:S.placement,q:SS.q,c:SS.c};
  }else if(mode==="read"||mode==="clz"||mode==="trap"||mode==="conn"){
    if(mode==="read")S.readDone[SS.pid]=t;if(mode==="clz")S.clozeDone[SS.czid]=t;
    const rch=(mode==="read"||mode==="clz")?readAdjust():null;
    summary={type:mode,q:SS.q,c:SS.c,secs,hard:[...SS.hard],studied:SS.studied,pid:SS.pid,czid:SS.czid,rch,rl:S.readLevel};
  }else{
    const areas=Object.entries(SS.sk).filter(([k,x])=>x.c+x.w>=2).map(([k,x])=>({k,a:x.c/(x.c+x.w)}));
    areas.sort((a,b)=>b.a-a.a);
    const clusters={};SS.newIds.forEach(id=>{const g=BY[id].g;(clusters[g]=clusters[g]||[]).push(id)});
    summary={type:mode,n:SS.newIds.length,r:SS.revIds.length,q:SS.q,c:SS.c,mastered:SS.mastered,weakNow:weakList().length,hard:[...SS.hard].filter(id=>BY[id]),best:areas[0]||null,worst:areas.length>1?areas[areas.length-1]:null,
      tomorrow:Object.values(S.cards).filter(c=>c.due<=t+1).length,pair:SS.pair,clusters,deferred:SS.deferred,rev:SS.revRec,ctx0:SS.ctx0,ctx1:S.ctxLevel,dq:SS.dqSkipped,cluster:SS.cluster};
  }
  const L=S.sessLog.find(x=>x.sid===SS.sid);if(L){L.done=SS.acts||0;L.ok=true;L.secs=Math.min(7200,secs)}
  if(mode!=="place"&&S.calStart==null)S.calStart=t;
  logEv("sessionCompleted",{qt:mode,r:SS.q?Math.round(100*SS.c/SS.q):null});
  if(mode==="read")logEv("readingCompleted",{q:SS.pid,r:SS.q?Math.round(100*SS.c/SS.q):null,d:S.readLevel});
  if(mode==="clz")logEv("clozeCompleted",{q:SS.czid,r:SS.q?Math.round(100*SS.c/SS.q):null,d:S.readLevel});
  if(mode==="yds")logEv("miniYdsCompleted",{q:String(SS.ydsN),r:SS.q?Math.round(100*SS.c/SS.q):null});
  if(summary&&["daily","extra","quick","weak","fav","cluster"].includes(mode))summary.keep3=pick3(SS);
  maintenance();
  REV++;save();SS=null;document.body.classList.remove("in-session");tab="summary";const r0=Date.now();render();perfMilestone(Date.now()-r0);flush();if(typeof window!=="undefined")window.scrollTo(0,0);
}
function exitSession(){
  if(SS){const L=S.sessLog.find(x=>x.sid===SS.sid);if(L){L.done=SS.acts||0;L.ok=false}logEv("sessionAbandoned",{qt:SS.mode,r:SS.planned?Math.round(100*(SS.acts||0)/SS.planned):null})}
  SS=null;sheet=null;document.body.classList.remove("in-session");tab="home";save();flush();render()}
function streakNow(){const t=today();return(S.last===t||S.last===t-1)?S.streak:0}
function days30(){const t=today();let n=0;for(let d=t-29;d<=t;d++)if(S.days[d]&&(S.days[d].q||S.days[d].n||S.days[d].r))n++;return n}

/* ================= HAFTALIK RAPOR VE İÇGÖRÜLER ================= */
function weekStats(end){
  end=end??today();const o={n:0,r:0,q:0,c:0,m:0,days:0,sk:{},g:{},rd:{c:0,w:0}};
  for(let d=end-6;d<=end;d++){const x=S.days[d];if(!x)continue;o.days++;o.n+=x.n||0;o.r+=x.r||0;o.q+=x.q||0;o.c+=x.c||0;o.m+=x.m||0;
    for(const k in x.sk||{}){o.sk[k]=o.sk[k]||{c:0,w:0};o.sk[k].c+=x.sk[k].c;o.sk[k].w+=x.sk[k].w}
    for(const k in x.g||{}){o.g[k]=o.g[k]||{c:0,w:0};o.g[k].c+=x.g[k].c;o.g[k].w+=x.g[k].w}
    if(x.rd){o.rd.c+=x.rd.c;o.rd.w+=x.rd.w}}
  return o;
}
function weeklyReport(){
  const t=today(),a=weekStats(t),b=weekStats(t-7);
  const grp=Object.entries(a.g).filter(([g,x])=>GROUPS[g]&&x.c+x.w>=4).map(([g,x])=>({g,a:x.c/(x.c+x.w),n:x.c+x.w})).sort((x,y)=>y.a-x.a||y.n-x.n);
  const sk=Object.entries(a.sk).filter(([k,x])=>SKILLS[k]&&x.c+x.w>=4).map(([k,x])=>({k,a:x.c/(x.c+x.w)}));
  const imp=sk.map(s=>{const p=b.sk[s.k];return p&&p.c+p.w>=4?{k:s.k,d:s.a-p.c/(p.c+p.w)}:null}).filter(Boolean).sort((x,y)=>y.d-x.d);
  const worst=sk.slice().sort((x,y)=>x.a-y.a)[0]||null;
  const weakG=grp.length>1&&grp[grp.length-1].a<.8?grp[grp.length-1]:null;
  // Gelecek haftanın odak kelimeleri: en zayıf kümedeki (yoksa genel) en düşük ustalıklı / en çok unutulmaya yakın 5 kelime
  const pool=Object.keys(S.cards).filter(id=>BY[id]&&(!weakG||BY[id].g===weakG.g));
  const focusWords=(pool.length>=3?pool:Object.keys(S.cards).filter(id=>BY[id])).sort((x,y)=>(masteryScore(x)+100*retr(S.cards[x],t+7))-(masteryScore(y)+100*retr(S.cards[y],t+7))).slice(0,5);
  const f=focusGroup(),dueNext=Object.values(S.cards).filter(c=>c.due<=t+7).length;
  let focus;
  if(worst&&worst.a<.75)focus=`${SKILLS[worst.k]} soruları (bu hafta %${pct(worst.a)}).`;
  else if(f)focus=`${GROUPS[f.g][0]} grubu (hata oranı %${pct(f.err)}).`;
  else if(dueNext>40)focus=`Tekrarlar: önümüzdeki 7 günde ${dueNext} kelimenin tekrarı var; yeni kelimeyi biraz azaltmak iyi olabilir.`;
  else focus="Yeni kelime ve okuma köprüsü: düzenli tempo iyi gidiyor.";
  return{a,b,acc:a.q?a.c/a.q:null,accPrev:b.q?b.c/b.q:null,strongest:grp[0]||null,improved:imp[0]&&imp[0].d>0?imp[0]:null,needs:worst,focus,weakG,focusWords,mastered:Object.keys(S.cards).filter(id=>statusMap()[id]==="mastered").length};
}
/* Küme ustalığı: kümedeki kelimelerin ustalık puanı, temel kelimeler daha ağır (L1 ×1.5 … L5 ×0.6); görülmemiş kelime 0 sayılır. */
const LV_W={1:1.5,2:1.3,3:1,4:.8,5:.6};
function clusterMastery(ids){
  let s=0,wsum=0,seen=0;for(const id of ids){const w=BY[id];if(!w)continue;const k=LV_W[w.l]||1;wsum+=k;if(S.cards[id]){seen++;s+=k*masteryScore(id)}}
  return{score:wsum?Math.round(s/wsum):0,seen,n:ids.length};
}
function groupMastery(g){return clusterMastery(W.filter(w=>w.g===g).map(w=>w.id))}
function ladderWords(L){return L.steps.flatMap(st=>st.w)}
/* Son 30 gün */
function monthStats(){
  const t=today(),o={days:0,n:0,m:0,fm:0,q:0,c:0,sk:{},rd:{c:0,w:0}};
  for(let d=t-29;d<=t;d++){const x=S.days[d];if(!x)continue;if(x.q||x.n||x.r)o.days++;o.n+=x.n||0;o.m+=x.m||0;o.fm+=x.fm||0;o.q+=x.q||0;o.c+=x.c||0;
    for(const k in x.sk||{}){o.sk[k]=o.sk[k]||{c:0,w:0};o.sk[k].c+=x.sk[k].c;o.sk[k].w+=x.sk[k].w}
    if(x.rd){o.rd.c+=x.rd.c;o.rd.w+=x.rd.w}}
  const dist={new:0,learning:0,familiar:0,weak:0,mastered:0};const sm=statusMap();W.forEach(w=>dist[sm[w.id]]++);
  return Object.assign(o,{acc:o.q?o.c/o.q:null,ctx:accOf(o.sk.ctx),syn:accOf(o.sk.syn),read:accOf(o.rd),dist});
}
/* “Bu hafta ne çalışmalısın?”: en fazla 3 alan + 5 kelime */
function weeklyPlan(r){
  const pr=[];
  if(r.weakG)pr.push(`${GROUPS[r.weakG.g][1]} kümesi (%${pct(r.weakG.a)})`);
  const cd=Object.entries(S.connDim).filter(([k,x])=>x.c+x.w>=6).map(([k,x])=>({k,a:x.c/(x.c+x.w)})).sort((a,b)=>a.a-b.a)[0];
  if(cd&&cd.a<.75)pr.push(`Bağlaç: ${CM_LABEL[cd.k].toLocaleLowerCase("tr-TR")} (%${pct(cd.a)})`);
  if(r.needs&&r.needs.a<.8)pr.push(`${SKILLS[r.needs.k]} soruları (%${pct(r.needs.a)})`);
  const rd=weekStats(today()).rd;if(pr.length<3&&rd&&rd.c+rd.w>=6&&rd.c/(rd.c+rd.w)<.7)pr.push(`Okuma soruları (%${pct(rd.c/(rd.c+rd.w))})`);
  if(!pr.length)pr.push("Düzenli tekrar: tempo iyi, aynı şekilde devam");
  return{areas:pr.slice(0,3),words:r.focusWords.slice(0,5)};
}
function memoryStats(){
  return memo("mem",()=>{const ids=Object.keys(S.cards).filter(id=>BY[id]);if(!ids.length)return null;const t=today();let ms=0,st=0,rt=0;
    for(const id of ids){ms+=masteryScore(id,t);st+=storageStr(S.cards[id]);rt+=retr(S.cards[id],t)}
    return{n:ids.length,mastery:ms/ids.length,storage:st/ids.length,retrieval:rt/ids.length,low:ids.filter(id=>retr(S.cards[id],t)<.5).length}});
}
function insights(){
  const ins=[];const f=focusGroup(),ws=weakestSkill(),lr=lapseRate(),sa=selfAccuracy(),kc=S.self.knowCtx,mem=memoryStats();
  if(f)ins.push({w:1,t:`<b>${esc(GROUPS[f.g][1])}</b> grubunda hata oranın %${pct(f.err)}. Yeni kelimeler ve tekrarlar bu gruba ağırlık veriyor.`});
  if(ws)ins.push({w:1,t:`${SKILL_EN[ws.k]} (${SKILLS[ws.k]}) sorularında başarın %${pct(ws.a)}. Günlük oturumda bu soru tipinin payı artırıldı.`});
  if(sa!=null){
    if(sa<.7)ins.push({w:0,t:`“Biliyorum” dediğin kelimelerin %${pct(sa)}'ini sonraki soruda da doğru cevapladın. Bu çok normal: emin olmadığında “Emin değilim” seçmek, tekrar zamanını sana daha uygun hale getirir.`});
    else ins.push({w:0,t:`Kendini değerlendirmen isabetli: “Biliyorum” dediğin kelimelerin %${pct(sa)}'ini sonraki soruda da doğru cevapladın.`});
  }
  if(kc.n>=4){const miss=1-kc.ok/kc.n;ins.push({w:0,t:miss>=.1?`Bildiğini düşündüğün kelimelerin %${pct(miss)}'inde bağlam sorularında zorlanıyorsun. Anlamı bilmek ile cümlede tanımak farklı beceriler; bu kelimeler bağlam sorularında biraz daha sık gelecek.`:`“Biliyorum” dediğin kelimeleri cümle içinde de tanıyorsun (%${pct(kc.ok/kc.n)}).`})}
  if(S.hardFollow.n>=4)ins.push({w:0,t:`Hard dediğin kelimelerin %${pct(S.hardFollow.ok/S.hardFollow.n)}'ini ertesi gün hatırladın.`});
  if(lr!==null)ins.push({w:lr>=.25?1:0,t:`Unutma hızın ${lr<.12?"düşük":lr<.25?"orta":"yüksek"}: tekrarların %${pct(lr)}'inde kelime unutuldu.`});
  if(mem&&mem.low>=5)ins.push({w:1,t:`${mem.low} kelimenin hatırlanma olasılığı %50'nin altına düştü; günlük tekrarda önce bunlar geliyor.`});
  // Beceri karşılaştırması: anlam güçlü, eş anlam/bağlam geride
  const acc=k=>{const x=S.err[k];return x.c+x.w>=10?x.c/(x.c+x.w):null};
  const am=acc("mean");for(const k of ["syn","ctx"]){const ak=acc(k);if(am!=null&&ak!=null&&am-ak>=.12){ins.push({w:1,t:`Kelime anlamlarında güçlüsün (%${pct(am)}) ancak ${k==="syn"?"eş anlam":"bağlam"} sorularında aynı başarıyı henüz gösteremiyorsun (%${pct(ak)}).`});break}}
  // Kalıcı hafızaya geçen küme
  const sm=statusMap();const gm={};for(const id in S.cards){if(!BY[id])continue;const g=BY[id].g;gm[g]=gm[g]||{n:0,m:0};gm[g].n++;if(sm[id]==="mastered")gm[g].m++}
  const bestG=Object.entries(gm).filter(([g,x])=>GROUPS[g]&&x.n>=4&&x.m/x.n>=.5).sort((a,b)=>b[1].m/b[1].n-a[1].m/a[1].n)[0];
  if(bestG)ins.push({w:0,t:`${esc(GROUPS[bestG[0]][1])} grubundaki kelimeler kalıcı hafızaya geçiyor (${bestG[1].m}/${bestG[1].n} kalıcı).`});
  // Son 7 gün eğilimi
  const wa=weekStats(today()),wb=weekStats(today()-7);
  for(const k of ["ctx","syn","mean"]){const a=wa.sk[k],b=wb.sk[k];if(a&&b&&a.c+a.w>=8&&b.c+b.w>=8){const x=a.c/(a.c+a.w),y=b.c/(b.c+b.w);if(Math.abs(x-y)>=.05){ins.push({w:x<y?1:0,t:`Son 7 günde ${SKILLS[k].toLocaleLowerCase("tr-TR")} başarın %${pct(y)}'ten %${pct(x)}'e ${x>y?"yükseldi":"geriledi"}.`});break}}}
  ins.push({w:0,t:`Bağlam soruları şu an <b>${CTX_LEVELS[S.ctxLevel]}</b> seviyesinde. Son 10 bağlam sorusunun %80'ini doğru yaparsan zorluk artar.`});
  const pl=plan("daily");if(pl.note)ins.push({w:0,t:esc(pl.note)});
  if(pl.why.length)ins.push({w:0,t:`Günlük oran ayarı: ${pl.why.join(", ")} payı artırıldı.`});
  return ins;
}

/* ================= İÇERİK DOĞRULAMA (gizli hata ayıklama) ================= */
function validateContent(){
  const E=[],WARN=[];const add=(type,id,msg)=>E.push({type,id,msg});
  const ids=new Set(),words=new Set();
  for(const w of W){
    if(ids.has(w.id))add("duplicate-id",w.id,"");ids.add(w.id);
    const lw=w.w.toLowerCase();if(words.has(lw))add("duplicate-word",w.id,"");words.add(lw);
    if(!w.tr||!w.tr.trim())add("missing-meaning",w.id,"");
    if(!/\*[^*]+\*/.test(w.ex))add("empty-example",w.id,w.ex);
    if(!w.exTr)add("missing-translation",w.id,"");
    if(!GROUPS[w.g])add("invalid-group",w.id,w.g);
    if(!w.col.length)add("missing-collocations",w.id,"");
    if(!w.syn.length&&!isLink(w))add("invalid-synonyms",w.id,"eş anlam yok");
    if(w.syn.includes(w.w)||new Set(w.syn).size!==w.syn.length||w.syn.some(s=>!s.trim()))add("invalid-synonyms",w.id,w.syn.join(","));
    for(const x of w.cw)if(!BY[x])add("broken-confusedWith",w.id,x);
    if(!w.cz||w.cz.split("___").length!==2)add("bad-cloze",w.id,w.cz);
    if(w.x2&&w.x2.split("___").length!==2)add("bad-x2",w.id,w.x2);
    if(w.czd.includes(w.w)||new Set(w.czd).size!==w.czd.length)add("answer-duplication",w.id,w.czd.join(","));
    if(w.czd.some(d=>w.syn.includes(d)))WARN.push({type:"curated-near-synonym",id:w.id,msg:w.czd.filter(d=>w.syn.includes(d)).join(",")});
    if(w.gd.includes(w.en)||(w.en&&w.syn.length&&w.gd.some(d=>w.syn.includes(d))))add("answer-duplication",w.id,"gd");
    if(!(w.l>=1&&w.l<=5))add("invalid-level",w.id,w.l);
    if(!(w.p>=0&&w.p<=100))add("invalid-priority",w.id,w.p);
    for(const k of ["mean","syn","cloze","guess","yctx","coll","fam","cstruct","cfunc","cid"]){
      if(!available(k,w))continue;const it={k,id:w.id};const o=buildOpts(it);
      const need=k==="fam"?Math.min(4,famForms(w).length+1):k==="yctx"?5:4;
      if(new Set(o.map(x=>x.t)).size<need)add("fewer-than-4-choices",w.id,k+":"+o.length);
      if(o.filter(x=>x.ok).length!==1)add("correct-count",w.id,k);
    }
  }
  const t=today();
  for(const id in S.cards){const c=S.cards[id];
    if(!BY[id])continue;
    if(c.masteredOn!=null&&(c.reps===0||!c.cdays.length))add("impossible-mastered",id,"");
    if(!isFinite(c.due)||c.due>t+400||c.due<c.first-1)add("invalid-review-date",id,c.due);
  }
  // Anlam merdivenleri
  const lu={};LADDERS.forEach(L=>{if(L.steps.length<3||L.steps.length>7)add("ladder-steps",L.id,L.steps.length);L.steps.forEach(st=>{if(!st.note)add("ladder-note",L.id,st.w.join("/"));st.w.forEach(x=>{if(!BY[x])add("ladder-word",L.id,x);lu[x]=(lu[x]||0)+1})})});
  for(const x in lu)if(lu[x]>2)add("ladder-reuse",x,lu[x]);
  for(const w of W)(w.cx||[]).forEach(sn=>{if(sn.split("___").length!==2)add("bad-cx",w.id,sn)});
  PASSAGES.forEach(p=>{const n=p.text.split(/\s+/).length;if(n<75||n>150)add("passage-length",p.id,n);if(!READ_LEVELS.includes(p.difficulty))add("passage-difficulty",p.id,p.difficulty);if(p.questionIds.length!==3)add("passage-questions",p.id,p.questionIds.length)});
  CLOZES.forEach(c=>c.blanks.forEach((b,i)=>{if(!["vocab","connector","preposition","grammar","collocation"].includes(b.type))add("cloze-type",c.id,i)}));
  const chk=(b,src)=>{if(b.o.length!==5||new Set(b.o).size!==5||!(b.a>=0&&b.a<5))add("bank-item",src,b.q.slice(0,40))};
  BANK.forEach((b,i)=>chk(b,"bank"+i));RD.forEach((b,i)=>{chk(b,"rd"+i);if(!PBY[b.p])add("reading-passage",i,b.p)});
  CLOZES.forEach(c=>c.blanks.forEach((b,i)=>{if(new Set(b.o).size!==5)add("cloze-options",c.id,i)}));
  TRAPS.forEach((tr,i)=>{if(tr.s.split("___").length!==2||new Set(tr.o).size!==tr.o.length)add("trap",i,tr.s)});
  const byType={};E.forEach(e=>byType[e.type]=(byType[e.type]||0)+1);
  return{words:W.length,errors:E,warnings:WARN,byType,passed:W.length-new Set(E.filter(e=>BY[e.id]).map(e=>e.id)).size,bank:BANK.length+RD.length};
}
if(typeof window!=="undefined")window.ydsValidate=()=>{const r=validateContent();try{console.log(`[YDS] ${r.passed}/${r.words} kelime doğrulamayı geçti, ${r.errors.length} sorun.`);if(r.errors.length)console.table(r.errors)}catch(e){}return r};

/* Haftalık rapor her 7 günde bir hazırlanır: son görülmeden 7+ gün geçtiyse ve en az 3 çalışma günü varsa */
function weeklyDue(){const t=today();if(S.weeklySeen!=null&&t-S.weeklySeen<7)return false;return weekStats(t).days>=3}

/* ================= v5: OLAY GÜNLÜĞÜ, BAKIM VE KOÇLUK ================= */
const EVT=["sessionStarted","sessionCompleted","sessionAbandoned","wordShown","wordRecalled","wordMissed","questionAnswered","questionCorrect","questionWrong","reviewCompleted","readingCompleted","clozeCompleted","miniYdsCompleted"];
/* Kompakt olay: [zaman, tür, oturum, kelime, soru, soru tipi, tepki ms, zorluk, sonuç, algoritma] — yalnızca bu cihazda, öğrenme algoritması için */
function logEv(type,o){o=o||{};if(!Array.isArray(S.ev))S.ev=[];S.ev.push([Date.now(),EVT.indexOf(type),SS?SS.sid:null,o.w??null,o.q??null,o.qt??null,o.rt??null,o.d??null,o.r??null,ALG]);if(S.ev.length>8000)aggregateEvents(today()-30)}
function evDay(ts){const d=new Date(ts);return Math.floor((ts-d.getTimezoneOffset()*60000)/86400000)}
/* Eski ayrıntılı olaylar günlük özete (dailyStats) taşınır; öğrenme durumu ve tekrar geçmişi korunur. */
function aggregateEvents(beforeDay){
  const keep=[];let moved=0;
  for(const e of S.ev){const d=evDay(e[0]);if(d>=beforeDay){keep.push(e);continue}
    const x=S.dailyStats[d]||(S.dailyStats[d]={e:{},q:0,c:0,rt:0,rtn:0});const ty=EVT[e[1]]||"?";x.e[ty]=(x.e[ty]||0)+1;
    if(ty==="questionCorrect"||ty==="questionWrong"){x.q++;if(ty==="questionCorrect")x.c++}
    if(e[6]!=null){x.rt+=e[6];x.rtn++}moved++}
  S.ev=keep;return moved;
}
function storageChars(){try{return JSON.stringify(S).length}catch(e){return 0}}
const STORAGE_BUDGET=5e6,STORAGE_SOFT=3.5e6,STORAGE_HARD=4.2e6;
function maintenance(){
  const t=today();aggregateEvents(t-90);
  try{trackGaps(t);quadSnapshot(t)}catch(e){}
  let n=storageChars();
  if(n>STORAGE_SOFT){aggregateEvents(t-30);n=storageChars()}
  if(n>STORAGE_HARD){aggregateEvents(t-7);for(const id in S.cards){const c=S.cards[id];if(c.exp)for(const k in c.exp)if(t-c.exp[k]>60)delete c.exp[k]}S.sessLog=S.sessLog.slice(-40);n=storageChars()}
  return n;
}
/* Sürpriz kontrol adayları: kararlı kalıcı kelimeler, kalıcılığın 30/60/90. günü civarı, tekrar zamanı gelmemiş */
function surpriseCandidates(t){
  const out=[];for(const id in S.cards){const c=S.cards[id];if(!BY[id]||c.masteredOn==null||c.due<=t)continue;
    if(c.stableOn==null&&t-c.masteredOn<45)continue;const age=t-c.masteredOn;
    for(const m of [30,60,90])if(Math.abs(age-m)<=3&&!(c.surpr||[]).includes(m)){out.push({id,m});break}}
  return shuffle(out);
}
/* Kırılgan kalıcı: kalıcılıktan 7+ gün sonra doğru bağlam/okuma cevabı → kararlı kalıcı */
function fragileCheck(c,ok){const t=today();if(c.masteredOn==null||c.stableOn!=null||t-c.masteredOn<7)return;S.fragileStats.n++;bump(S.mastCheck,"7",ok);if(ok){S.fragileStats.ok++;c.stableOn=t}}
/* Bugünden aklında kalması gereken 3 kelime */
function pick3(ss){
  const out=[];const nw=ss.newIds.filter(id=>BY[id]).sort((a,b)=>BY[b].p-BY[a].p);if(nw[0])out.push(nw[0]);
  const wk=[...(ss.weakSet||[])].filter(id=>BY[id]&&!out.includes(id));
  const rec=wk.find(id=>statusOf(id)!=="weak")||wk[0]||[...ss.hard].find(id=>BY[id]&&S.cards[id]&&!out.includes(id));if(rec)out.push(rec);
  const base=out[0]||out[1];
  const sem=ss.studied.find(id=>BY[id]&&!out.includes(id)&&base&&(sameLadder(id,base)||BY[id].g===BY[base].g))||ss.studied.find(id=>BY[id]&&!out.includes(id));if(sem)out.push(sem);
  return out.slice(0,3).map(id=>({id,tr:BY[id].tr.split(" / ")[0],col:BY[id].col[0]||""}));
}
/* Oturum tamamlama analizi (son 10 oturum, süreye göre) */
function completionStats(){
  const L=S.sessLog.filter(x=>["daily","extra","quick"].includes(x.mode)).slice(-10),by={};
  for(const x of L){const b=by[x.len]||(by[x.len]={n:0,ok:0});b.n++;if(x.ok)b.ok++}
  let tip=null;const cur=by[S.settings.length];
  if(cur&&cur.n>=3&&cur.ok/cur.n<.7)for(const k in by){if(k!==S.settings.length&&by[k].n>=3&&by[k].ok/by[k].n>=.85){tip=`${LEN[k].min} dakikalık oturumlarda daha düzenli çalışıyorsun (%${pct(by[k].ok/by[k].n)} tamamlama).`;break}}
  return{by,n:L.length,tip};
}
/* Kişisel yeni kelime önerisi: ≥14 çalışma günü ve ≥10 oturum sonra. Tercihin üzerine yazılmaz. */
function suggestNewPerDay(){
  const t=today();let days=0,q=0,c=0;for(let d=t-27;d<=t;d++){const x=S.days[d];if(x&&(x.q||x.n||x.r))days++;if(x&&d>t-14){q+=x.q||0;c+=x.c||0}}
  const sess=S.sessLog.filter(x=>x.d>=t-27&&["daily","extra"].includes(x.mode));
  if(days<14||sess.length<10)return{ready:false,days,sess:sess.length};
  const acc=q?c/q:0,lapse=lapseRate(),backlog=dueList().length,comp=sess.filter(x=>x.ok).length/sess.length,freq=days/28,cur=S.settings.newPerDay;
  let rec=cur;
  if(acc<.75||(lapse!=null&&lapse>.25)||backlog>60||comp<.7)rec=Math.max(5,cur-3);
  else if(acc>=.85&&backlog<25&&comp>=.9&&freq>=.7)rec=Math.min(20,cur+3);
  const text=rec<cur?`Mevcut çalışma düzenine göre günlük ${rec} yeni kelime daha sürdürülebilir görünüyor.`:rec>cur?`Tekrarların dengede ve doğruluğun yüksek; günlük ${rec} yeni kelimeye çıkabilirsin.`:`Günlük ${cur} yeni kelime mevcut temponla uyumlu görünüyor.`;
  return{ready:true,rec,cur,acc,lapse,backlog,comp,freq,days,text};
}
/* YDS hazırlık göstergeleri (yalnızca uygulama içi performans) */
function readiness(){
  const m=monthStats(),sm=statusMap(),lab=(v,n,min,hi,mid)=>n<min?"Veri yetersiz":v>=hi?"Strong":v>=mid?"Developing":"Limited";
  const core=W.filter(w=>w.l<=3),cov=core.filter(w=>sm[w.id]==="mastered"||sm[w.id]==="familiar").length/core.length;
  const meanA=accOf(S.err.mean),nMean=cnt(S.err.mean);
  const vocab=nMean<30?"Veri yetersiz":cov>=.6&&meanA>=.8?"Strong":cov>=.25&&meanA>=.65?"Developing":"Limited";
  const cd=Object.values(S.connDim).reduce((a,x)=>({c:a.c+x.c,w:a.w+x.w}),{c:0,w:0});
  const cz=(()=>{let c=0,w=0;const t=today();for(let d=t-29;d<=t;d++){const x=S.days[d];if(x&&x.cz){c+=x.cz.c;w+=x.cz.w}}return{c,w}})();
  return[{k:"Vocabulary Readiness",v:vocab,d:`Temel+orta kelimelerin %${pct(cov)}'i tanıdık/kalıcı`},
    {k:"Reading Transfer",v:lab(m.read??0,cnt(m.rd),15,.8,.6),d:m.read==null?"":`son 30 gün okuma %${pct(m.read)} · seviye ${READ_LABEL[READ_LEVELS[S.readLevel]]}`},
    {k:"Connectors",v:lab(accOf(cd)??0,cnt(cd),20,.85,.65),d:cnt(cd)?`bağlaç soruları %${pct(accOf(cd))}`:""},
    {k:"Context",v:lab(m.ctx??0,cnt(m.sk.ctx),20,.8,.6),d:m.ctx==null?"":`son 30 gün bağlam %${pct(m.ctx)} · ${CTX_LEVELS[S.ctxLevel]}`},
    {k:"Cloze",v:lab(accOf(cz)??0,cnt(cz),10,.8,.6),d:cnt(cz)?`cloze boşlukları %${pct(accOf(cz))}`:""}];
}
/* Ana ekranda tek öneri */
function homeTip(){
  const t=today();if(!Object.keys(S.cards).length)return null;
  const p=plan("daily"),rg=taggedIds("RecognitionGap").length,le=taggedIds("Leech").length;
  if(p.load==="heavy")return"Tekrar yükün yüksek; bugün yeni kelimeyi azaltıp unutulmaya en yakın kelimelere odaklanıyoruz.";
  if(rg>=5)return`Bugün bağlam çalışmalarına biraz daha ağırlık vereceğiz: ${rg} kelimeyi kartta tanıyorsun ama soruda kaçırıyorsun.`;
  const wr=weeklyReport();if(wr.weakG){const n=W.filter(w=>w.g===wr.weakG.g&&S.cards[w.id]&&p.dueAll.includes(w.id)).length;if(n>=2)return`Son günlerde ${GROUPS[wr.weakG.g][1]} grubunda zorlandığın için ${n} kelimeyi yeniden göreceksin.`}
  if(le)return`${le} kelime çok tekrar etmene rağmen oturmadı; bugün onları farklı bir yöntemle göreceksin.`;
  const sg=suggestNewPerDay();if(sg.ready&&sg.rec!==sg.cur)return sg.text;
  const ct=completionStats();if(ct.tip)return ct.tip;
  if(p.dueAll.length<15&&p.newIds.length)return`Tekrar yükün düşük; bugün ${p.newIds.length} yeni kelime ekleyebiliriz.`;
  return null;
}
/* Haftalık 3 kazanım (gerçek veriden) */
function weeklyWins(){
  const t=today(),a=weekStats(t),b=weekStats(t-7),out=[];
  if(a.m>0)out.push(`${a.m} kelime Kalıcı seviyesine geçti.`);
  for(const k of ["ctx","syn","mean","conf"]){const x=a.sk[k],y=b.sk[k];if(cnt(x)>=8&&cnt(y)>=8){const nx=x.c/cnt(x),ny=y.c/cnt(y);if(nx-ny>=.05){out.push(`${SKILLS[k]} doğruluğun %${pct(ny)} → %${pct(nx)} yükseldi.`);break}}}
  const gs=Object.keys(a.g).filter(g=>GROUPS[g]).map(g=>({g,...groupMastery(g)})).filter(x=>x.score>=50).sort((x,y)=>y.score-x.score);
  if(gs[0])out.push(`${GROUPS[gs[0].g][1]} kümesinde ustalık %${gs[0].score} oldu.`);
  if(out.length<3&&a.days>=4)out.push(`Son 7 günün ${a.days}'ında çalıştın.`);
  if(out.length<3&&a.rd&&cnt(a.rd)>=6&&a.rd.c/cnt(a.rd)>=.7)out.push(`Okuma sorularında %${pct(a.rd.c/cnt(a.rd))} doğruluk.`);
  return out.slice(0,3);
}
/* Mini YDS eğilimi: son 5 / 10 / 20 test; yeterli veri yoksa üretilmez */
function miniTrend(){
  if(S.mini.length<5)return null;const types=["vocab","ct","sc","tr","rs","pc","rd"];const out={};
  for(const N of [5,10,20]){if(S.mini.length<N&&N!==5)continue;const last=S.mini.slice(-N);
    for(const tp of types){const x=last.reduce((a,m)=>{const v=m.bt&&m.bt[tp];return v?{c:a.c+v.c,w:a.w+v.w}:a},{c:0,w:0});(out[tp]=out[tp]||{})[N]=cnt(x)>=5?x.c/cnt(x):null}}
  return out;
}
function calibDashboard(){
  const rev=S.ev.filter(e=>EVT[e[1]]==="reviewCompleted").length+Object.values(S.dailyStats).reduce((a,x)=>a+(x.e.reviewCompleted||0),0);
  const rts=S.rtStats;const tot=S.schedTot;
  let days=0;const t=today();for(const d in S.days){const x=S.days[d];if(x.q||x.n||x.r)days++}
  return{reviews:rev,brier:S.brier.n?S.brier.sum/S.brier.n:null,calib:calibReport(),rt:rts.n?rts.sum/rts.n:null,rtDropped:rts.dropped,hard:S.hardStats,
    easy:accOf({c:tot.easy.ok,w:tot.easy.n-tot.easy.ok}),good:accOf({c:tot.good.ok,w:tot.good.n-tot.good.ok}),hardR:accOf({c:tot.hard.ok,w:tot.hard.n-tot.hard.ok}),tot,spacing:S.spacing,log:S.schedLog,
    leech:taggedIds("Leech"),recog:taggedIds("RecognitionGap"),recall:taggedIds("RecallGap"),fragile:taggedIds("FragileMastered"),pairs:personalPairs(),days,ready:days>=14,
    chars:storageChars(),events:S.ev.length,agg:Object.keys(S.dailyStats).length,alg:ALG,algHistory:S.algHistory,transfer37:S.transfer37,surprise:S.surpriseStats,fragileStats:S.fragileStats};
}
maintenance();

/* ================= KALİBRASYON DÖNEMİ (ölçüm; algoritmayı değiştirmez) ================= */
function studyDaysSince(start){if(start==null)return 0;let n=0;for(const d in S.days){const x=S.days[d];if(+d>=start&&(x.q||x.n||x.r))n++}return n}
function calDay(){return studyDaysSince(S.calStart)}
function calStatus(){const d=calDay();return d<14?"Early Data":d<30?"Calibration in Progress":"Calibration Ready"}
/* Yeniden hatırlama gözlemi: önceki puana ve aradaki güne göre (1/3/7/14) + doğru cevap hız kovası + leech kurtarma */
function gapBucket(g){return g<=1?"1":g<=4?"3":g<=10?"7":g<=20?"14":null}
function retrievalObs(c,ok,t,quiz){
  const g=t-c.lastRev,b=gapBucket(g),prev={e:"easy",g:"good",h:"hard",a:"again"}[c.rat[c.rat.length-1]];
  if(b&&prev&&prev!=="again"&&!(prev==="hard"&&b==="14")){const k=prev+":"+b;bump(S.ratingGap,k,ok)}
  if(c.rtB&&t>c.rtB.d){bump(S.rtNext,c.rtB.b,ok);c.rtB=null}
  if(c.leechTrack&&t>c.leechTrack.t){const L=c.leechTrack,lg=t-L.t,lb=lg<=2?"d1":lg<=5?"d3":lg<=10?"d7":null;
    if(lb&&!L.seen[lb]){L.seen[lb]=1;S.leechRec[lb].n++;if(ok)S.leechRec[lb].ok++}
    if(!ok){L.fails++;if(L.fails>=2){c.restUntil=t+3;S.leechRest++;c.leechTrack=null;c.exp={}}}   // özel çalışmadan sonra da gelişme yoksa 3 gün dinlenme, sonra farklı bağlam
    else L.fails=0;
    if(lg>10)c.leechTrack=null}
}
/* Anında / gecikmeli aktarım: daha önce görülmemiş bağlam, okuma veya cloze sorusu */
function delayedTransfer(c,it,ok,t,skill){
  if(skill!=="ctx"||it.k==="reverse")return;
  const unseen=it.k==="yds"||it.k==="rdq"?!(S.qstats[it.bank]&&S.qstats[it.bank].n>1):it.sk?!(c.exp&&c.exp[it.sk]!=null&&c.exp[it.sk]<t):true;
  if(!unseen)return;const age=t-c.first;
  if(age<=1){c.trI=c.trI||{c:0,w:0};bump(c,"trI",ok);bump(S,"immediate",ok)}
  else if(age>=3&&age<=7){c.trD=c.trD||{c:0,w:0};bump(c,"trD",ok);bump(S,"delayed",ok)}
}
function transferGap(id){return wordTags(id).has("RecognitionGap")||quadrantOf(id)==="B"}
/* Bellek ve aktarım dört grubu: A yüksek/yüksek · B bellek yüksek/aktarım düşük · C bellek düşük/aktarım yüksek · D düşük/düşük */
function quadrantOf(id){const c=S.cards[id];if(!c)return null;const tf=transferScore(id);if(!tf)return null;const m=masteryScore(id)>=70,tr=tf.score>=70;return m&&tr?"A":m?"B":tr?"C":"D"}
function quadrants(){return memo("quad",()=>{const o={A:0,B:0,C:0,D:0,none:0,B_ids:[]};for(const id in S.cards){if(!BY[id])continue;const q=quadrantOf(id);if(!q)o.none++;else{o[q]++;if(q==="B")o.B_ids.push(id)}}return o})}
function quadSnapshot(t){if(S.quadHist.length&&S.quadHist[S.quadHist.length-1].d===t)return;const q=quadrants();S.quadHist.push({d:t,A:q.A,B:q.B,C:q.C,D:q.D});if(S.quadHist.length>120)S.quadHist.shift()}
/* Recognition / Recall Gap doğrulaması: etiketlenen kelime 14 gün sonra yeniden değerlendirilir */
function directAcc(c){const r=c.rat.slice(-6).map(x=>x==="g"||x==="e"?1:x==="h"?.5:0);const m=c.sk.mean||{c:0,w:0};const n=r.length+m.c+m.w;return n?{a:(r.reduce((a,b)=>a+b,0)+m.c)/n,n}:null}
function trackGaps(t){
  for(const id in S.cards){if(!BY[id])continue;const tags=wordTags(id,t),c=S.cards[id];
    for(const [tag,key] of [["RecognitionGap","RG"],["RecallGap","RC"]]){
      const tr=S.gapTrack[key+":"+id];
      if(!tr&&tags.has(tag)){const da=directAcc(c);S.gapTrack[key+":"+id]={since:t,before:da?da.a:null,n0:da?da.n:0}}
      else if(tr&&!tr.done&&t-tr.since>=14){tr.done=t;tr.resolved=!tags.has(tag);S.gapStats[key].n++;if(tr.resolved)S.gapStats[key].resolved++;
        if(key==="RC"){const da=directAcc(c);if(da&&tr.before!=null&&da.n>=tr.n0+3){S.gapStats.RC.before+=tr.before;S.gapStats.RC.after+=da.a;S.gapStats.RC.m=(S.gapStats.RC.m||0)+1}}}}}
}
/* Leech nedeni (yaklaşık) */
function lev(a,b){if(Math.abs(a.length-b.length)>2)return 9;const d=[...Array(b.length+1).keys()];for(let i=1;i<=a.length;i++){let p=d[0];d[0]=i;for(let j=1;j<=b.length;j++){const tmp=d[j];d[j]=Math.min(d[j]+1,d[j-1]+1,p+(a[i-1]===b[j-1]?0:1));p=tmp}}return d[b.length]}
function leechReason(id){
  const c=S.cards[id],w=BY[id];if(!c)return null;
  const confs=Object.keys(S.conf[id]||{}).concat(Object.keys(S.conf).filter(k=>S.conf[k][id]));
  const spell=confs.find(x=>BY[x]&&x!==id&&w.w.length>=5&&lev(w.w,x)<=2)||W.find(x=>x.id!==id&&S.cards[x.id]&&w.w.length>=6&&x.w.slice(0,5)===w.w.slice(0,5));
  if(spell)return{r:"Spelling similarity",tr:"Yazım benzerliği",d:typeof spell==="string"?spell:spell.w};
  if((c.confErr||0)>=2||confs.some(x=>confusionCount(id,x)>=2))return{r:"Confusion",tr:"Karıştırma",d:confs[0]||""};
  const fam=W.filter(x=>x.id!==id&&S.cards[x.id]&&Math.abs(S.cards[x.id].first-c.first)<=3&&(sameLadder(id,x.id)||(x.g===w.g&&(w.syn.includes(x.w)||x.syn.includes(w.w)))));
  if(fam.length>=3)return{r:"Synonym overload",tr:"Eş anlam yükü",d:fam.slice(0,3).map(x=>x.w).join(", ")};
  const ca=smAcc(c.sk.ctx),ma=directAcc(c);if(ca!=null&&ca<.5&&ma&&ma.a>=.6)return{r:"Weak context transfer",tr:"Bağlama aktarım zayıf",d:""};
  if(c.lapses>=3||(c.forgot||0)>=1)return{r:"Repeated forgetting",tr:"Tekrar tekrar unutma",d:`${c.lapses} unutma`};
  return{r:"Low exposure quality",tr:"Düşük nitelikli tekrar",d:`${c.cdays.length} farklı günde doğru`};
}
/* Karar motoru: öğrenme değeri (iç kullanım) */
function learningValueScore(id,t,p){
  const c=S.cards[id],w=BY[id];if(!c)return 0;p=p??recallProbability(id,t);
  const overdue=Math.min(1,Math.max(0,t-c.due)/7),weak=weakScore(id)/100,gap=transferGap(id)?1:0,lee=wordTags(id).has("Leech")?1:0;
  const recent=(c.lastRev===t?1:0);const sem=(LADBY[id]||[]).length?1:0;
  return 40*(1-p)*(1+overdue)+15*(w.p/100)+15*Math.max(weak,lee*.6)+15*gap+5*sem-25*recent+(c.hardPending?5:0);
}
/* Soru anahtarı (geri bildirim / tekrar eden yanlış seçenek) */
function qKey(it){return it.bank?it.bank:it.k==="clz"?`clz:${it.cz.id}:${it.bi}`:it.k==="trap"?`trap:${it.t.s.slice(0,40)}`:`${it.k}:${it.id||""}:${it.sk||""}`}
/* Brier yorumu */
function brierLabel(){const n=S.brier.n,b=n?S.brier.sum/n:null;if(b==null)return{b,l:"Insufficient Data"};const l=b<.15?"Good":b<.2?"Acceptable":b<.25?"Needs calibration":"Poor calibration";return{b,l:n<100?`${l} (n<100, kesin değil)`:l,n}}
function gapRate(k){const x=S.ratingGap[k];return x?{a:x.c/(x.c+x.w),n:x.c+x.w}:{a:null,n:0}}
function rateOf(x){return x&&x.n?{a:x.ok/x.n,n:x.n}:{a:null,n:0}}
/* REAL USER CALIBRATION */
function realCalibration(){
  const t=today(),sessions=S.sessLog.filter(x=>x.ok),all=S.sessLog.filter(x=>["daily","extra","quick"].includes(x.mode));
  const durs=sessions.map(x=>x.secs).filter(x=>x!=null);
  const tot=S.schedTot,acc=x=>x.n?{a:x.ok/x.n,n:x.n}:{a:null,n:0};
  const tfAgg=k=>{let c=0,w=0;for(const id in S.cards){const x=(S.cards[id].tr||{})[k];if(x){c+=x.c;w+=x.w}}return{a:c+w?c/(c+w):null,n:c+w}};
  return{calDay:calDay(),status:calStatus(),studyDays:studyDaysSince(-1e9),sessions:sessions.length,reviews:calibDashboard().reviews,
    unique:Object.values(S.cards).filter(c=>c.reps>0).length,newWords:Object.values(S.cards).filter(c=>S.calStart!=null&&c.first>=S.calStart).length,
    predicted:S.brier.n?S.calib.reduce((a,b)=>a+b.ps,0)/S.brier.n:null,actual:S.brier.n?S.calib.reduce((a,b)=>a+b.ok,0)/S.brier.n:null,brier:brierLabel(),
    easy:acc(tot.easy),good:acc(tot.good),hard:acc(tot.hard),hard1:rateOf(S.hardStats.d1),hard3:rateOf(S.hardStats.d3),hard7:rateOf(S.hardStats.d7),
    recog:taggedIds("RecognitionGap").length,recall:taggedIds("RecallGap").length,leech:taggedIds("Leech").length,fragile:taggedIds("FragileMastered").length,forgotten:S.forgotMastered||0,
    readT:tfAgg("read"),clzT:tfAgg("clz"),yvT:tfAgg("yv"),delayed:rateOf({n:S.delayed.c+S.delayed.w,ok:S.delayed.c}),immediate:rateOf({n:S.immediate.c+S.immediate.w,ok:S.immediate.c}),
    avgSecs:durs.length?durs.reduce((a,b)=>a+b,0)/durs.length:null,completion:all.length?all.filter(x=>x.ok).length/all.length:null,chars:storageChars(),events:S.ev.length,agg:Object.keys(S.dailyStats).length};
}
/* Önerilen kalibrasyon değişiklikleri: yalnızca yeterli veriyle; otomatik uygulanmaz (onaydan sonra scheduler-v3) */
function recommendedChanges(){
  const out=[],tot=S.schedTot;
  const chk=(k,lo,hi,label)=>{const x=tot[k];if(x.n<40)return;const a=x.ok/x.n;if(a>hi+.03)out.push(`${label} sonrası gerçek hatırlama %${pct(a)} (hedef %${pct(lo)}–${pct(hi)}, n=${x.n}) → ${label} aralığı biraz uzatılabilir.`);else if(a<lo-.03)out.push(`${label} sonrası gerçek hatırlama %${pct(a)} (hedef %${pct(lo)}–${pct(hi)}, n=${x.n}) → ${label} aralığı kısaltılmalı.`)};
  chk("good",.8,.9,"Good");chk("easy",.9,.97,"Easy");chk("hard",.6,.75,"Hard");
  const h3=gapRate("hard:3");if(h3.n>=20&&h3.a<.5)out.push(`Hard 3 gün hatırlama %${pct(h3.a)} (n=${h3.n}) → Hard aralığı kısaltılmalı.`);
  const rb=["<3","3–7","7–15","15–30"].map(b=>({b,...(S.rtNext[b]?{a:S.rtNext[b].c/(S.rtNext[b].c+S.rtNext[b].w),n:S.rtNext[b].c+S.rtNext[b].w}:{a:null,n:0})}));
  const f=rb[0],sl=rb.slice(2).filter(x=>x.n>=20)[0];if(f.n>=20&&sl){if(f.a-sl.a<.05)out.push(`Hızlı (<3 sn) ve yavaş doğru cevapların sonraki hatırlaması benzer (%${pct(f.a)} / %${pct(sl.a)}) → tepki süresinin ustalık etkisi azaltılmalı.`);else out.push(`Tepki süresi sonraki hatırlamayı öngörüyor (%${pct(f.a)} / %${pct(sl.a)}) → mevcut düşük ağırlık korunabilir.`)}
  const G=S.gapStats.RG;if(G.n>=10)out.push(`Recognition Gap: 14 gün sonra %${pct(G.resolved/G.n)} etiketten çıktı (n=${G.n}) → ${G.resolved/G.n>=.5?"bağlam ağırlıklı yöntem etkili":"yöntem yeniden değerlendirilmeli"}.`);
  const RC=S.gapStats.RC;if((RC.m||0)>=8)out.push(`Recall Gap: doğrudan hatırlama %${pct(RC.before/RC.m)} → %${pct(RC.after/RC.m)} (n=${RC.m}).`);
  const m30=S.mastCheck["30"];if(m30&&m30.c+m30.w>=20){const a=m30.c/(m30.c+m30.w);out.push(`Kalıcı kelimelerin 30. gün kontrol başarısı %${pct(a)} (n=${m30.c+m30.w}) → ${a<.8?"Mastered kriteri gevşek olabilir; eşik yeniden değerlendirilmeli":"Mastered kriteri yeterli görünüyor"}.`)}
  const L=S.leechRec.d7;if(L.n>=10)out.push(`Leech yöntemi: özel karttan 7 gün sonra hatırlama %${pct(L.ok/L.n)} (n=${L.n}).`);
  const sg=suggestNewPerDay();if(sg.ready&&sg.rec!==sg.cur)out.push(sg.text);
  const cs=completionStats();if(cs.tip)out.push(cs.tip);
  return out;
}
/* 30 günlük öğrenme raporu */
function report30(){
  const st=S.calStart,days=Object.keys(S.days).filter(d=>+d>=(st??0)).map(d=>S.days[d]);
  const sum=k=>days.reduce((a,x)=>a+(x[k]||0),0),skc=k=>days.reduce((a,x)=>{const v=x.sk&&x.sk[k];return v?{c:a.c+v.c,w:a.w+v.w}:a},{c:0,w:0});
  const rd=days.reduce((a,x)=>x.rd?{c:a.c+x.rd.c,w:a.w+x.rd.w}:a,{c:0,w:0}),cz=days.reduce((a,x)=>x.cz?{c:a.c+x.cz.c,w:a.w+x.cz.w}:a,{c:0,w:0});
  const gs=Object.keys(GROUPS).map(g=>({g,...groupMastery(g)})).filter(x=>x.seen>=3).sort((a,b)=>b.score-a.score);
  const tfs=Object.keys(S.cards).map(id=>transferScore(id)).filter(Boolean);
  const secs=S.sessLog.filter(x=>x.d>=(st??0)&&x.secs).reduce((a,x)=>a+x.secs,0);
  const rc=realCalibration();
  return{studyDays:rc.calDay,studyMin:Math.round(secs/60),introduced:sum("n"),mastered:sum("m"),forgotten:days.reduce((a,x)=>a+(x.fm||0),0),reviews:rc.reviews,
    memory:accOf(S.err.mean),transfer:tfs.length?tfs.reduce((a,x)=>a+x.score,0)/tfs.length/100:null,delayed:rc.delayed,
    best:gs.slice(0,3),weakest:gs.slice(-3).reverse(),recog:rc.recog,recall:rc.recall,leech:rc.leech,easy:rc.easy,good:rc.good,hard:rc.hard,
    spacing:S.spacing,brier:rc.brier,reading:accOf(rd),cloze:accOf(cz),mini:miniTrend(),newRec:suggestNewPerDay(),lenRec:completionStats().tip,changes:recommendedChanges()};
}
/* Performans kaydı: 1 / 14 / 30 / 60 / 90. çalışma günü */
function perfMilestone(renderMs){const d=calDay();for(const m of [1,14,30,60,90])if(d>=m&&!S.perfLog.some(x=>x.m===m)){S.perfLog.push({m,d:today(),chars:storageChars(),events:S.ev.length,agg:Object.keys(S.dailyStats).length,renderMs:Math.round(renderMs)})}}

/* ================= GÖRÜNÜMLER ================= */
function announce(msg){const el=document.getElementById("live");if(el){el.textContent="";setTimeout(()=>{el.textContent=msg},30)}}
function starBtn(id){return`<button class="star" data-act="fav" data-v="${esc(id)}" aria-pressed="${isFav(id)}" aria-label="${isFav(id)?"Favorilerden çıkar":"Favorilere ekle"}">${isFav(id)?"★":"☆"}</button>`}
function head(w,tags){return`<div class="whead"><div class="wtype">${esc(posLabel(w.pos))} · L${w.l} ${esc(LEVELS[w.l])}${tags||""}</div><div class="word">${esc(w.w)}</div>${starBtn(w.id)}</div>`}
function related(w){
  const same=W.filter(x=>x.g===w.g&&x.id!==w.id);
  same.sort((a,b)=>((w.syn.includes(b.w)||b.syn.includes(w.w))-(w.syn.includes(a.w)||a.syn.includes(w.w)))||(b.p-a.p));
  const opp=GROUPS[w.g]&&GROUPS[w.g][2];
  let anti=w.ant.filter(a=>BY[a]).map(a=>BY[a]);
  if(opp)W.filter(x=>x.g===opp).sort((a,b)=>b.p-a.p).forEach(x=>{if(!anti.includes(x))anti.push(x)});
  return{rel:same.slice(0,4),anti:anti.slice(0,4),opp};
}
function connPanel(w){
  if(!w.cn)return"";
  return`<div class="sec conn"><h4>Bağlaç ustası · ${esc(CONN_FN[w.g]||"")}</h4>
  <dl class="cdl"><dt>Yapı</dt><dd><b>${esc(w.w)}</b> ${esc(STRUCT_SHORT[w.cn.struct])} · ${esc(STRUCT[w.cn.struct])}</dd>
  <dt>Konum</dt><dd>${esc(w.cn.position)}</dd><dt>Noktalama</dt><dd>${esc(w.cn.punct)}</dd><dt>Farkı</dt><dd>${esc(w.cn.diff)}</dd></dl></div>`;
}
/* Aşamalı gösterim: ilk karşılaşma → anlam, 2 eş anlam, 2 kalıp, 1 örnek; tanıdık → aile, dil bilgisi kalıbı, ek bağlam, ağ; kalıcı → nüans, yakın eş anlamlar, ileri kalıplar, aktarım */
function cardStage(w,full){if(full)return 3;const c=S.cards[w.id];if(!c||!c.reps)return 1;if(statusMap()[w.id]==="mastered")return 3;return(c.step>=2||c.cdays.length>=2)?2:1}
function cardBody(w,fullFam){
  const c=S.cards[w.id],st=cardStage(w,fullFam);
  const {rel,anti,opp}=related(w);
  const chain=[...new Set([w.w,...w.syn.slice(0,2),w.en].filter(Boolean))].join(" → ");
  const cws=w.cw.filter(x=>BY[x]);
  const extra=st>=2?(blankSents(w,"cloze").find(([k])=>k!=="cz")||[])[1]:null;
  const near=st>=3?w.syn.filter(x=>BY[x]).map(x=>({x,r:relOf(w.id,x)})).filter(o=>o.r):[];
  const tf=st>=3&&c?transferScore(w.id):null;
  const more=st<3&&!fullFam?`<button class="link" data-act="famopen">Daha fazla bilgi göster</button>`:"";
  return`<div><div class="meaning">${esc(w.tr)}</div>${w.tr2&&st>=2?`<div class="meaning2">Diğer anlam: ${esc(w.tr2)}</div>`:""}</div>
  <div class="two">
    <div class="sec"><h4>Eş anlamlılar</h4><div class="chips">${w.syn.slice(0,st>=2?4:2).map(s=>`<span class="chip">${esc(s)}</span>`).join("")}</div>
    ${st>=2&&w.ant.length?`<div class="chips">${w.ant.slice(0,2).map(s=>`<span class="chip ant">≠ ${esc(s)}</span>`).join("")}</div>`:""}
    ${st>=3&&(w.nu||useNote(w.id))?`<p class="small muted">${esc(w.nu||useNote(w.id))}</p>`:""}</div>
    <div class="sec"><h4>Sık kalıplar</h4><ul class="colls">${w.col.slice(0,st>=3?9:2).map(s=>`<li>${esc(s)}</li>`).join("")}</ul></div>
  </div>
  ${st>=2&&w.pat.length?`<div class="sec"><h4>Dil bilgisi kalıbı · grammar pattern</h4><div class="chips">${w.pat.map(s=>`<span class="chip pat">${esc(s)}</span>`).join("")}</div></div>`:""}
  ${st>=2||isLink(w)?connPanel(w):""}
  <div class="sec"><h4>YDS örneği</h4><p class="ex">${exHtml(w)}</p><p class="extr">${esc(w.exTr)}</p>${extra?`<p class="extr">${esc(cap(extra.replace("___",w.w)))}</p>`:""}</div>
  ${st>=2&&w.fam.length?`<div class="sec"><h4>Kelime ailesi</h4><div class="chips">${w.fam.map(f=>`<span class="chip">${esc(f[0])} <small class="muted">${esc(f[1])}</small></span>`).join("")}</div></div>`:""}
  ${st>=2?`<div class="sec"><h4>Kelime ağı</h4><div class="net">
    ${rel.length?`<div class="netrow"><span class="lab">İlişkili</span><span class="ws">${rel.map(m=>`<span>${esc(m.w)} <small>${esc(m.tr.split(" / ")[0])}</small></span>`).join("")}</span></div>`:""}
    ${anti.length?`<div class="netrow"><span class="lab">${opp?"Karşıt grup":"Zıt"}</span><span class="ws">${anti.map(m=>`<span>${esc(m.w)} <small>${esc(m.tr.split(" / ")[0])}</small></span>`).join("")}</span></div>`:""}
    <div class="netrow"><span class="lab">Hafıza bağı</span><span class="chain">${esc(chain)}</span></div>
  </div></div>`:""}
  ${near.length?`<div class="sec"><h4>Yakın eş anlamlar</h4><p class="small">${near.map(o=>`<b>${esc(o.x)}</b> · ${REL_TR[o.r[0]]}: ${esc(o.r[1])}`).join("<br>")}</p></div>`:""}
  ${tf?`<p class="small muted">Sınav benzeri sorularda kullanım (aktarım): ${tf.score}/100</p>`:""}
  ${(st>=2||fullFam)&&cws.length?`<div class="cw">⚠ Karıştırma: ${cws.map(x=>`<b>${esc(x)}</b> (${esc(BY[x].tr.split(" / ")[0])})`).join(", ")}</div>`:""}
  ${(st>=2||fullFam)&&w.cwx?`<div class="cw">⚠ ${esc(w.cwx)}</div>`:""}
  ${more}`;
}
function loadBadge(p){return`<span class="load ${p.load}"><span aria-hidden="true">${p.load==="light"?"○":p.load==="normal"?"◐":"●"}</span> ${LOAD[p.load]} yük</span>`}

function vHome(){
  const t=today(),done=S.doneDay===t,p=plan("daily");
  const date=new Date().toLocaleDateString("tr-TR",{weekday:"long",day:"numeric",month:"long"});
  const total=p.newIds.length+p.review.length+p.weak.length+p.early.length;
  const sm=statusMap();const mastered=Object.values(sm).filter(x=>x==="mastered").length;
  const weakN=weakList().length,dueN=p.dueAll.length;
  const seg=Object.entries(LEN).map(([k,v])=>`<button data-act="len" data-v="${k}" aria-pressed="${S.settings.length===k}">${v.label}<small>${v.min} dk</small></button>`).join("");
  let body;
  if(done){
    const tomorrow=Object.values(S.cards).filter(c=>c.due<=t+1).length;
    body=`<div><div class="eyebrow">Bugünkü çalışma</div><h1>Bugünün çalışması tamam.</h1></div>
    <p class="muted">Yarın <b class="num" style="color:var(--ink)">${tomorrow}</b> kelime tekrar için hazır olacak. Aynı gün aşırı tekrar uzun süreli hafızaya katkı sağlamaz; biraz unutup yeniden hatırlamak kalıcılığı artırır.</p>
    <button class="btn btn-ghost" data-act="extra">Ek çalışma: 5 yeni kelime${weakN?` + zayıf kelimeler`:""}</button>`;
  }else if(!total){
    body=`<div><div class="eyebrow">Bugünkü çalışma</div><h1>Bugün tekrar zamanı gelen kelime yok.</h1></div><p class="muted">${S.noNewDay===t?"Bugün yeni kelime almamayı seçtin.":"Havuzdaki bütün kelimeleri öğrendin."}</p>${S.noNewDay===t?`<button class="link" data-act="nonew">Yeni kelimeleri yeniden aç</button>`:""}`;
  }else{
    body=`<div><div class="eyebrow">Bugünkü çalışma · ${loadBadge(p)}</div><h1>Hatırla, ilişkilendir ve kullan.</h1></div>
    <div class="planline"><span><b>${p.newIds.length}</b> yeni</span><span><b>${p.review.length+p.early.length}</b> tekrar</span><span class="w"><b>${p.weak.length}</b> zayıf</span><span>yaklaşık <b>${p.minutes} dk</b></span></div>
    <div class="lenrow"><span class="seg" role="group" aria-label="Çalışma süresi">${seg}</span><button class="link" data-act="nonew">${S.noNewDay===t?"Yeni kelimeleri yeniden aç":"Bugün yeni kelime istemiyorum"}</button></div>
    ${(()=>{const tip=homeTip();return tip?`<p class="tip">${esc(tip)}</p>`:p.note?`<p class="notice">${esc(p.note)}</p>`:""})()}
    ${p.overflow.length?`<p class="notice">Kapasiteyi aşan ${p.overflow.length} tekrar, en iyi hatırladıkların önce olmak üzere sonraki günlere yayılacak.</p>`:""}
    <button class="btn btn-primary" data-act="start">BUGÜNKÜ ÇALIŞMAYA BAŞLA</button>`;
  }
  return`<header class="topbar"><div><div class="eyebrow">${esc(date)}</div><div class="brand">YDS Kelime Atölyesi</div></div></header>
  <div class="stack">
    <section class="stats4">
      <div class="stat"><span class="n">${streakNow()}</span><span class="l">Gün seri · en iyi ${S.best||0} · ${days30()}/30</span></div>
      <div class="stat"><span class="n">${dueN}</span><span class="l">Tekrar bekleyen</span></div>
      <div class="stat weak"><span class="n">${weakN}</span><span class="l">Zayıf kelime</span></div>
      <div class="stat mast"><span class="n">${mastered}</span><span class="l">Kalıcı kelime</span></div>
    </section>
    ${weeklyDue()?`<button class="sc wide banner" data-act="weekly"><b>Haftalık raporun hazır</b><span>Son 7 günün özeti ve gelecek haftanın odak kelimeleri</span></button>`:""}
    <section class="today">${body}</section>
    <section class="shortcuts">
      <button class="sc" data-act="quick"${dueN?"":" disabled"}><b>Hızlı tekrar</b><span>${dueN?`${Math.min(dueN,30)} kelime, önce unutulmaya yakın olanlar`:"Bekleyen tekrar yok"}</span></button>
      <button class="sc" data-act="ydsopen"><b>Mini YDS</b><span>5–40 soru · ${BANK.length+RD.length} soruluk banka</span></button>
      <button class="sc" data-act="weak"${weakN?"":" disabled"}><b>Zayıf kelimeler</b><span>${weakN?`${Math.min(weakN,8)} kelime, farklı soru tipleri`:"Şu an zayıf kelime yok"}</span></button>
      <button class="sc" data-act="tab" data-v="study"><b>Diğer modlar</b><span>Bağlaç, tuzak, okuma, cloze</span></button>
    </section>
    <p class="slogan">Ezberleme. Hatırla, ilişkilendir ve kullan.</p>
    <p class="flow">Gör → Hatırla → Bağla → Kullan → Biraz unut → Yeniden hatırla → Kalıcı</p>
  </div>`;
}

/* Karşılama: en fazla 3 adım; yalnızca ilk oturum yükünü ayarlar */
let OB={step:0};
function needsOnboarding(){return!S.profile&&!Object.keys(S.cards).length}
const OB_Q=[{k:"target",q:"YDS hedefin nedir?",o:["50–60","60–70","70–80","80+"]},{k:"minutes",q:"Günde kaç dakika çalışabilirsin?",o:["10","20","30"]},{k:"level",q:"Şu anki seviyen?",o:["Başlangıç","Yaklaşık 40","Yaklaşık 50","60+"]}];
function vOnboard(){
  if(OB.step>=OB_Q.length)return`<div class="stack"><div><div class="eyebrow">Hazır</div><h1 class="sumhead">İlk çalışman hazır</h1></div>
    <section class="panel"><p>Günde ${esc(OB.minutes)} dakika · ilk oturumda ${S.firstNew} yeni kelime. Bu ayarlar yalnızca başlangıç yükünü belirler; sistem sonra senin hatırlama verine göre uyum sağlar.</p></section>
    <button class="btn btn-primary" data-act="start">İLK ÇALIŞMAYA BAŞLA</button><button class="link" data-act="place">Önce seviyemi ölç (18 soru, isteğe bağlı)</button></div>`;
  const Q=OB_Q[OB.step];
  return`<div class="stack"><div><div class="eyebrow">YDS Kelime Atölyesi · ${OB.step+1}/3</div><h1 class="sumhead">${esc(Q.q)}</h1></div>
  <div class="opts" role="group" aria-label="${esc(Q.q)}">${Q.o.map(o=>`<button class="opt" data-act="ob" data-v="${esc(o)}"><span>${esc(o)}${Q.k==="minutes"?" dakika":""}</span></button>`).join("")}</div>
  <button class="link" data-act="ob" data-v="__skip">Atla, varsayılan ayarlarla başla</button></div>`;
}
function obStep(v){
  if(v==="__skip"){S.profile={skipped:true,d:today()};save();render();return}
  const Q=OB_Q[OB.step];OB[Q.k]=v;OB.step++;
  if(OB.step>=OB_Q.length){
    S.profile={target:OB.target,minutes:+OB.minutes,level:OB.level,d:today()};
    S.settings.length={10:"quick",20:"normal",30:"deep"}[OB.minutes]||"normal";
    S.firstNew={"Başlangıç":8,"Yaklaşık 40":10,"Yaklaşık 50":12,"60+":15}[OB.level]||12;
    S.readLevel=OB.level==="60+"?2:OB.level==="Başlangıç"?0:1;REV++;save();
  }
  render();
}
function vStudy(){
  const m=(act,v,title,desc,dis)=>`<button class="sc wide" data-act="${act}"${v!=null?` data-v="${esc(v)}"`:""}${dis?" disabled":""}><b>${title}</b><span>${desc}</span></button>`;
  const dueN=dueList().length,weakN=weakList().length;
  const p=pickPassage(),c=pickCloze();
  const linkN=W.filter(w=>isLink(w)&&w.cn).length;
  return`<div class="stack">
  <div><div class="eyebrow">Çalışma modları</div><h1 class="sumhead" style="font-size:27px">Çalış</h1></div>
  <section class="panel"><h2>Hafıza</h2><div class="modes">
    ${m("start",null,"Günlük akıllı oturum","Tekrar, zayıf, yeni, eş anlam, bağlam ve karıştırılan kelimeler dengeli dağıtılır.",S.doneDay===today())}
    ${m("quick",null,"Hızlı tekrar",dueN?`${Math.min(dueN,30)} kelime`:"Bekleyen tekrar yok",!dueN)}
    ${m("weak",null,"Zayıf kelimeler",weakN?`${Math.min(weakN,8)} kelime`:"Şu an zayıf kelime yok",!weakN)}
    ${m("favstudy",null,"Favoriler",S.fav.length?`${Math.min(S.fav.length,20)} kelime`:"Henüz favori yok",!S.fav.length)}
  </div></section>
  <section class="panel"><h2>İlişkilendir</h2><div class="modes">
    ${m("clusters",null,"Eş anlam kümeleri ve merdiven","Yakın anlamlılar ve kullanım farkları; temelden yüksek puana.")}
    ${m("connopen",null,"Bağlaç ustası",`${linkN} bağlaç: anlam, yapı, konum, noktalama.`)}
    ${m("trap",null,"Kelime tuzağı","rise/raise, affect/effect, adapt/adopt… mikro testler.")}
    ${m("pairsopen",null,"Karıştırılan kelimeler",`${PAIRS.length} çift, yan yana açıklama.`)}
  </div></section>
  <section class="panel"><h2>Kullan</h2><div class="modes">
    ${m("read",null,"Okuma köprüsü",p?`“${esc(p.title)}” · 3 soru`:"Pasaj yok",!p)}
    ${m("clz",null,"Cloze köprüsü",c?`“${esc(c.title)}” · ${c.blanks.length} boşluk`:"Pasaj yok",!c)}
    ${m("ydsopen",null,"Mini YDS","Vocabulary, cloze, sentence completion, translation, restatement, paragraph completion, reading.")}
    ${m("weekly",null,"Haftalık rapor","Bu haftanın özeti ve gelecek haftanın odağı.")}
    ${m("place",null,"Seviyemi ölç","18 soruluk kısa kelime yerleştirme testi (YDS puanı değildir).")}
  </div></section></div>`;
}

function vSession(){
  const ph=SS.phases[SS.pi],it=cur();
  const bars=SS.phases.map((p,i)=>{const w=i<SS.pi?100:i>SS.pi?0:Math.round(SS.ii/Math.max(1,p.items.length)*100);return`<i><b style="width:${w}%"></b></i>`}).join("");
  return`<h1 class="sr">Çalışma oturumu</h1><div class="shead"><button class="iconbtn" data-act="exit" aria-label="Oturumdan çık">×</button><div class="phasebar" aria-hidden="true">${bars}</div><span class="qcount">${SS.q?`${SS.c}/${SS.q}`:""}</span></div>
  <div class="plabel"><span class="eyebrow">${SS.pi+1}/${SS.phases.length} · ${esc(ph.label)}</span><span class="qcount">${SS.ii+1} / ${ph.items.length}</span></div>`+vItem(it);
}
function feedbackFor(it,o){
  const w=it.id?BY[it.id]:null;
  if(it.k==="yds"||it.k==="rdq"){
    const picked=it.opts[SS.ans];
    return`${!picked.ok&&picked.ow?`<span><b>Neden yanlış:</b> ${esc(picked.ow)}</span>`:""}<span><b>Neden doğru:</b> ${esc(it.why||"")}</span>${it.key&&it.key.length?`<span class="muted small">Anahtar kelimeler: ${it.key.map(esc).join(" · ")}</span>`:""}${it.gram?`<span class="muted small">Dil bilgisi / bağlaç: ${esc(it.gram)}</span>`:""}`;
  }
  if(it.k==="trap")return`<span>${esc(it.t.e)}</span>`;
  if(it.k==="clz")return`<span>${esc(it.cz.blanks[it.bi].why)}</span>`;
  if(it.k==="syn"){const okT=it.opts.find(x=>x.ok).t,rl=BY[okT]?relOf(w.id,okT):null;const notes=synNotes(w,okT)+(rl?`<span class="small"><b>${esc(w.w)} ↔ ${esc(okT)}</b> · ${REL_TR[rl[0]]}: ${esc(rl[1])}</span>`:"");
    return`<span class="link-eq">${esc([w.w,...w.syn.slice(0,2)].join(" ≈ "))}</span>${notes}<span class="muted small">Yakın anlamlı, ancak tamamen interchangeable değiller; kalıplara dikkat et.</span>`}
  if(it.k==="cpunct")return`<span>${esc(w.cn.punct)}</span><span class="muted small">${esc(w.cn.position)}</span>`;
  if(it.k==="place")return`<span><b>${esc(w.w)}</b> → ${esc(w.tr)}</span>`;
  if(it.k==="cloze"||it.k==="yctx")return`<span>${esc(w.note)}</span>${w.pat.length?`<span class="muted small">Kalıp: ${w.pat.map(esc).join(" · ")}</span>`:""}`;
  if(it.k==="guess")return`<span><b>${esc(w.w)}</b> → ${esc(w.tr)}.</span><span>${esc(w.hint)}</span>`;
  if(it.k==="coll")return`<span>Doğal kalıplar: ${w.col.map(esc).join(", ")}.</span>${w.pat.length?`<span class="muted small">${w.pat.map(esc).join(" · ")}</span>`:""}`;
  if(it.k==="fam")return`<span>${w.fam.map(f=>`<b>${esc(f[0])}</b> <small class="muted">${esc(f[1])}</small>`).join(" · ")} · <b>${esc(w.w)}</b> <small class="muted">${esc(w.pos)}</small></span>`;
  if(it.k==="pairq")return`<span>${esc(it.p.tip)}</span>`;
  if(it.k==="cstruct"||it.k==="cfunc"||it.k==="cid")return`<span><b>${esc(w.w)}</b>: ${esc(CONN_FN[w.g])}, ${esc(STRUCT_SHORT[w.cn.struct])}. ${esc(w.cn.punct)}</span><span class="muted small">${esc(w.cn.diff)}</span>`;
  return`<span><b>${esc(w.w)}</b> → ${esc(w.tr)} · ${esc(w.col[0])}</span>`;
}
const BTYPE_TR={vocab:"kelime",connector:"bağlaç",preposition:"edat",grammar:"dil bilgisi",collocation:"kalıp"};
/* Kullanım notu: önce anlam merdivenindeki not, yoksa kelimenin nüans notu */
function useNote(id){for(const L of LADBY[id]||[])for(const st of L.steps)if(st.w.includes(id))return st.note;const w=BY[id];return w&&w.nu||""}
function synNotes(w,other){const a=useNote(w.id),b=BY[other]?useNote(other):"";
  if(!a&&!b)return"";return`<span class="small">${a?`<b>${esc(w.w)}</b> → ${esc(a)}`:""}${a&&b?"<br>":""}${b?`<b>${esc(other)}</b> → ${esc(b)}`:""}</span>`}
function recallMode(it){return it.open?"open":"buttons"}
function openRow(it){
  const b=(v,k,lab)=>`<button class="rate ${k}" data-act="orate" data-v="${v}"><b>${lab}</b><small>${rateLabel(it.id,k)}</small></button>`;
  return`<div class="raterow three">${b("dunno","again","Hatırlayamadım")}${b("unsure","hard","Kısmen")}${b("know","good","Doğru hatırladım")}</div>
  <p class="ratehelp">Zihninde söylediğin anlam kartla örtüşüyor mu? Seçimin sonraki tekrar zamanını belirler ve sonraki eş anlam / bağlam sorusuyla doğrulanır. <button class="link" data-act="orate" data-v="easy">Çok kolaydı (Easy · ${rateLabel(it.id,"easy")})</button></p>`;
}
function rateRow(it){
  if(it.open)return openRow(it);
  const sug={know:"good",unsure:"hard",dunno:"again"}[SS.self];
  const open=SS.self==null;
  const lab={again:open?"Hatırlayamadım":"Again",hard:open?"Kısmen":"Hard",good:open?"Doğru":"Good",easy:open?"Hemen":"Easy"};
  const r=k=>`<button class="rate ${k}${sug===k?" sug":""}" data-act="rate" data-v="${k}"><b>${lab[k]}</b><small>${open?{again:"Again",hard:"Hard",good:"Good",easy:"Easy"}[k]+" · ":""}${rateLabel(it.id,k)}</small></button>`;
  return`<div class="raterow">${r("again")}${r("hard")}${r("good")}${r("easy")}</div>
  <p class="ratehelp">${open?"Zihninde söylediğin cevap kartla ne kadar örtüşüyor?":"Ne kadar kolay hatırladın? Çerçeveli olan senin cevabına göre önerilen."} Seçimin bir sonraki tekrarın zamanını belirler. Klavye: 1–4.</p>`;
}
function vItem(it){
  if(it.k==="pair")return vPairCard(it.p,true);
  if(it.k==="ladder")return`${it.L?vSemLadder(it.L):vLadder(it.g,it.ids)}<div style="margin-top:14px"><button class="btn btn-primary" data-act="next">Başla</button></div>`;
  if(it.k==="leech"){const w=BY[it.id],c=S.cards[it.id];const L=(LADBY[it.id]||[])[0];
    const rel=W.filter(x=>x.g===w.g&&x.id!==w.id).sort((a,b)=>b.p-a.p).slice(0,3);
    const cws=[...new Set([...w.cw.filter(x=>BY[x]),...personalPairs().filter(p=>p.ws.includes(w.id)).map(p=>p.ws.find(x=>x!==w.id))])];
    const ctx2=cap((blankSents(w,"cloze").find(([k])=>k!=="cz")||blankSents(w,"cloze")[0])[1].replace("___",w.w));
    return`<div class="card leech"><div class="eyebrow">Farklı yöntem · bu kelime ${c.reps+c.correct+c.wrong} kez görüldü ama henüz oturmadı</div>
    <div class="word">${esc(w.w)}</div><div class="meaning">${esc(w.tr)}</div>
    <div class="sec"><h4>Mini hafıza ipucu</h4><p>${esc(mnemonic(w))}</p></div>
    <div class="sec"><h4>Anlam ailesi</h4><p class="small">${esc(GROUPS[w.g][0])}${L?` · ${esc(L.title)}: ${esc(useNote(w.id))}`:""}</p><div class="chips">${rel.map(x=>`<span class="chip">${esc(x.w)} <small class="muted">${esc(x.tr.split(" / ")[0])}</small></span>`).join("")}</div></div>
    ${w.fam.length?`<div class="sec"><h4>Kelime ailesi</h4><div class="chips">${w.fam.map(f=>`<span class="chip">${esc(f[0])} <small class="muted">${esc(f[1])}</small></span>`).join("")}</div></div>`:""}
    <div class="sec"><h4>Kalıplar</h4><ul class="colls">${w.col.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>
    ${cws.length?`<div class="cw">⚠ Karıştırma: ${cws.map(x=>`<b>${esc(x)}</b> (${esc(BY[x].tr.split(" / ")[0])})`).join(", ")}</div>`:""}
    <div class="sec"><h4>İki farklı bağlam</h4><p class="ex">${exHtml(w)}</p><p class="ex">${esc(ctx2)}</p></div></div>
    <div style="margin-top:14px"><button class="btn btn-primary" data-act="next">Kısa teste geç</button></div>`}
  if(it.k==="passage")return`<div class="card"><div class="eyebrow">Okuma köprüsü · ${esc(it.p.title)}</div><p class="ptext">${passageHtml(it.p)}</p><p class="note">Altı çizili kelimeleri son günlerde çalıştın. Önce metni oku; ardından 3 soru gelecek.</p></div><div style="margin-top:14px"><button class="btn btn-primary" data-act="next">Sorulara geç</button></div>`;
  const w=it.id?BY[it.id]:null;
  if(it.k==="flash"||it.k==="learn"||it.k==="connfo"){
    const tags=(it.k!=="flash"&&!it.again&&!S.cards[it.id]?`<span class="tag">yeni</span>`:"")+(isWeak(it.id)?`<span class="tag weak">zayıf</span>`:"")+(it.early?`<span class="tag">erken tekrar</span>`:"");
    if(SS.stage==="front"){
      if(recallMode(it)==="open")return`<div class="card">${head(w,tags)}<p class="prompt"><b>Cevabı görmeden önce anlamını zihninden söyle.</b> Sonra kendini kontrol et.</p></div>
        <div style="margin-top:14px"><button class="btn btn-primary" data-act="reveal">Cevabı göster</button></div>`;
      return`<div class="card">${head(w,tags)}<p class="prompt">Bu kelimenin anlamını hatırlıyor musun? Önce düşün, sonra seç.</p></div>
      <div class="selfrow"><button class="self" data-act="self" data-v="know">Biliyorum</button><button class="self" data-act="self" data-v="unsure">Emin değilim</button><button class="self" data-act="self" data-v="dunno">Bilmiyorum</button></div>`;
    }
    return`<div class="card">${head(w,tags)}${cardBody(w,SS.fam||it.k==="connfo")}</div>${rateRow(it)}`;
  }
  if(it.k==="reverse"){
    if(SS.stage==="front")return`<div class="card"><div class="eyebrow">Ters hatırlama · Türkçe → İngilizce</div><div class="meaning" style="font-size:26px">${esc(w.tr)}</div><p class="prompt">İngilizcesini zihninden söyle ve cevabı aç. (${esc(POS_TR[w.pos.split("/")[0]]||w.pos)}, ${w.w.length} harf)</p></div>
      <div style="margin-top:14px"><button class="btn btn-primary" data-act="reveal">Cevabı aç</button></div>`;
    return`<div class="card"><div class="eyebrow">Ters hatırlama</div><div class="word">${esc(w.w)}</div><div class="meaning">${esc(w.tr)}</div><p class="ex">${exHtml(w)}</p></div>
      <div class="btn-row" style="margin-top:14px"><button class="btn btn-ghost" data-act="rev" data-v="0">Hatırlayamadım</button><button class="btn btn-primary" data-act="rev" data-v="1">Hatırladım</button></div>
      <p class="ratehelp">Ters hatırlama tekrar programını değiştirmez; yalnızca anlam becerine işlenir.</p>`;
  }
  const answered=SS.ans!==null;let q;
  const fillBlank=(s,word)=>{const parts=s.split("___");return`${esc(parts[0])}<span class="blank${answered?" fill":""}">${answered?esc(word):"&nbsp;"}</span>${esc(parts[1]||"")}`};
  if(it.k==="yds"||it.k==="rdq")q=`<span class="qtype">${YT[it.yt]}</span>${it.stem}`;
  else if(it.k==="trap")q=`<p class="eyebrow">Kelime tuzağı · ${esc(it.t.pair)}</p><p class="sent">${fillBlank(it.t.s,it.t.o[it.t.a])}</p>`;
  else if(it.k==="clz")q=`<p class="eyebrow">Cloze köprüsü · ${esc(it.cz.title)} · boşluk ${it.bi+1}/${it.cz.blanks.length} · ${esc(BTYPE_TR[it.cz.blanks[it.bi].type]||"")}</p><p class="ptext">${clozeHtml(it)}</p>`;
  else if(it.k==="syn")q=`<p class="qtext">Which word is closest in meaning to <q>${esc(w.w)}</q>?</p>`;
  else if(it.k==="mean"){it.stemI=it.stemI??Math.floor(Math.random()*MEAN_STEMS.length);q=`<p class="qtext">${MEAN_STEMS[it.stemI](esc(w.tr))}</p>`}
  else if(it.k==="guess")q=`<p class="eyebrow">Bağlam · Kolay · tahmin</p><p class="sent">${exHtml(w)}</p><p class="qtext">What does <q>${esc(w.w)}</q> most likely mean?</p>`;
  else if(it.k==="coll")q=`<p class="eyebrow">Kalıp · ${esc(w.w)}</p><p class="qtext">Which combination is most natural?</p>`;
  else if(it.k==="cstruct")q=`<p class="eyebrow">Bağlaç ustası · yapı</p><p class="qtext"><q>${esc(w.w)}</q> bağlacından sonra hangi yapı gelir?</p>`;
  else if(it.k==="cfunc")q=`<p class="eyebrow">Bağlaç ustası · işlev</p><p class="qtext"><q>${esc(w.w)}</q> hangi anlam ilişkisini kurar?</p>`;
  else if(it.k==="cid")q=`<p class="eyebrow">Bağlaç ustası · seçim</p><p class="qtext">Anlamı <b>${esc(CONN_FN[w.g])}</b> olan ve ardından <b>${esc(STRUCT[w.cn.struct])}</b> gelen bağlaç hangisidir?</p>`;
  else if(it.k==="yctx")q=`<p class="eyebrow">Bağlam · YDS düzeyi</p><p class="sent long">${fillBlank(it.sent||w.x2,w.w)}</p>`;
  else if(it.k==="cpunct")q=`<p class="eyebrow">Bağlaç ustası · konum ve noktalama</p><p class="qtext"><q>${esc(w.w)}</q> ile kurulmuş, konum ve noktalama açısından doğru cümle hangisidir?</p>`;
  else if(it.k==="place")q=`<p class="eyebrow">Seviyemi ölç · ${SS.ii+1}/${SS.phases[SS.pi].items.length}</p><p class="qtext"><q>${esc(w.w)}</q> kelimesinin anlamı hangisidir?</p>`;
  else{const lab=it.k==="fam"?`Kelime ailesi · doğru biçimi seç`:it.k==="pairq"?`Karıştırılan kelimeler · ${esc(it.p.ws.join(" / "))}`:"Bağlam · Orta · boşluğa en uygun kelime";
    q=`<p class="eyebrow">${lab}</p><p class="sent">${fillBlank(it.k==="cloze"&&it.sent?it.sent:w.cz,w.w)}</p>`}
  const long=(it.k==="yds"||it.k==="rdq")&&["sc","tr","rs","pc","rd"].includes(it.yt)||it.k==="cstruct"||it.k==="cpunct";
  const opts=it.opts.map((o,i)=>{let c="",mk="";if(answered){if(o.ok){c=" ok";mk=`<span class="mk">✓ doğru</span>`}else if(i===SS.ans){c=" bad";mk=`<span class="mk">✗ seçimin</span>`}else c=" dim"}
    return`<button class="opt${long?" long":""}${c}" data-act="ans" data-v="${i}"${answered?" disabled":""}><span class="k">${"ABCDE"[i]})</span><span class="ot">${esc(o.t)}</span>${mk}</button>`}).join("");
  let fb="";
  if(answered){
    const o=it.opts[SS.ans],ok=o.ok;let conf="";
    if(!ok&&o.wid&&BY[o.wid]&&w&&o.wid!==w.id){const pw=BY[o.wid];const pr=PAIRMAP[pairKey(w.id,pw.id)]||w.cw.includes(pw.id);conf=`<span class="muted">${esc(pw.w)} = ${esc(pw.tr)}${pr?" · Bu iki kelime sık karıştırılır; karşılaştırma kartını günün zor kelimelerinde göreceksin.":""}</span>`}
    fb=`<div class="fb" role="status"><span class="v ${ok?"ok":"bad"}">${ok?"✓ Doğru.":"✗ Doğru cevap: "+esc(it.opts.find(x=>x.ok).t)}</span>${feedbackFor(it,o)}${conf}</div><button class="btn btn-primary" data-act="next" id="nextbtn">Devam</button>
    <button class="link flaglink" data-act="flagopen">${SS.flagged?"✓ Bildirim kaydedildi":"Bu soruda sorun var"}</button>`;
  }
  return`<div class="card">${q}</div><div class="stack" style="margin-top:14px"><div class="opts" role="group" aria-label="Seçenekler">${opts}</div>${fb}</div>`;
}
function passageHtml(p){
  let h=esc(p.text);
  for(const id of p.words){const w=BY[id];if(!w||!S.cards[id])continue;const re=new RegExp("\\b("+w.w.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+"\\w*)","i");h=h.replace(re,"<u>$1</u>")}
  return h;
}
function clozeHtml(it){
  const c=it.cz;
  return esc(c.text).replace(/\{(\d)\}/g,(m,n)=>{const i=+n-1;
    if(i===it.bi)return`<span class="blank cur${SS.ans!==null?" fill":""}">(${n}) ${SS.ans!==null?esc(c.blanks[i].o[c.blanks[i].a]):"&nbsp;"}</span>`;
    if(i<it.bi)return`<span class="blank fill">${esc(c.blanks[i].o[c.blanks[i].a])}</span>`;
    return`<span class="blank">(${n})</span>`});
}
function vPairCard(p,inSession){
  const col=id=>{const w=BY[id];return`<div class="pcol"><div class="wtype">${esc(posLabel(w.pos))}</div><div class="word">${esc(w.w)}</div><div class="meaning">${esc(w.tr)}</div><p class="ex">${exHtml(w)}</p><p class="extr">${esc(w.col.slice(0,2).join(" · "))}</p></div>`};
  return`<div class="card"><div class="eyebrow">Karşılaştırma kartı</div><div class="pair">${p.ws.map(col).join("")}</div><div class="fb">${esc(p.tip)}</div></div>
  ${inSession?`<div style="margin-top:14px"><button class="btn btn-primary" data-act="next">Anladım</button></div>`:""}`;
}
/* Anlam merdiveni (elle tanımlı): temel anlam → akademik kullanım → daha güçlü / daha özel kullanım */
function vSemLadder(L){
  const sm=statusMap(),cm=clusterMastery(ladderWords(L));
  const steps=L.steps.map((st,i)=>`<li><span class="lv">${i+1}. basamak</span><div class="lw">${st.w.map(id=>`<button class="chipbtn" data-act="detail" data-v="${esc(id)}"><b>${esc(id)}</b> <small class="muted">${esc(BY[id].tr.split(" / ")[0])}</small>${sm[id]==="mastered"?" ✓":""}</button>`).join(`<span class="muted">/</span>`)}<span class="nu">→ ${esc(st.note)}</span></div></li>`).join("");
  return`<div class="card"><div class="eyebrow">${esc(L.title)} · anlam merdiveni · küme ustalığı ${cm.score}/100</div>
  <p class="small muted">Temel anlamdan akademik kullanıma ve daha güçlü / daha özel kullanıma doğru. Yakın anlamlı, ancak tamamen interchangeable değiller: her basamağın notu farkı söyler.</p><ol class="ladder">${steps}</ol></div>`;
}
/* Küme görünümü: seviye sırası + kümeye bağlı elle tanımlı merdivenler */
function vLadder(g,ids){
  const ws=(ids?ids.map(id=>BY[id]):W.filter(w=>w.g===g)).slice().sort((a,b)=>a.l-b.l||b.p-a.p);
  const sm=statusMap();
  const steps=[1,2,3,4,5].map(l=>{const xs=ws.filter(w=>w.l===l);if(!xs.length)return"";
    return`<li><span class="lv">L${l} · ${esc(LEVELS[l])}</span><div class="lw">${xs.map(w=>`<button class="chipbtn" data-act="detail" data-v="${esc(w.id)}"><b>${esc(w.w)}</b> <small class="muted">${esc(w.tr.split(" / ")[0])}</small>${sm[w.id]==="mastered"?" ✓":""}</button>${useNote(w.id)?`<span class="nu">${esc(useNote(w.id))}</span>`:""}`).join("")}</div></li>`}).join("");
  const gm=groupMastery(g);
  const lads=LADDERS.filter(L=>ladderWords(L).some(id=>BY[id]&&BY[id].g===g));
  return`<div class="card"><div class="eyebrow">${esc(GROUPS[g][0])} · seviyeye göre · küme ustalığı ${gm.score}/100</div>
  <p class="small muted">Yakın anlamlı, ancak tamamen interchangeable değiller. Notlar her kelimenin kullanım farkını söyler.</p><ol class="ladder">${steps}</ol>
  ${lads.length?`<div class="chips">${lads.map(L=>`<button class="chipbtn" data-act="ladderopen" data-v="${esc(L.id)}">Anlam merdiveni: ${esc(L.title)}</button>`).join("")}</div>`:""}</div>`;
}

function vSummary(){
  const s=summary;if(!s){tab="home";return vHome()}
  const acc=s.q?pct(s.c/s.q):null;
  if(s.type==="yds"){
    const mm=Math.floor(s.secs/60),ss=String(s.secs%60).padStart(2,"0");
    const types=Object.entries(s.bt).map(([k,x])=>`<div class="brow"><span>${YT[k]} <span class="muted small">(${x.c}/${x.c+x.w})</span></span><span class="num">%${pct(x.c/(x.c+x.w))}</span><div class="bar g"><i style="width:${pct(x.c/(x.c+x.w))}%"></i></div></div>`).join("");
    const wrong=s.log.filter(l=>!l.ok),right=s.log.filter(l=>l.ok);
    const entry=l=>`<article class="lrn"><div class="qtype">${YT[l.yt]}</div><p class="small">${esc(l.q)}</p>
      ${!l.ok?`<p class="small"><span class="badtxt">✗ Senin cevabın:</span> ${esc(l.o[l.picked])}${l.ow[l.picked]?` · <span class="muted">${esc(l.ow[l.picked])}</span>`:""}</p>`:""}
      <p class="small"><span class="oktxt">✓ Doğru:</span> ${esc(l.o[l.a])} · ${esc(l.why||"")}</p>
      ${l.key&&l.key.length?`<p class="small muted">Anahtar kelimeler: ${l.key.map(esc).join(" · ")}</p>`:""}${l.gram?`<p class="small muted">Dil bilgisi / bağlaç: ${esc(l.gram)}</p>`:""}</article>`;
    return`<div class="stack"><div><div class="eyebrow">Mini YDS sonucu</div><h1 class="sumhead">${s.c} / ${s.n} doğru</h1></div>
    <section class="panel"><div class="sumgrid"><span>Puan</span><b>${pct(s.c/s.n)} / 100</b><span>Süre</span><b>${mm}:${ss}</b><span>Soru başına</span><b>${Math.round(s.secs/s.n)} sn</b></div><p class="note">Puan yalnızca bu mini testteki doğru oranıdır; YDS sınav puanı tahmini değildir.</p></section>
    <section class="panel"><h2>Soru tipine göre</h2><div class="bars">${types}</div></section>
    <section class="panel"><h2>Öğrenme modu <small>· neden yanlış, neden doğru</small></h2>${wrong.length?wrong.map(entry).join(""):`<p class="small muted">Yanlış yok.</p>`}
      ${right.length?`<details><summary class="small">Doğru yaptığın ${right.length} sorunun açıklamaları</summary>${right.map(entry).join("")}</details>`:""}</section>
    ${s.weak.length?`<section class="panel"><h2>Bu testte zorlandığın kelimeler</h2><div class="chips">${s.weak.map(id=>`<button class="chipbtn" data-act="detail" data-v="${esc(id)}">${esc(id)}</button>`).join("")}</div></section>`:""}
    <div class="btn-row"><button class="btn btn-ghost" data-act="ydsopen">Yeni test</button><button class="btn btn-primary" data-act="tab" data-v="home">Ana ekran</button></div></div>`;
  }
  if(s.type==="place"){const P=s.placement,TR={Strong:"Güçlü",Developing:"Gelişiyor",Limited:"Sınırlı"};
    const row=(lab,k)=>`<span>${lab}</span><b>${P[k]} · ${TR[P[k]]||""} <span class="muted small">(${P.raw[k].c}/${P.raw[k].n})</span></b>`;
    return`<div class="stack"><div><div class="eyebrow">Seviyemi ölç</div><h1 class="sumhead">Başlangıç kelime seviyen</h1></div>
    <section class="panel"><div class="sumgrid">${row("Core Vocabulary · temel","core")}${row("Intermediate · orta","inter")}${row("Advanced · ileri","adv")}</div>
    <p class="note">Bu yalnızca kelime tanıma düzeyinin kaba bir tahminidir; YDS puanı değildir. Doğru bildiğin kelimeler yeni kelime sırasında biraz geriye alındı, böylece önce bilmediklerin gelir.</p></section>
    <div class="btn-row"><button class="btn btn-ghost" data-act="tab" data-v="study">Diğer modlar</button><button class="btn btn-primary" data-act="start">Çalışmaya başla</button></div></div>`}
  if(["read","clz","trap","conn"].includes(s.type)){
    const title={read:"Okuma köprüsü tamam",clz:"Cloze köprüsü tamam",trap:"Kelime tuzağı tamam",conn:"Bağlaç çalışması tamam"}[s.type];
    return`<div class="stack"><div><div class="eyebrow">Özet</div><h1 class="sumhead">${title}</h1></div>
    <section class="panel"><div class="sumgrid"><span>Doğru cevap</span><b>${s.c} / ${s.q}</b>${s.rl!=null?`<span>Okuma seviyesi</span><b>${READ_LABEL[READ_LEVELS[s.rl]]}</b>`:""}</div>${acc!==null&&s.q?`<div class="acc"><span class="n">%${acc}</span><span class="muted">doğruluk</span></div>`:""}
    ${s.rch?`<p class="small">Son okuma sorularındaki başarına göre okuma seviyesi <b>${READ_LABEL[READ_LEVELS[s.rl]]}</b> düzeyine ${s.rch==="up"?"yükseldi":"indi"}.</p>`:""}</section>
    ${s.hard.length?`<section class="panel"><h2>Zorlandığın kelimeler</h2><div class="chips">${s.hard.filter(id=>BY[id]).map(id=>`<button class="chipbtn" data-act="detail" data-v="${esc(id)}">${esc(id)}</button>`).join("")}</div></section>`:""}
    <div class="btn-row"><button class="btn btn-ghost" data-act="tab" data-v="study">Diğer modlar</button><button class="btn btn-primary" data-act="tab" data-v="home">Ana ekran</button></div></div>`;
  }
  const area=a=>a?`${SKILLS[a.k]} <span class="muted small">%${pct(a.a)}</span>`:"Henüz yeterli veri yok";
  const cl=Object.entries(s.clusters||{}).map(([g,ids])=>`<div class="lcl"><span class="eyebrow">${esc(GROUPS[g][0])}</span><div class="chips">${ids.map(id=>`<button class="chipbtn" data-act="detail" data-v="${esc(id)}">${esc(id)} <small class="muted">${esc(BY[id].tr.split(" / ")[0])}</small></button>`).join("")}</div></div>`).join("");
  return`<div class="stack">
  <div><div class="eyebrow">Today's Summary · Bugünün özeti</div><h1 class="sumhead">${s.type==="pair"?"Karşılaştırma tamam":s.type==="weak"?"Zayıf kelime çalışması":s.type==="quick"?"Hızlı tekrar tamam":s.type==="cluster"?"Küme çalışması tamam":"Bugün"}</h1></div>
  <section class="panel">
    <div class="sumgrid">
      <span>Yeni kelime</span><b>${s.n}</b>
      <span>Tekrar edilen</span><b>${s.r}</b>
      <span>Doğru cevap</span><b>${s.c} / ${s.q}</b>
      <span>Bugün kalıcı olan</span><b>${s.mastered}</b>
      <span>Zayıf kelime (şu an)</span><b>${s.weakNow}</b>
      ${s.rev&&s.rev.n?`<span>Ters hatırlama</span><b>${s.rev.ok} / ${s.rev.n}</b>`:""}
      ${s.deferred?`<span>Sonraki günlere yayılan</span><b>${s.deferred}</b>`:""}
    </div>
    ${acc!==null&&s.q?`<div class="acc"><span class="n">%${acc}</span><span class="muted">doğruluk</span></div><div class="bar g"><i style="width:${acc}%"></i></div>`:""}
  </section>
  ${s.keep3&&s.keep3.length?`<section class="panel"><h2>Bugünden aklında kalması gereken ${s.keep3.length} kelime</h2><ul class="keep3">${s.keep3.map(x=>`<li><button class="link" data-act="detail" data-v="${esc(x.id)}"><b>${esc(x.id)}</b></button> → ${esc(x.tr)}${x.col?` <span class="muted small">· ${esc(x.col)}</span>`:""}</li>`).join("")}</ul></section>`:""}
  ${cl?`<section class="panel"><h2>Bugün ne öğrendim? <small>· kümelere göre</small></h2>${cl}</section>`:""}
  <section class="areas"><div class="area"><span>En güçlü alan</span><b>${area(s.best)}</b></div><div class="area"><span>Geliştirilmeli</span><b>${area(s.worst)}</b></div></section>
  <section class="panel"><p>Yarın <b class="num">${s.tomorrow}</b> kelime tekrar için hazır olacak.${s.ctx1!==s.ctx0?` Bağlam soruları <b>${CTX_LEVELS[s.ctx1]}</b> seviyesine ${s.ctx1>s.ctx0?"yükseldi":"indi"}.`:""}</p></section>
  ${s.hard.length?`<section class="panel"><h2>Zorlandığın kelimeler</h2><div class="chips">${s.hard.map(id=>`<button class="chipbtn" data-act="detail" data-v="${esc(id)}">${esc(id)}</button>`).join("")}</div><p class="note">Bu kelimeler yarın tekrar programına alındı.</p></section>`:""}
  <div class="btn-row"><button class="btn btn-ghost" data-act="read">Okuma köprüsü</button><button class="btn btn-primary" data-act="tab" data-v="home">Ana ekrana dön</button></div></div>`;
}

const WFILT={all:()=>true,fav:id=>isFav(id),learned:id=>!!S.cards[id],weak:id=>statusMap()[id]==="weak",mastered:id=>statusMap()[id]==="mastered",new:id=>!S.cards[id]};
function vWords(){
  const q=wq.trim().toLocaleLowerCase("tr-TR");
  const filt=WFILT[wf]||WFILT.all;
  const counts={all:W.length,fav:S.fav.filter(id=>BY[id]).length,learned:Object.keys(S.cards).filter(id=>BY[id]).length,weak:weakList().length};
  const fb=(k,l)=>`<button class="chipbtn" data-act="wf" data-v="${k}" aria-pressed="${wf===k}">${l}${counts[k]!=null?`<span class="num">${counts[k]}</span>`:""}</button>`;
  return`<div class="stack">
  <div><div class="eyebrow">${W.length} kelime (${CORE_N} çekirdek + ${SUPPORT_N} destek) · ${Object.keys(GROUPS).length} anlamsal küme · ${LADDERS.length} anlam merdiveni · 5 seviye</div><h1 class="sumhead" style="font-size:27px">Kelime gezgini</h1></div>
  <input class="search" id="wsearch" type="search" placeholder="Kelime ya da Türkçe anlam ara (ör. decline, azalmak)" value="${esc(wq)}" autocomplete="off" aria-label="Kelime ara">
  <div class="filters" role="group" aria-label="Filtre">${fb("all","Tümü")}${fb("fav","Favoriler")}${fb("learned","Öğrenilen")}${fb("weak","Zayıf")}${fb("mastered","Kalıcı")}${fb("new","Yeni")}</div>
  ${wf==="fav"&&counts.fav?`<button class="btn btn-ghost" data-act="favstudy">Favorileri çalış (${Math.min(counts.fav,20)} kelime)</button>`:""}
  <div id="wresults">${vWordResults(q,filt)}</div>
  </div>`;
}
function vWordResults(q,filt){
  const norm=s=>(s||"").toLocaleLowerCase("tr-TR");
  const match=w=>!q||norm(w.w).includes(q)||norm(w.tr).includes(q)||norm(w.tr2).includes(q)||w.syn.some(s=>norm(s)===q);
  const t=today(),sm=statusMap();
  const row=w=>{const st=sm[w.id],c=S.cards[w.id];return`<button class="wrow" data-act="detail" data-v="${esc(w.id)}"><span class="w">${esc(w.w)}<span class="lvl">L${w.l}</span>${isFav(w.id)?`<span class="favmark" aria-label="favori">★</span>`:""}</span><span class="st"><span class="pill ${st}">${STATUS[st]}</span>${c&&c.due<=t?`<span class="duemark">tekrar zamanı</span>`:""}</span><span class="t">${esc(w.tr)}</span></button>`};
  if(q){
    const res=W.filter(w=>match(w)&&filt(w.id)).sort((a,b)=>(norm(b.w).startsWith(q)-norm(a.w).startsWith(q))||(b.p-a.p));
    return res.length?`<div class="gblock"><div class="gtitle"><h3>ARAMA SONUÇLARI</h3><span class="qcount">${res.length}</span></div>${res.slice(0,60).map(row).join("")}</div>`:`<p class="muted" style="padding-top:12px">“${esc(wq)}” için sonuç yok.</p>`;
  }
  let shown=0,html="";
  for(const g of Object.keys(GROUPS)){
    if(shown>=wlimit)break;
    const ws=W.filter(w=>w.g===g&&filt(w.id)).sort((a,b)=>b.p-a.p);if(!ws.length)continue;
    const known=W.filter(w=>w.g===g&&S.cards[w.id]).length,all=W.filter(w=>w.g===g).length;
    const take=ws.slice(0,Math.max(0,wlimit-shown));shown+=take.length;
    html+=`<div class="gblock"><div class="gtitle"><h3>${esc(GROUPS[g][0])}</h3><span class="qcount">${known}/${all}</span></div>${take.map(row).join("")}</div>`;
  }
  const total=W.filter(w=>filt(w.id)).length;
  if(!html)return`<p class="muted" style="padding-top:12px">Bu filtrede kelime yok.</p>`;
  return html+(total>shown?`<div class="more"><button class="btn btn-ghost btn-sm" data-act="more">Daha fazla göster (${total-shown})</button></div>`:"");
}

function stats(){
  const sm=statusMap();const st={new:0,learning:0,familiar:0,weak:0,mastered:0};
  W.forEach(w=>st[sm[w.id]]++);
  const credit={mastered:1,familiar:.6,learning:.3,weak:.2,new:0};
  const cov=l=>{const ws=W.filter(w=>w.l===l);return ws.length?ws.reduce((a,w)=>a+credit[sm[w.id]],0)/ws.length:0};
  const lv={};for(let l=1;l<=5;l++)lv[l]=cov(l);
  const stage=lv[1]<.3?"Başlangıç (Foundation)":lv[1]<.7?"Temel (Core YDS)":lv[2]<.5?"Sık akademik (High Frequency)":lv[3]<.5?"Orta (Intermediate YDS)":lv[4]<.4?"İleri (Advanced YDS)":"Yüksek puan (High Score)";
  return{st,lv,stage,due:dueList().length};
}
function vWeekly(){
  const r=weeklyReport();const a=r.a;
  const d=(x,y)=>y==null||x==null?"":` <span class="muted small">(${x>=y?"+":""}${pct(x-y)} puan)</span>`;
  const wins=weeklyWins();
  return`${wins.length?`<div class="wins"><h3>Bu hafta kazandıkların</h3><ul>${wins.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>`:""}<div class="sumgrid"><span>Yeni kelime</span><b>${a.n}</b><span>Tekrar</span><b>${a.r}</b><span>Cevaplanan soru</span><b>${a.q}</b><span>Doğruluk</span><b>${r.acc==null?"–":"%"+pct(r.acc)}</b><span>Bu hafta kalıcı olan</span><b>${a.m}</b><span>Toplam kalıcı</span><b>${r.mastered}</b><span>Çalışılan gün</span><b>${a.days} / 7</b></div>
  ${r.acc!=null&&r.accPrev!=null?`<p class="small">Geçen haftaya göre doğruluk${d(r.acc,r.accPrev)}</p>`:""}
  <div class="areas"><div class="area"><span>En güçlü küme</span><b>${r.strongest?`${esc(GROUPS[r.strongest.g][1])} <span class="muted small">%${pct(r.strongest.a)}</span>`:"Veri yok"}</b></div>
  <div class="area"><span>En çok gelişen alan</span><b>${r.improved?`${SKILLS[r.improved.k]} <span class="muted small">+${pct(r.improved.d)}</span>`:"Veri yok"}</b></div>
  <div class="area"><span>Çalışılması gereken</span><b>${r.weakG?`${esc(GROUPS[r.weakG.g][1])} <span class="muted small">%${pct(r.weakG.a)}</span>`:r.needs?`${SKILLS[r.needs.k]} <span class="muted small">%${pct(r.needs.a)}</span>`:"Veri yok"}</b></div>
  <div class="area"><span>Gelecek haftanın odağı</span><b class="small">${esc(r.focus)}</b></div></div>
  ${(()=>{const wp=weeklyPlan(r);return`<div class="wplan"><h3>Bu hafta ne çalışmalısın?</h3><ol>${wp.areas.map(a=>`<li>${esc(a)}</li>`).join("")}</ol>
  ${wp.words.length?`<div class="eyebrow">Önerilen kelimeler</div><div class="chips">${wp.words.map(id=>`<button class="chipbtn" data-act="detail" data-v="${esc(id)}">${esc(id)}</button>`).join("")}</div>`:""}</div>`})()}`;
}
const SKILL_ROWS=[["Vocabulary","Vocabulary Readiness","Kelime"],["Context","Context","Bağlam"],["Reading","Reading Transfer","Okuma"],["Cloze","Cloze","Cloze"],["Connectors","Connectors","Bağlaçlar"]];
function vReady(){
  const R=readiness(),TR={Strong:"Güçlü",Developing:"Gelişiyor",Limited:"Sınırlı","Veri yetersiz":"Veri yetersiz"},by={};R.forEach(x=>by[x.k]=x);
  const cs=completionStats(),sg=suggestNewPerDay();
  return`<section class="panel"><h2>YDS becerileri</h2>
  <div class="sumgrid">${SKILL_ROWS.map(([en,k,tr])=>`<span>${tr} <span class="muted small">· ${en}</span></span><b>${TR[by[k].v]}</b>`).join("")}</div>
  <p class="note">Yalnızca uygulama içindeki performansını gösterir; YDS puanı tahmini değildir. Gerçek sınav performansı dil bilgisi, zaman yönetimi, okuma ve soru stratejisine de bağlıdır.</p>
  ${S.mocks.length?`<p class="small">Son deneme (${new Date(S.mocks[S.mocks.length-1].d*86400000).toLocaleDateString("tr-TR",{day:"numeric",month:"short",timeZone:"UTC"})}): ${S.mocks[S.mocks.length-1].total}/80 doğru</p>`:""}
  <button class="btn btn-ghost btn-sm" data-act="mockopen">Deneme sonucumu ekle</button>
  ${calDay()>=30?`<button class="btn btn-ghost btn-sm" data-act="report30">30 günlük öğrenme raporu</button>`:""}
  ${cs.tip?`<p class="tip">${esc(cs.tip)}</p>`:""}
  ${sg.ready?`<p class="tip">${esc(sg.text)}${sg.rec!==sg.cur?` <button class="link" data-act="npd" data-v="${sg.rec}">Öneriyi uygula (${sg.rec})</button>`:""}</p>`:`<p class="small muted">Kişisel yeni kelime önerisi ${sg.days}/14 çalışma günü ve ${sg.sess}/10 oturumdan sonra hazırlanır.</p>`}</section>`;
}
function pctOr(x){return x==null?"–":"%"+pct(x)}
function vMonth(){
  const m=monthStats(),dist=m.dist,tot=W.length;
  const colors={new:"var(--line)",learning:"var(--accent)",familiar:"var(--fam)",weak:"var(--warn)",mastered:"var(--good)"};
  return`<section class="panel"><h2>Son 30 gün <small>· Last 30 Days</small></h2>
  <div class="sumgrid"><span>Çalışılan gün</span><b>${m.days} / 30</b><span>Yeni kelime</span><b>${m.n}</b><span>Kalıcı olan</span><b>${m.m}</b><span>Unutulan kalıcı</span><b>${m.fm}</b>
  <span>Ortalama doğruluk</span><b>${pctOr(m.acc)}</b><span>Bağlam doğruluğu</span><b>${pctOr(m.ctx)}</b><span>Eş anlam doğruluğu</span><b>${pctOr(m.syn)}</b><span>Okuma doğruluğu</span><b>${pctOr(m.read)}</b></div>
  <h3 class="eyebrow">Ustalık dağılımı</h3><div class="stackbar" aria-hidden="true">${Object.keys(colors).map(k=>`<i style="width:${dist[k]/tot*100}%;background:${colors[k]}"></i>`).join("")}</div>
  <div class="legend">${Object.keys(colors).map(k=>`<span style="--c:${colors[k]}">${STATUS[k]} %${Math.round(dist[k]/tot*100)}</span>`).join("")}</div></section>`;
}
/* Koç paneli: öz değerlendirme kalibrasyonu, Hard analizi, kişisel aralıklar, küme ve bağlaç ustalığı */
function vCoach(){
  const v=S.self.verify,kc=S.self.knowCtx,H=S.hardStats,sp=S.spacing;
  const hb=k=>H[k].n?`%${pct(H[k].ok/H[k].n)} <span class="muted small">(${H[k].n})</span>`:"–";
  const gs=Object.keys(GROUPS).map(g=>({g,...groupMastery(g)})).filter(x=>x.seen>=3).sort((a,b)=>b.score-a.score);
  const cd=Object.keys(CM_LABEL).map(k=>{const x=S.connDim[k];return{k,a:accOf(x),n:x?x.c+x.w:0}});
  const gl=x=>`<button class="chipbtn" data-act="cluster" data-v="${x.g}">${esc(GROUPS[x.g][1])} <span class="num">${x.score}</span></button>`;
  return`<section class="panel"><h2>Kelime koçu</h2>
  <h3 class="eyebrow">Kendini değerlendirme</h3>
  ${v.n?`<p class="small">Bildiğini düşündüğün kelimelerin %${pct(v.ok/v.n)}'ini sonraki soruda doğru tanıyorsun.${kc.n?` Bağlam sorularında bu oran %${pct(kc.ok/kc.n)}.`:""}</p>`:`<p class="small muted">Birkaç oturumdan sonra “Biliyorum” dediğin kelimelerin sonraki sorularda ne kadar doğrulandığı burada görünür.</p>`}
  ${gs.length?`<h3 class="eyebrow">Küme ustalığı</h3><div class="chips">${gs.slice(0,3).map(gl).join("")}</div>${gs.length>3?`<p class="small muted">Geliştirilecek kümeler:</p><div class="chips">${gs.slice(-3).reverse().map(gl).join("")}</div>`:""}`:""}
  </section>`;
}
function vProgress(){
  const s=stats(),t=today(),mem=memoryStats();
  const row=(l,v,cls,n)=>`<div class="brow"><span>${l}${n!=null?` <span class="muted small">(${n})</span>`:""}</span><span class="num">%${pct(v)}</span><div class="bar${cls?" "+cls:""}"><i style="width:${pct(v)}%"></i></div></div>`;
  const colors={new:"var(--line)",learning:"var(--accent)",familiar:"var(--fam)",weak:"var(--warn)",mastered:"var(--good)"};
  const stack=Object.keys(colors).map(k=>`<i style="width:${s.st[k]/W.length*100}%;background:${colors[k]}"></i>`).join("");
  const legend=Object.keys(colors).map(k=>`<span style="--c:${colors[k]}">${STATUS[k]} ${s.st[k]}</span>`).join("");
  const skills=Object.keys(SKILLS).map(k=>{const x=S.err[k],n=x.c+x.w;return n?row(`${SKILL_EN[k]} · ${SKILLS[k]}`,x.c/n,"g",n):""}).join("");
  const gr=Object.keys(S.grp).filter(g=>GROUPS[g]&&S.grp[g].c+S.grp[g].w>0).sort((a,b)=>(S.grp[b].c+S.grp[b].w)-(S.grp[a].c+S.grp[a].w)).slice(0,12)
    .map(g=>{const x=S.grp[g],n=x.c+x.w;return`<tr><td>${esc(GROUPS[g][1])} <span class="muted small">${esc(GROUPS[g][0])}</span></td><td class="r">${n}</td><td class="r">%${pct(x.c/n)}</td></tr>`}).join("");
  const days=[];for(let i=6;i>=0;i--){const d=t-i,x=S.days[d],dt=new Date(d*86400000);const n=x?((x.n||0)+(x.r||0)||x.q||0):0;days.push(`<div class="day"><i class="${x?"on":""}">${x?n:""}</i>${dt.toLocaleDateString("tr-TR",{weekday:"short",timeZone:"UTC"})}</div>`)}
  const weak=weakList();
  const confs=[];for(const a in S.conf)for(const b in S.conf[a])confs.push([a,b,S.conf[a][b]]);confs.sort((x,y)=>y[2]-x[2]);
  const ins=insights().map(i=>`<li class="${i.w?"warn":""}">${i.t}</li>`).join("");
  const mini=S.mini.slice(-6).reverse().map(m=>`<tr><td>${new Date(m.d*86400000).toLocaleDateString("tr-TR",{day:"numeric",month:"short",timeZone:"UTC"})}</td><td class="r">${m.n}</td><td class="r">${pct(m.c/m.n)}</td><td class="r">${Math.floor(m.secs/60)}:${String(m.secs%60).padStart(2,"0")}</td></tr>`).join("");
  const segN=n=>`<button data-act="npd" data-v="${n}" aria-pressed="${S.settings.newPerDay===n}">${n}</button>`;
  const segT=(k,l)=>`<button data-act="theme" data-v="${k}" aria-pressed="${S.settings.theme===k}">${l}</button>`;
  const segR=(k,l)=>`<button data-act="recall" data-v="${k}" aria-pressed="${S.settings.recall===k}">${l}</button>`;
  const debug=typeof location!=="undefined"&&location.hash==="#debug";
  return`<div class="stack">
  <div><div class="eyebrow">İlerleme</div><h1 class="sumhead" style="font-size:27px">Kişisel performans paneli</h1></div>
  <section class="tiles">
    <div class="stat"><span class="n">${W.length}</span><span class="l">Toplam kelime</span></div>
    <div class="stat"><span class="n">${s.st.learning+s.st.familiar}</span><span class="l">Öğreniliyor</span></div>
    <div class="stat weak"><span class="n">${s.st.weak}</span><span class="l">Zayıf</span></div>
    <div class="stat mast"><span class="n">${s.st.mastered}</span><span class="l">Kalıcı</span></div>
    <div class="stat"><span class="n">${s.due}</span><span class="l">Tekrar bekleyen</span></div>
    <div class="stat"><span class="n">${streakNow()}</span><span class="l">Seri · en iyi ${S.best||0} · son 30 günde ${days30()} / 30 gün</span></div>
  </section>
  ${mem?`<section class="panel"><h2>Hafıza durumu <small>· ${mem.n} kelime</small></h2><div class="bars">
    ${row("Ortalama ustalık puanı (masteryScore)",mem.mastery/100,"g")}${row("Depolama gücü · storage strength",mem.storage)}${row("Şu an hatırlama olasılığı · retrieval",mem.retrieval,mem.retrieval<.6?"w":"")}</div>
    <p class="note">Storage, kelimenin uzun süreli hafızadaki sağlamlığıdır ve tekrarla büyür. Retrieval, bugün hatırlama olasılığıdır; zamanla düşer. Tekrar sırası retrieval'a göre belirlenir.</p></section>`:""}
  <section class="panel"><h2>Kelime durumları</h2><div class="stackbar" aria-hidden="true">${stack}</div><div class="legend">${legend}</div>
    <p class="note">Kalıcı sayılmak için: en az 3 farklı günde doğru hatırlama, en az 1 eş anlam ve 1 bağlam sorusunu doğru yapma, son 3 tekrarın en az 2'sinde Good ya da Easy ve ustalık puanı en az 75. Puan zamanla düşer; 60'ın altına inerse kelime yeniden tekrara girer.</p></section>
  <section class="panel"><h2>YDS kelime kapsamı <small>· 5 seviye</small></h2>
    <div class="bars">${[1,2,3,4,5].map(l=>row(`L${l} ${LEVELS[l]} · ${LEVELS_TR[l]}`,s.lv[l],"",W.filter(w=>w.l===l).length)).join("")}</div>
    <div class="band"><span class="muted small">Current Vocabulary Stage</span><span class="n">${esc(s.stage)}</span></div>
    <p class="note">Seviyeler ydsPriorityScore'a göre belirlenir (sıklık, akademik kullanım, soru faydası, eş anlam ve okuma faydası). Bu değer yalnızca kelime kapsamını gösterir; YDS sınav puanı tahmini değildir.</p></section>
  <section class="panel"><h2>İçgörüler</h2><ul class="insights">${ins}</ul></section>
  ${vReady()}
  ${vMonth()}
  ${vCoach()}
  <section class="panel"><h2>Haftalık rapor</h2>${vWeekly()}</section>
  <section class="panel"><h2>Soru tipine göre başarı</h2>${skills?`<div class="bars">${skills}</div>`:`<p class="muted small">İlk oturumdan sonra anlam, eş anlam, bağlam, kalıp ve kelime ailesi başarın burada görünür.</p>`}</section>
  ${gr?`<section class="panel"><h2>Anlamsal kümelere göre</h2><div class="tablewrap"><table class="gtable"><tr><th>Küme</th><th class="r">Soru</th><th class="r">Doğru</th></tr>${gr}</table></div></section>`:""}
  <section class="panel"><h2>Son 7 gün</h2><div class="week">${days.join("")}</div><p class="note">Kutudaki sayı o gün çalışılan kelime sayısıdır (yalnızca test çözülen günlerde soru sayısı).</p></section>
  ${mini?`<section class="panel"><h2>Mini YDS geçmişi</h2><div class="tablewrap"><table class="gtable"><tr><th>Tarih</th><th class="r">Soru</th><th class="r">Puan</th><th class="r">Süre</th></tr>${mini}</table></div></section>`:""}
  <section class="panel"><h2>Zayıf kelimeler <small>· weak score</small></h2>
    ${weak.length?`<div class="chips">${weak.slice(0,30).map(id=>`<button class="chipbtn" data-act="detail" data-v="${esc(id)}">${esc(id)} <span class="num">${weakScore(id)}</span></button>`).join("")}</div>`:`<p class="muted small">Şu an zayıf kelime yok.</p>`}
    ${confs.length?`<p class="small muted">Karıştırdıkların: ${confs.slice(0,6).map(c=>`${esc(c[0])} ↔ ${esc(c[1])}`).join(", ")}</p>`:""}</section>
  <section class="panel"><h2>Ayarlar</h2>
    <div class="setrow"><span>Günlük yeni kelime (Normal süre)</span><span class="seg">${segN(5)}${segN(10)}${segN(15)}${segN(20)}${[5,10,15,20].includes(S.settings.newPerDay)?"":segN(S.settings.newPerDay)}</span></div>
    <div class="setrow"><span>Hatırlama biçimi</span><span class="seg">${segR("auto","Otomatik")}${segR("buttons","Butonlu")}${segR("open","Açık hatırlama")}</span></div>
    <p class="note">Açık hatırlama: anlamı zihninden söyler, sonra cevabı açarsın. Otomatik: oturmuş tekrarlarda açık hatırlama, yeni kelimelerde butonlar.</p>
    <div class="setrow"><span>Görünüm</span><span class="seg">${segT("system","Sistem")}${segT("light","Açık")}${segT("dark","Koyu")}</span></div>
  </section>
  <section class="panel"><h2>Yedek</h2>
    <div class="btn-row"><button class="btn btn-primary btn-sm" data-act="copybackup">Yedeği kopyala</button><button class="btn btn-ghost btn-sm" data-act="import">Yedeği yapıştır</button></div>
    <button class="link" data-act="export">Yedeği metin olarak göster (eski dışa aktarma)</button>
    <p class="note" id="backupmsg" role="status"></p>
    <div class="setrow"><span class="muted small">İlerleme bu tarayıcıda saklanır (veri sürümü v${S.dataVersion}).</span><button class="link" data-act="reset">İlerlemeyi sıfırla</button></div>
  </section>
  ${debug?vDebug():""}</div>`;
}
const DEVICE_CHECKS=["Dokunma alanları (≥ 40–44 px)","Yedeği kopyala (pano izni)","Yedeği yapıştır: JSON içe aktarma","Dosya seçici (.json)","Koyu mod kontrastı","Arama kutusunda klavye açılınca yerleşim","Soru geçişlerinde kaydırma konumu","Uzun panellerde (sheet) taşma ve kaydırma","Alt sekme çubuğu: güvenli alan (Home Indicator)","Çentik / safe-area üst boşluk","Yatay-dikey dönüş"];
function nOf(x){return x&&x.n?` <span class="muted small">n=${x.n}</span>`:` <span class="muted small">n=0</span>`}
function aOf(x){return x&&x.a!=null?"%"+pct(x.a):"Insufficient Data"}
function vRealCal(){
  const RC=realCalibration(),T=calibReport(),q=quadrants(),pc=x=>x==null?"–":"%"+pct(x);
  const row=(l,x)=>`<span>${l}</span><b>${aOf(x)}${nOf(x)}</b>`;
  const gap=(r,b)=>{const g=gapRate(r+":"+b);return`<td class="r">${g.n?`%${pct(g.a)}<br><span class="muted small">n=${g.n}</span>`:`<span class="muted small">n=0</span>`}</td>`};
  const rtb=["<3","3–7","7–15","15–30"].map(b=>{const x=S.rtNext[b];return`<tr><td>${b} sn</td><td class="r">${x&&x.c+x.w?"%"+pct(x.c/(x.c+x.w)):"–"}</td><td class="r">${x?x.c+x.w:0}</td></tr>`}).join("");
  const lee=taggedIds("Leech").map(id=>({id,r:leechReason(id)}));
  const mc=["7","30","60","90"].map(k=>{const x=S.mastCheck[k];return`<span>${k}. gün kontrolü</span><b>${x&&x.c+x.w?"%"+pct(x.c/(x.c+x.w)):"–"} <span class="muted small">n=${x?x.c+x.w:0}</span></b>`}).join("");
  const G=S.gapStats,lr=S.leechRec;
  const mock=S.mocks[S.mocks.length-1],Rd=readiness(),byR={};Rd.forEach(x=>byR[x.k]=x.v);
  const mm=(lab,key,v)=>{if(v==null)return"";const r=byR[key],warn=(r==="Strong"&&v<60)||(r==="Limited"&&v>80);return`<tr><td>${lab}</td><td>${r}</td><td class="r">%${v}</td><td>${warn?"⚠ uyumsuz":"✓"}</td></tr>`};
  const rec=recommendedChanges();
  const wp=Object.entries(S.wrongPicks).filter(([k,x])=>x.rep>=1);
  return`<section class="panel"><h2>REAL USER CALIBRATION</h2>
  <p class="small"><b>Calibration Day: ${RC.calDay}/30</b> · ${RC.status}${S.calStart!=null?` · başlangıç ${new Date(S.calStart*86400000).toLocaleDateString("tr-TR",{timeZone:"UTC"})}`:""}</p>
  <div class="sumgrid"><span>Study Days</span><b>${RC.studyDays}</b><span>Sessions Completed</span><b>${RC.sessions}</b><span>Total Reviews</span><b>${RC.reviews}</b><span>Unique Words Reviewed</span><b>${RC.unique}</b><span>New Words Learned</span><b>${RC.newWords}</b>
  <span>Recall Predictions (ort.)</span><b>${pc(RC.predicted)}</b><span>Actual Recall</span><b>${pc(RC.actual)}</b><span>Brier Score</span><b>${RC.brier.b==null?"–":RC.brier.b.toFixed(3)} · ${esc(RC.brier.l)}</b>
  ${row("Easy Recall",RC.easy)}${row("Good Recall",RC.good)}${row("Hard Recall",RC.hard)}${row("Hard 1-day",RC.hard1)}${row("Hard 3-day",RC.hard3)}${row("Hard 7-day",RC.hard7)}
  <span>Recognition Gaps</span><b>${RC.recog}</b><span>Recall Gaps</span><b>${RC.recall}</b><span>Leech Words</span><b>${RC.leech}</b><span>Fragile Mastered</span><b>${RC.fragile}</b><span>Forgotten Mastered</span><b>${RC.forgotten}</b>
  ${row("Reading Transfer",RC.readT)}${row("Cloze Transfer",RC.clzT)}${row("Mini YDS Vocabulary Transfer",RC.yvT)}${row("Immediate Transfer",RC.immediate)}${row("Delayed Transfer (3–7 gün)",RC.delayed)}
  <span>Average Session Duration</span><b>${RC.avgSecs==null?"–":Math.round(RC.avgSecs/60)+" dk"}</b><span>Completion Rate</span><b>${pc(RC.completion)}</b>
  <span>Storage Usage</span><b>${(RC.chars/1048576).toFixed(2)} M karakter · events ${RC.events} · aggregated ${RC.agg} gün</b></div>
  <h3 class="eyebrow">Recall calibration</h3><div class="tablewrap"><table class="gtable"><tr><th>Prediction</th><th class="r">Avg pred.</th><th class="r">Actual</th><th class="r">Samples</th><th class="r">Diff</th><th>Durum</th></tr>
  ${T.map(b=>`<tr><td>%${b.range}</td><td class="r">${pc(b.pred)}</td><td class="r">${pc(b.real)}</td><td class="r">n = ${b.n}</td><td class="r">${b.n?((b.real-b.pred)>=0?"+":"")+pct(b.real-b.pred)+"%":"–"}</td><td>${b.n<20?"yetersiz":Math.abs(b.real-b.pred)<=.1?"kalibre":"sapma"}</td></tr>`).join("")}</table></div>
  <h3 class="eyebrow">Puan sonrası gerçek hatırlama</h3><div class="tablewrap"><table class="gtable"><tr><th>Puan</th><th class="r">1 gün</th><th class="r">3 gün</th><th class="r">7 gün</th><th class="r">14 gün</th></tr>
  <tr><td>Easy</td>${gap("easy",1)}${gap("easy",3)}${gap("easy",7)}${gap("easy",14)}</tr><tr><td>Good</td>${gap("good",1)}${gap("good",3)}${gap("good",7)}${gap("good",14)}</tr><tr><td>Hard</td>${gap("hard",1)}${gap("hard",3)}${gap("hard",7)}<td class="r">–</td></tr></table></div>
  <h3 class="eyebrow">Çarpan değişiklik kaydı</h3><p class="small">${S.schedLog.length?S.schedLog.slice(-8).map(x=>`${new Date(x.t*86400000).toLocaleDateString("tr-TR",{timeZone:"UTC"})} · ${x.key}: ${x.from} → ${x.to} · gerçek %${pct(x.rate)} · hedef ${x.target||"–"} · n=${x.n} · ${x.reason||""}`).join("<br>"):"Değişiklik yok. Her puan türü için en az 20 geçerli gözlem; aynı çarpan 3 günden sık değişmez; adım ±%5; sınırlar Easy 0,80–1,30 · Good 0,80–1,25 · Hard 0,70–1,15."}</p>
  <h3 class="eyebrow">Tepki süresi → sonraki hatırlama</h3><div class="tablewrap"><table class="gtable"><tr><th>Doğru cevap süresi</th><th class="r">Sonraki hatırlama</th><th class="r">n</th></tr>${rtb}</table></div>
  <h3 class="eyebrow">Müdahale doğrulaması (14 gün sonra)</h3><p class="small">Recognition Gap: ${G.RG.n?`%${pct(G.RG.resolved/G.RG.n)} etiketten çıktı`:"Insufficient Data"} <span class="muted">n=${G.RG.n}</span><br>Recall Gap: ${G.RC.m?`doğrudan hatırlama %${pct(G.RC.before/G.RC.m)} → %${pct(G.RC.after/G.RC.m)}`:"Insufficient Data"} <span class="muted">n=${G.RC.m||0}</span> · etiketten çıkan ${G.RC.n?"%"+pct(G.RC.resolved/G.RC.n):"–"}</p>
  <h3 class="eyebrow">Leech</h3><p class="small">${lee.length?lee.slice(0,15).map(x=>`${esc(x.id)} — ${esc(x.r.tr)} <span class="muted">(${esc(x.r.r)}${x.r.d?": "+esc(x.r.d):""})</span>`).join("<br>"):"Leech yok."}<br>Özel kart sonrası: 1 gün ${rateOf(lr.d1).n?"%"+pct(rateOf(lr.d1).a):"–"} (n=${lr.d1.n}) · 3 gün ${rateOf(lr.d3).n?"%"+pct(rateOf(lr.d3).a):"–"} (n=${lr.d3.n}) · 7 gün ${rateOf(lr.d7).n?"%"+pct(rateOf(lr.d7).a):"–"} (n=${lr.d7.n}) · dinlenmeye alınan: ${S.leechRest}</p>
  <h3 class="eyebrow">Kalıcı kontrolleri</h3><div class="sumgrid">${mc}</div>
  <h3 class="eyebrow">Memory vs Transfer</h3><div class="sumgrid"><span>A · bellek yüksek, aktarım yüksek</span><b>${q.A}</b><span><b>B · bellek yüksek, aktarım düşük ⚠</b></span><b>${q.B}</b><span>C · bellek düşük, aktarım yüksek</span><b>${q.C}</b><span>D · ikisi de düşük</span><b>${q.D}</b><span>Aktarım verisi yok</span><b>${q.none}</b></div>
  ${S.quadHist.length>1?`<p class="small muted">Değişim: ${S.quadHist.slice(-7).map(x=>`${new Date(x.d*86400000).toLocaleDateString("tr-TR",{day:"numeric",month:"numeric",timeZone:"UTC"})} B=${x.B}`).join(" · ")}</p>`:""}
  ${q.B_ids.length?`<p class="small">B grubu (bağlam/okuma/cloze ile çalışılıyor): ${q.B_ids.slice(0,15).map(esc).join(", ")}</p>`:""}
  <h3 class="eyebrow">Readiness vs Mock Exam</h3>${mock?`<div class="tablewrap"><table class="gtable"><tr><th>Beceri</th><th>Uygulama</th><th class="r">Deneme</th><th></th></tr>${mm("Vocabulary","Vocabulary Readiness",mock.vocab)}${mm("Cloze","Cloze",mock.cloze)}${mm("Sentence Completion","Context",mock.sc)}${mm("Reading","Reading Transfer",mock.reading)}${mm("Toplam","Vocabulary Readiness",Math.round(mock.total/80*100))}</table></div>`:`<p class="small muted">Henüz deneme sonucu girilmedi.</p>`}
  <h3 class="eyebrow">Recommended Calibration Changes</h3>${RC.calDay<30?`<p class="small muted">30 çalışma günü dolmadan öneriler kesin değildir (şu an ${RC.calDay}/30).</p>`:""}${rec.length?`<ul class="small">${rec.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:`<p class="small muted">Yeterli veri yok; değişiklik önerilmiyor. scheduler-v2 korunur.</p>`}
  <p class="small muted">Öneriler otomatik uygulanmaz; onaydan sonra gerekiyorsa scheduler-v3 oluşturulur.</p>
  <h3 class="eyebrow">Soru kalitesi sinyalleri</h3><p class="small">Kullanıcı bildirimleri: ${S.flags.length?S.flags.slice(-10).map(f=>`${esc(f.q)} — ${esc(f.reason)}`).join("<br>"):"yok"}<br>Aynı yanlış seçeneğin tekrar seçildiği sorular: ${wp.length?wp.slice(0,10).map(([k,x])=>`${esc(k)} → “${esc(x.pick)}” (${x.rep+1}×)`).join("<br>"):"yok"}</p>
  <h3 class="eyebrow">Mini YDS eğilimi</h3>${(()=>{const mt=miniTrend();return mt?`<p class="small">${Object.keys(mt).filter(k=>Object.values(mt[k]).some(v=>v!=null)).map(k=>`${YT[k]}: ${[5,10,20].map(N=>mt[k][N]==null?"–":"%"+pct(mt[k][N])).join(" / ")}`).join("<br>")}</p>`:`<p class="small muted">En az 5 test gerekir (şu an ${S.mini.length}).</p>`})()}
  <h3 class="eyebrow">Performans kaydı</h3><p class="small">${S.perfLog.length?S.perfLog.map(x=>`Gün ${x.m}: ${(x.chars/1048576).toFixed(2)} M karakter · events ${x.events} · aggregated ${x.agg} · render ${x.renderMs} ms`).join("<br>"):"Henüz kayıt yok (1, 14, 30, 60, 90. çalışma günlerinde alınır)."}</p></section>`;
}
function vCalib(){
  const D=calibDashboard(),pc=x=>x==null?"–":"%"+pct(x);
  const hb=k=>D.hard[k].n?`%${pct(D.hard[k].ok/D.hard[k].n)} (${D.hard[k].n})`:"–";
  return`<section class="panel"><h2>Calibration Dashboard</h2>
  <p class="small ${D.ready?"":"muted"}">Gerçek kullanım verisi: ${D.days}/14 çalışma günü${D.ready?" — kalibrasyon yorumlanabilir.":" — büyük algoritma değişikliğinden önce en az 14 gün veri biriktirilmeli."} Algoritma: ${esc(D.alg)}${D.algHistory.length?` (önceki: ${D.algHistory.map(x=>esc(x.v)).join(", ")})`:""}</p>
  <div class="sumgrid"><span>Toplam tekrar</span><b>${D.reviews}</b><span>Tahmin hatası (Brier)</span><b>${D.brier==null?"–":D.brier.toFixed(3)}</b><span>Ortalama tepki süresi</span><b>${D.rt==null?"–":(D.rt/1000).toFixed(1)+" sn"}</b><span>Elenen uç süreler</span><b>${D.rtDropped}</b>
  <span>Hard 1 / 3 / 7 gün</span><b>${hb("d1")} · ${hb("d3")} · ${hb("d7")}</b><span>Easy sonrası hatırlama</span><b>${pc(D.easy)} (${D.tot.easy.n})</b><span>Good sonrası hatırlama</span><b>${pc(D.good)} (${D.tot.good.n})</b><span>Hard sonrası hatırlama</span><b>${pc(D.hardR)} (${D.tot.hard.n})</b>
  <span>Çarpanlar</span><b>E ×${D.spacing.easy.toFixed(2)} · G ×${D.spacing.good.toFixed(2)} · H ×${D.spacing.hard.toFixed(2)}</b><span>3–7 gün okuma aktarımı</span><b>${D.transfer37.n?`%${pct(D.transfer37.ok/D.transfer37.n)} (${D.transfer37.n})`:"–"}</b>
  <span>Kırılgan kalıcı kontrol</span><b>${D.fragileStats.n?`%${pct(D.fragileStats.ok/D.fragileStats.n)} (${D.fragileStats.n})`:"–"}</b><span>Sürpriz kontrol</span><b>${D.surprise.n?`%${pct(D.surprise.ok/D.surprise.n)} (${D.surprise.n})`:"–"}</b></div>
  <h3 class="eyebrow">Tahmin kalibrasyonu (recallProbability)</h3>
  <div class="tablewrap"><table class="gtable"><tr><th>Tahmin</th><th class="r">n</th><th class="r">Ort. tahmin</th><th class="r">Gerçek</th></tr>${D.calib.map(b=>`<tr><td>%${b.range}</td><td class="r">${b.n}</td><td class="r">${pc(b.pred)}</td><td class="r">${pc(b.real)}</td></tr>`).join("")}</table></div>
  <h3 class="eyebrow">Zamanlayıcı ayarları</h3><p class="small">${D.log.length?D.log.slice(-5).map(x=>`${x.key}: ×${x.from} → ×${x.to} (hatırlama %${pct(x.rate)}, n=${x.n})`).join("<br>"):"Henüz değişiklik yok (en az 20 örnek gerekir)."}</p>
  <p class="small">Leech: ${D.leech.length?D.leech.slice(0,12).map(esc).join(", "):"–"}<br>Recognition gap: ${D.recog.length?D.recog.slice(0,12).map(esc).join(", "):"–"}<br>Recall gap: ${D.recall.length?D.recall.slice(0,12).map(esc).join(", "):"–"}<br>Kırılgan kalıcı: ${D.fragile.length}<br>Kişisel karıştırma çiftleri: ${D.pairs.length?D.pairs.slice(0,8).map(p=>esc(p.ws.join("↔"))+" ("+p.n+")").join(", "):"–"}</p>
  <h3 class="eyebrow">Depolama</h3><p class="small">Tahmini kullanım: ${Math.round(D.chars/1024)} K karakter (~%${Math.round(100*D.chars/STORAGE_BUDGET)} / 5 M) · ayrıntılı olay: ${D.events} · özetlenmiş gün: ${D.agg}. 3,5 M karakterin üzerinde 30 günden eski olaylar, 4,2 M üzerinde 7 günden eskiler özetlenir; öğrenme durumu korunur.</p></section>`;
}
function vDebug(){
  const r=validateContent();
  return`<section class="panel"><h2>İçerik doğrulama (debug)</h2><p class="small">${r.passed}/${r.words} kelime geçti · ${r.errors.length} sorun · soru bankası ${r.bank}</p>
  ${r.errors.length?`<ul class="small">${Object.entries(r.byType).map(([k,n])=>`<li>${esc(k)}: ${n}</li>`).join("")}</ul>`:""}<p class="note">Ayrıntı için konsolda ydsValidate() çalıştır.</p></section>
  ${vRealCal()}
  ${vCalib()}
  <section class="panel"><h2>Gerçek cihaz kontrol listesi</h2><p class="small muted">Cihazlar: iPhone Safari · Android Chrome · Desktop Chrome · Desktop Firefox</p>
  <ul class="chk">${DEVICE_CHECKS.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></section>`;
}

function vAdvanced(id){
  const c=S.cards[id],t=today(),tf=transferScore(id),tags=wordTags(id),last={e:"Easy",g:"Good",h:"Hard",a:"Again"}[c.rat[c.rat.length-1]]||"–";
  const ex=c.reps+c.correct+c.wrong,okN=c.correct+c.rat.filter(x=>x==="g"||x==="e").length;
  const tI=c.trI&&c.trI.c+c.trI.w,tD=c.trD&&c.trD.c+c.trD.w;
  return`<details class="adv"><summary class="small">Gelişmiş ayrıntılar</summary><div class="sumgrid small">
  <span>Exposures</span><b>${ex}</b><span>Correct Recall</span><b>${okN}</b><span>Incorrect</span><b>${ex-okN}</b><span>Current Mastery</span><b>${masteryScore(id,t)}</b>
  <span>Transfer</span><b>${tf?tf.score:"–"}</b><span>Predicted Recall Today</span><b>%${pct(recallProbability(id,t))}</b><span>Last Rating</span><b>${last}</b><span>Next Review</span><b>${c.due<=t?"bugün":(c.due-t)+" gün"}</b>
  <span>Recognition Gap</span><b>${tags.has("RecognitionGap")?"Yes":"No"}</b><span>Recall Gap</span><b>${tags.has("RecallGap")?"Yes":"No"}</b>
  <span>Immediate Transfer</span><b>${tI?`%${pct(c.trI.c/tI)} (n=${tI})`:"–"}</b><span>Delayed Transfer</span><b>${tD?`%${pct(c.trD.c/tD)} (n=${tD})`:"–"}</b>
  ${tags.has("Leech")?`<span>Leech nedeni</span><b>${esc(leechReason(id).tr)}</b>`:""}${c.restUntil>t?`<span>Dinlenme</span><b>${c.restUntil-t} gün</b>`:""}</div></details>`;
}
function vDetail(id){
  const w=BY[id],c=S.cards[id],st=statusMap()[id],t=today();
  const due=c?(c.due<=t?"bugün":c.due===t+1?"yarın":`${c.due-t} gün sonra`):null;
  const m=mastery(c);const queued=S.queue.includes(id);
  const prof=Object.keys(SKILLS).map(k=>{const a=c&&accOf(c.sk[k]);return`<div>${SKILL_EN[k]}<b>${a==null?"–":"%"+pct(a)}</b></div>`}).join("");
  const sc=w.sc||{};
  const ms=c?masteryScore(id):0;
  return`<div class="sheet-top"><span class="pill ${st}">${STATUS[st]}</span><button class="iconbtn" data-act="close" aria-label="Kapat">×</button></div>
  <div class="card">${head(w,"")}${cardBody(w,true)}
  ${w.sv?`<p class="small"><span class="tag">destek kelimesi</span> Bağlaç öğretimi, karıştırılan çiftler ve kelime tuzakları için eklendi.</p>`:""}
  ${(LADBY[id]||[]).length?`<div class="sec"><h4>Anlam merdiveni</h4><div class="chips">${LADBY[id].map(L=>`<button class="chipbtn" data-act="ladderopen" data-v="${esc(L.id)}">${esc(L.title)}</button>`).join("")}</div><p class="small muted">${esc(useNote(id))}</p></div>`:""}
  ${isLink(w)&&c?`<div class="sec"><h4>Bağlaç ustalığı</h4><div class="prof">${Object.entries(connMastery(id)).map(([k,v])=>`<div>${CM_LABEL[k]}<b>${v==null?"–":v}</b></div>`).join("")}</div></div>`:""}
  ${c&&c.forgot?`<p class="small muted">Bu kelime ${c.forgot} kez kalıcı olduktan sonra zayıfladı; yeniden öğrenmede bağlam soruları öncelikli.</p>`:""}
  <div class="sec"><h4>Küme ve öncelik</h4><p class="small">${esc(GROUPS[w.g][0])} · ${esc(GROUPS[w.g][1])} · <button class="link" data-act="cluster" data-v="${esc(w.g)}">kümeyi aç</button></p>
    <p class="small muted">ydsPriorityScore <b class="num">${w.p}</b> · sıklık ${sc.frequency} · akademik ${sc.academicUse} · soru ${sc.questionUtility} · eş anlam ${sc.synonymUtility} · okuma ${sc.readingUtility}</p></div>
  ${c?`<div class="sec"><h4>Hafıza</h4><div class="prof"><div>Ustalık<b>${ms}</b></div><div>Depolama<b>%${pct(storageStr(c))}</b></div><div>Bugün hatırlama<b>%${pct(recallProbability(id,t))}</b></div></div>
    ${(()=>{const tf=transferScore(id);return`<div class="prof"><div>Memory mastery<b>${ms}</b></div><div>Transfer mastery<b>${tf?tf.score:"–"}</b></div><div>Tepki<b>${c.rt?(c.rt/1000).toFixed(1)+" sn":"–"}</b></div></div>${tf&&ms-tf.score>=20?`<p class="small muted">Kartta iyi biliyorsun ama sınav benzeri sorularda henüz aynı düzeyde değil; bağlam ve okuma soruları öncelikli.</p>`:""}`})()}
    <h4>Bilgi profili</h4><div class="prof">${prof}</div>
    <p class="small">Sonraki tekrar: <b>${due}</b> · Weak score ${weakScore(id)} · Doğru ${c.correct} · Yanlış ${c.wrong} · Unutma ${c.lapses}</p>
    <ul class="chk"><li class="${m.days?"ok":""}">3 farklı günde doğru (${c.cdays.length}/3)</li><li class="${m.syn?"ok":""}">Eş anlam sorusunda doğru</li><li class="${m.ctx?"ok":""}">Bağlam sorusunda doğru</li><li class="${m.rat?"ok":""}">Son 3 tekrarın 2'si Good / Easy</li><li class="${ms>=75?"ok":""}">Ustalık puanı ≥ 75 (${ms})</li></ul></div>`:""}
  </div>
  ${c?vAdvanced(id):""}
  ${!c?`<button class="btn ${queued?"btn-ghost":"btn-primary"}" data-act="queue" data-v="${esc(id)}">${queued?"Çalışma listende · listeden çıkar":"Bu kelimeyi çalışma listeme ekle"}</button>`:""}`;
}
const closeBtn=`<button class="iconbtn" data-act="close" aria-label="Kapat">×</button>`;
function vSheet(){
  if(!sheet)return"";let inner="";
  if(sheet.type==="detail")inner=vDetail(sheet.id);
  else if(sheet.type==="pair")inner=`<div class="sheet-top"><span class="eyebrow">Karıştırılan kelimeler</span>${closeBtn}</div>${vPairCard(PAIRS[sheet.i],false)}<button class="btn btn-primary" data-act="pairstudy" data-v="${sheet.i}">Mini teste başla</button>`;
  else if(sheet.type==="pairs")inner=`<div class="sheet-top"><h2 style="font-size:20px">Karıştırılan kelimeler</h2>${closeBtn}</div><div class="pairbtns">${PAIRS.map((p,i)=>`<button class="chipbtn" data-act="pair" data-v="${i}">${esc(p.ws.join(" / "))}</button>`).join("")}</div>`;
  else if(sheet.type==="clusters"){
    const gs=Object.keys(GROUPS).filter(g=>g[0]!=="l"&&W.some(w=>w.g===g));
    inner=`<div class="sheet-top"><h2 style="font-size:20px">Eş anlam kümeleri</h2>${closeBtn}</div><p class="small muted">Yakın anlamlı, ancak tamamen interchangeable değiller. Bir anlam merdiveni ya da küme seç.</p>
    <h3 class="eyebrow">Anlam merdivenleri · ${LADDERS.length}</h3>
    <div class="pairbtns">${LADDERS.map(L=>`<button class="chipbtn" data-act="ladderopen" data-v="${esc(L.id)}">${esc(L.title)} <span class="num">${clusterMastery(ladderWords(L)).score}</span></button>`).join("")}</div>
    <h3 class="eyebrow">Anlamsal kümeler</h3>
    <div class="pairbtns">${gs.map(g=>{const n=W.filter(w=>w.g===g).length,k=W.filter(w=>w.g===g&&S.cards[w.id]).length;return`<button class="chipbtn" data-act="cluster" data-v="${g}">${esc(GROUPS[g][0])} <span class="num">${k}/${n}</span></button>`}).join("")}</div>`;
  }else if(sheet.type==="ladder"){const L=LADDERS.find(x=>x.id===sheet.id);inner=`<div class="sheet-top"><span class="eyebrow">Anlam merdiveni</span>${closeBtn}</div>${vSemLadder(L)}<button class="btn btn-primary" data-act="ladderstudy" data-v="${esc(L.id)}">Bu merdiveni çalış</button>`}
  else if(sheet.type==="cluster")inner=`<div class="sheet-top"><span class="eyebrow">Eş anlam kümesi</span>${closeBtn}</div>${vLadder(sheet.g)}<button class="btn btn-primary" data-act="clusterstudy" data-v="${esc(sheet.g)}">Bu kümeyi çalış</button>`;
  else if(sheet.type==="conn"){
    const gs=Object.keys(CONN_FN);
    inner=`<div class="sheet-top"><h2 style="font-size:20px">Bağlaç ustası</h2>${closeBtn}</div><p class="small muted">Her bağlacın anlamı, ardından gelen yapı, cümledeki yeri ve noktalaması. YDS'de en sık tuzak: despite + isim / V-ing ↔ although + özne + yüklem.</p>
    ${gs.map(g=>`<div class="cgroup"><div class="gtitle"><h3>${esc(GROUPS[g][0])}</h3><button class="link" data-act="connstudy" data-v="${g}">çalış</button></div><table class="gtable"><tr><th>Bağlaç</th><th>Yapı</th></tr>${W.filter(w=>w.g===g&&w.cn).map(w=>`<tr><td><button class="link" data-act="detail" data-v="${esc(w.id)}">${esc(w.w)}</button> <span class="muted small">${esc(w.tr.split(" / ")[0])}</span></td><td class="small">${esc(STRUCT_SHORT[w.cn.struct])}</td></tr>`).join("")}</table></div>`).join("")}
    <button class="btn btn-primary" data-act="connstudy">Karışık bağlaç testi</button>`;
  }else if(sheet.type==="mock")inner=`<div class="sheet-top"><h2 style="font-size:20px">Deneme sonucumu ekle</h2>${closeBtn}</div>
    <p class="small muted">İsteğe bağlı. Bu bilgi puan tahmini için kullanılmaz; yalnızca uygulama içi göstergelerin gerçek denemeyle uyumunu görmek için saklanır. Yalnızca toplamı biliyorsan diğer alanları boş bırak.</p>
    <div class="form"><label>Tarih<input type="date" id="mk_d" value="${new Date(today()*86400000).toISOString().slice(0,10)}"></label>
    <label>Toplam doğru (80 soruda)<input type="number" id="mk_t" min="0" max="80" inputmode="numeric"></label>
    <label>Vocabulary %<input type="number" id="mk_v" min="0" max="100" inputmode="numeric"></label><label>Cloze %<input type="number" id="mk_c" min="0" max="100" inputmode="numeric"></label>
    <label>Sentence Completion %<input type="number" id="mk_s" min="0" max="100" inputmode="numeric"></label><label>Reading %<input type="number" id="mk_r" min="0" max="100" inputmode="numeric"></label></div>
    ${sheet.msg?`<p class="msg bad" role="status">${esc(sheet.msg)}</p>`:""}<button class="btn btn-primary" data-act="mocksave">Kaydet</button>`;
  else if(sheet.type==="flag")inner=`<div class="sheet-top"><h2 style="font-size:20px">Bu soruda sorun var</h2>${closeBtn}</div>
    <p class="small muted">Bildirim yalnızca bu cihazda saklanır; açıklama zorunlu değil.</p>
    <div class="opts">${["Birden fazla doğru olabilir","Cümle doğal değil","Çeviri sorunlu","Cevabı anlamadım","Diğer"].map(r=>`<button class="opt" data-act="flagsave" data-v="${esc(r)}"><span>${esc(r)}</span></button>`).join("")}</div>
    <input type="text" id="flagnote" class="search" placeholder="İstersen kısa not (isteğe bağlı)" aria-label="Kısa not">`;
  else if(sheet.type==="report30"){const r=report30(),pc=x=>x==null?"–":"%"+pct(x),ra=x=>x&&x.a!=null?`%${pct(x.a)} (n=${x.n})`:"Insufficient Data";
    inner=`<div class="sheet-top"><h2 style="font-size:20px">30 günlük öğrenme raporu</h2>${closeBtn}</div>
    <div class="sumgrid"><span>Çalışılan gün</span><b>${r.studyDays}</b><span>Toplam çalışma</span><b>${r.studyMin} dk</b><span>Tanıtılan kelime</span><b>${r.introduced}</b><span>Kalıcı olan</span><b>${r.mastered}</b><span>Kalıcıyken unutulan</span><b>${r.forgotten}</b><span>Tamamlanan tekrar</span><b>${r.reviews}</b>
    <span>Bellek doğruluğu</span><b>${pc(r.memory)}</b><span>Aktarım doğruluğu</span><b>${pc(r.transfer)}</b><span>Gecikmeli aktarım</span><b>${ra(r.delayed)}</b>
    <span>Easy / Good / Hard hatırlama</span><b>${ra(r.easy)} · ${ra(r.good)} · ${ra(r.hard)}</b><span>Okuma / Cloze doğruluğu</span><b>${pc(r.reading)} · ${pc(r.cloze)}</b>
    <span>Recognition / Recall gap · Leech</span><b>${r.recog} · ${r.recall} · ${r.leech}</b><span>Tahmin kalibrasyonu</span><b>${esc(r.brier.l)}</b>
    <span>Önerilen günlük yeni kelime</span><b>${r.newRec.ready?r.newRec.rec:"Insufficient Data"}</b><span>Önerilen oturum süresi</span><b>${r.lenRec?esc(r.lenRec):"mevcut süre uygun"}</b></div>
    <h3 class="eyebrow">En güçlü / en zayıf kümeler</h3><p class="small">${r.best.map(x=>esc(GROUPS[x.g][1])+" "+x.score).join(" · ")||"–"}<br>${r.weakest.map(x=>esc(GROUPS[x.g][1])+" "+x.score).join(" · ")||"–"}</p>
    <h3 class="eyebrow">Algoritmada değiştirilmesi önerilenler</h3>${r.changes.length?`<ul class="small">${r.changes.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`:`<p class="small muted">Veri, değişiklik gerektirmiyor ya da henüz yeterli değil.</p>`}
    <p class="note">Öneriler otomatik uygulanmaz.</p>`
  }else if(sheet.type==="weekly")inner=`<div class="sheet-top"><h2 style="font-size:20px">Haftalık rapor</h2>${closeBtn}</div>${vWeekly()}`;
  else if(sheet.type==="yds"){
    const last=S.mini.slice(-1)[0];
    inner=`<div class="sheet-top"><h2 style="font-size:20px">Mini YDS</h2>${closeBtn}</div>
    <p class="muted">${BANK.length+RD.length} soruluk banka: Vocabulary, Cloze Test, Sentence Completion, Translation, Restatement, Paragraph Completion ve Reading. Doğru cevaplar A–E arasında dengeli dağılır; test sonunda her soru için öğrenme modu açılır.</p>
    <div class="opts">${[5,10,20,40].map(n=>`<button class="opt" data-act="ydsstart" data-v="${n}"><span class="k">${n}</span><span>${n} soru · yaklaşık ${Math.round(n*1.3)} dk</span></button>`).join("")}</div>
    ${last?`<p class="note">Son test: ${last.c}/${last.n} doğru.</p>`:""}`;
  }else if(sheet.type==="export"){
    inner=`<div class="sheet-top"><h2 style="font-size:20px">Yedeği kopyala</h2>${closeBtn}</div>
    <p class="muted small">${sheet.auto?"Otomatik kopyalama bu tarayıcıda çalışmadı. Metin seçildi; kopyala komutunu kullan.":"Bu metni kopyalayıp güvenli bir yere (not, e-posta) kaydet."} Başka cihazda “Yedeği yapıştır” ile yükleyebilirsin.</p>
    <textarea id="exportbox" readonly aria-label="Yedek metni">${esc(exportText())}</textarea>
    <button class="btn btn-primary" data-act="copybox">Kopyala</button>`;
  }else if(sheet.type==="import"){
    inner=`<div class="sheet-top"><h2 style="font-size:20px">Yedeği yapıştır</h2>${closeBtn}</div>
    <p class="muted small">Kopyaladığın yedek metnini yapıştır ya da kaydettiğin .json dosyasını seç. Önce kontrol edilir; hatalı yedek mevcut verine dokunmaz.</p>
    <textarea id="importbox" aria-label="Yedek metni" placeholder='{"app":"YDS Kelime Atölyesi", ...}'>${esc(sheet.text||"")}</textarea>
    <input type="file" id="importfile" accept=".json,application/json,text/plain" aria-label="Dosya seç">
    ${sheet.msg?`<p class="msg ${sheet.ok?"ok":"bad"}" role="status">${esc(sheet.msg)}</p>`:""}
    ${sheet.undo?`<button class="btn btn-ghost" data-act="undoimport">İçe aktarmayı geri al</button>`:""}
    ${sheet.pending?`<p class="small">${esc(sheet.pending.summary)}</p><div class="btn-row"><button class="btn btn-ghost" data-act="close">Vazgeç</button><button class="btn btn-danger" data-act="importconfirm">Yerine geçir</button></div>`:sheet.undo?"":`<button class="btn btn-primary" data-act="importcheck">Kontrol et</button>`}`;
  }else if(sheet.type==="confirm"){
    const m={exit:["Oturumdan çıkılsın mı?","Şimdiye kadar puanladığın kelimeler ve cevapların kaydedildi. Kalan adımlar bugünkü listede bekler.","Çık","btn-primary"],reset:["Tüm ilerleme silinsin mi?","Öğrenilen kelimeler, tekrar programı, favoriler ve istatistikler bu tarayıcıdan silinir. Önce yedeği kopyalamanı öneririz. Bu işlem geri alınamaz.","Sıfırla","btn-danger"]}[sheet.what];
    inner=`<h2 style="font-size:20px">${m[0]}</h2><p class="muted">${m[1]}</p><div class="btn-row"><button class="btn btn-ghost" data-act="close">Vazgeç</button><button class="btn ${m[3]}" data-act="confirm">${m[2]}</button></div>`;
  }
  return`<div class="sheet-back" data-act="backdrop"><div class="sheet" role="dialog" aria-modal="true">${inner}</div></div>`;
}

const $app=document.getElementById("app"),$sheet=document.getElementById("sheet");
function applyTheme(){const r=document.documentElement;if(S.settings.theme==="system")r.removeAttribute("data-theme");else r.setAttribute("data-theme",S.settings.theme)}
function render(){
  applyTheme();
  let html;
  if(!SS&&needsOnboarding()&&tab==="home")html=vOnboard();else if(SS)html=vSession();else if(tab==="summary")html=vSummary();else if(tab==="words")html=vWords();else if(tab==="progress")html=vProgress();else if(tab==="study")html=vStudy();else html=vHome();
  $app.innerHTML=html;renderSheet();
  document.querySelectorAll("#tabs .tab").forEach(b=>{if(b.dataset.v===tab)b.setAttribute("aria-current","page");else b.removeAttribute("aria-current")});
  if(SS&&SS.ans!==null){const nb=document.getElementById("nextbtn");if(nb&&nb.focus)nb.focus({preventScroll:true})}
}
function renderSheet(){$sheet.innerHTML=vSheet()}
function backupMsg(t){const el=document.getElementById("backupmsg");if(el)el.textContent=t}
function doImport(state){
  try{localStorage.setItem(KEY+".undo",JSON.stringify(S))}catch(e){}
  S=state;REV++;save();flush();summary=null;
}
function undoImport(){
  try{const r=localStorage.getItem(KEY+".undo");if(!r)return false;S=migrate(JSON.parse(r));REV++;save();flush();localStorage.removeItem&&localStorage.removeItem(KEY+".undo");return true}catch(e){return false}
}

/* ================= OLAYLAR ================= */
document.addEventListener("click",e=>{
  const el=e.target.closest("[data-act]");if(!el)return;
  const a=el.dataset.act,v=el.dataset.v;
  if(a==="backdrop"){if(e.target===el){sheet=null;renderSheet()}return}
  switch(a){
    case"tab":tab=v;sheet=null;render();window.scrollTo(0,0);break;
    case"start":startSession("daily");break;
    case"extra":startSession("extra");break;
    case"quick":startSession("quick");break;
    case"weak":startSession("weak");break;
    case"favstudy":startSession("fav");break;
    case"pairstudy":startSession("pair",+v);break;
    case"trap":startSession("trap");break;
    case"read":startSession("read");break;
    case"clz":startSession("clz");break;
    case"connstudy":startSession("conn",v||null);break;
    case"clusterstudy":startSession("cluster",v);break;
    case"ladderstudy":startSession("ladder",v);break;
    case"ladderopen":sheet={type:"ladder",id:v};renderSheet();break;
    case"place":startSession("place");break;
    case"orate":{const map={know:"good",unsure:"hard",dunno:"again",easy:"easy"};SS.self=v==="easy"?"know":v;rate(map[v]);break}
    case"ob":obStep(v);break;
    case"mockopen":sheet={type:"mock"};renderSheet();break;
    case"report30":sheet={type:"report30"};renderSheet();break;
    case"flagopen":sheet={type:"flag"};renderSheet();break;
    case"flagsave":{const it=cur();const note=(document.getElementById("flagnote")||{}).value||"";S.flags.push({q:it?qKey(it):"?",k:it&&it.k,reason:v,note:note.slice(0,200),d:today()});if(S.flags.length>300)S.flags.shift();SS.flagged=true;save();sheet=null;render();announce("Bildirim kaydedildi.");break}
    case"mocksave":{const g=id=>{const el=document.getElementById(id);const x=el&&el.value!==""?+el.value:null;return x==null||isNaN(x)?null:x};
      const tot=g("mk_t");if(tot==null||tot<0||tot>80){sheet.msg="Toplam doğru 0–80 arasında olmalı.";renderSheet();break}
      const pcts=["mk_v","mk_c","mk_s","mk_r"].map(g);if(pcts.some(x=>x!=null&&(x<0||x>100))){sheet.msg="Yüzdeler 0–100 arasında olmalı.";renderSheet();break}
      const dv=(document.getElementById("mk_d")||{}).value;const day=dv?Math.floor(Date.parse(dv)/86400000):today();
      S.mocks.push({d:day,total:tot,vocab:pcts[0],cloze:pcts[1],sc:pcts[2],reading:pcts[3]});save();sheet=null;render();announce("Deneme sonucu kaydedildi.");break}
    case"ydsopen":sheet={type:"yds"};render();break;
    case"ydsstart":startSession("yds",+v);break;
    case"pairsopen":sheet={type:"pairs"};renderSheet();break;
    case"clusters":sheet={type:"clusters"};renderSheet();break;
    case"cluster":sheet={type:"cluster",g:v};renderSheet();break;
    case"connopen":sheet={type:"conn"};renderSheet();break;
    case"weekly":sheet={type:"weekly"};S.weeklySeen=today();save();renderSheet();break;
    case"len":S.settings.length=v;save();render();break;
    case"nonew":S.noNewDay=S.noNewDay===today()?null:today();save();render();break;
    case"self":markReveal();SS.self=v;SS.stage="back";render();break;
    case"reveal":markReveal();SS.stage="back";render();break;
    case"rev":record(cur(),v==="1",null);next();break;
    case"rate":rate(v);break;
    case"famopen":SS.fam=true;render();break;
    case"ans":answer(+v);break;
    case"next":next();break;
    case"fav":{S.fav=isFav(v)?S.fav.filter(x=>x!==v):[...S.fav,v];save();render();break}
    case"queue":S.queue=S.queue.includes(v)?S.queue.filter(x=>x!==v):[...S.queue,v];save();renderSheet();break;
    case"exit":sheet={type:"confirm",what:"exit"};renderSheet();break;
    case"reset":sheet={type:"confirm",what:"reset"};renderSheet();break;
    case"confirm":if(sheet.what==="exit")exitSession();else{try{localStorage.setItem(KEY+".undo",JSON.stringify(S))}catch(err){}S=blankState();REV++;save();flush();sheet=null;summary=null;tab="home";render()}break;
    case"close":sheet=null;renderSheet();break;
    case"detail":sheet={type:"detail",id:v};renderSheet();break;
    case"pair":sheet={type:"pair",i:+v};renderSheet();break;
    case"wf":wf=v;wlimit=120;render();break;
    case"more":wlimit+=150;render();break;
    case"npd":S.settings.newPerDay=+v;save();render();break;
    case"recall":S.settings.recall=v;save();render();break;
    case"theme":S.settings.theme=v;save();render();break;
    case"copybackup":{flush();const txt=exportText();
      const fail=()=>{sheet={type:"export",auto:true};renderSheet();const b=document.getElementById("exportbox");if(b){b.focus();b.select()}};
      try{navigator.clipboard.writeText(txt).then(()=>{backupMsg(`Yedek kopyalandı (${Math.round(txt.length/1024)} KB). Güvenli bir yere yapıştır.`);announce("Yedek kopyalandı.")},fail)}catch(err){fail()}break}
    case"import":sheet={type:"import"};renderSheet();break;
    case"export":flush();sheet={type:"export"};renderSheet();break;
    case"copybox":{const b=document.getElementById("exportbox");const txt=b?b.value:exportText();try{navigator.clipboard.writeText(txt).then(()=>announce("Yedek kopyalandı."),()=>{b.focus();b.select()})}catch(err){b.focus();b.select()}break}
    case"importcheck":{const txt=document.getElementById("importbox").value.trim();sheet.text=txt;
      if(!txt){sheet.msg="Önce yedek metnini yapıştır ya da bir dosya seç.";sheet.ok=false;renderSheet();break}
      try{sheet.pending=validateBackup(txt);sheet.msg="Yedek geçerli.";sheet.ok=true}catch(err){sheet.pending=null;sheet.msg=err.message+" Mevcut verin değişmedi.";sheet.ok=false}renderSheet();break}
    case"importconfirm":doImport(sheet.pending.state);sheet={type:"import",msg:"Yedek içe aktarıldı. Önceki durum geri alma için saklandı.",ok:true,undo:true};render();break;
    case"undoimport":{const ok=undoImport();sheet={type:"import",msg:ok?"İçe aktarma geri alındı.":"Geri alınacak kayıt bulunamadı.",ok};render();break}
  }
});
document.addEventListener("input",e=>{
  if(e.target.id==="wsearch"){wq=e.target.value;const q=wq.trim().toLocaleLowerCase("tr-TR");
    document.getElementById("wresults").innerHTML=vWordResults(q,WFILT[wf]||WFILT.all)}
});
document.addEventListener("change",e=>{
  if(e.target.id==="importfile"&&e.target.files&&e.target.files[0]){const r=new FileReader();r.onload=()=>{sheet.text=String(r.result);try{sheet.pending=validateBackup(sheet.text);sheet.msg="Dosya okundu, yedek geçerli.";sheet.ok=true}catch(err){sheet.pending=null;sheet.msg=err.message+" Mevcut verin değişmedi.";sheet.ok=false}renderSheet()};r.onerror=()=>{sheet.msg="Dosya okunamadı.";sheet.ok=false;renderSheet()};r.readAsText(e.target.files[0])}
});
document.addEventListener("keydown",e=>{
  if(e.key==="Escape"&&sheet){sheet=null;renderSheet();return}
  if(!SS||sheet||e.metaKey||e.ctrlKey||e.altKey)return;
  const tag=(e.target.tagName||"").toLowerCase();if(tag==="input"||tag==="textarea")return;
  const it=cur();const k=e.key.toLowerCase();
  if(it.k==="flash"||it.k==="learn"||it.k==="connfo"){
    if(SS.stage==="front"){
      if(recallMode(it)==="open"){if(k===" "||k==="enter"){e.preventDefault();SS.stage="back";render()}}
      else{const m={"1":"know","2":"unsure","3":"dunno"};if(m[k]){e.preventDefault();SS.self=m[k];SS.stage="back";render()}}}
    else if(it.open){const m={"1":"dunno","2":"unsure","3":"know","4":"easy"};if(m[k]){e.preventDefault();const map={know:"good",unsure:"hard",dunno:"again",easy:"easy"};SS.self=m[k]==="easy"?"know":m[k];rate(map[m[k]])}}
    else{const m={"1":"again","2":"hard","3":"good","4":"easy"};if(m[k]){e.preventDefault();rate(m[k])}}
  }else if(it.k==="reverse"){
    if(SS.stage==="front"){if(k===" "||k==="enter"){e.preventDefault();SS.stage="back";render()}}
    else if(k==="1"||k==="2"){e.preventDefault();record(it,k==="2",null);next()}
  }else if(it.k==="pair"||it.k==="ladder"||it.k==="passage"||it.k==="leech"){if(k==="enter"||k===" "){e.preventDefault();next()}}
  else if(it.opts){
    if(SS.ans===null){let i="abcde".indexOf(k);if(i<0)i="12345".indexOf(k);if(i>=0&&i<it.opts.length){e.preventDefault();answer(i)}}
    else if(k==="enter"||k===" "){if(e.target&&e.target.id==="nextbtn")return;e.preventDefault();next()}
  }
});
if(typeof window!=="undefined"&&window.addEventListener){window.addEventListener("pagehide",flush);document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="hidden"){if(SS)SS.hid=true;flush()}})}
render();
